A révházban pihennek, alusznak.','Szalkszentmárton, 1846. április 10-24.',1846,'1846',array['Szerelem','Természet','Elmúlás']::text[],'{}'::text[],false,482,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184603-81','petofi','Zöldleveles, fehér...','Zöldleveles, fehér
Virágos ákácfa,
Kék ruhában szőke
Kislyány van alatta;
Megeredt az eső,
Annak végét várja,
A pitvarajtóból
Kacsintgatok rája.

Gyere be, galambom,
Gyere a szobánkba!
Míg eláll az eső,
Űlj föl a ládánkra;
Ha magas a láda,
Rája fölültetlek,
Ha kemény az űlés,
Az ölembe veszlek.','Zöldleveles, fehér
Virágos ákácfa,
Kék ruhában szőke
Kislyány van alatta;','Szalkszentmárton, 1846. április 10-24.',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,483,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184603-82','petofi','Rég elhuzták az esteli harangot...','Rég elhuzták az esteli
Harangot.
Ki az, aki még mostan is
Barangol?
Csak én járok a faluban
Egyedül.
Keresem az álmot, de az
Elkerűl.

Fönn van a hold, fönn vannak a
Csillagok;
Mind megannyi szép leányszem,
Ugy ragyog.
Sötét árnyat vetnek a fák,
A házak,
Unalmokban egyebet sem
Csinálnak.

Amott egy ház, a tetején
Két gólya,
Alant egy pár ember a kis
Ajtóba''...
Legény, leány - amaz szőke,
Ez barna,
Legény a lyányt subájába
Takarja.

Mellettök mentem el, észre
Sem vettek.
Én istenem, be boldogok
Lehetnek!
Nem irígylem, de mégis jobb
Szeretném,
Ha azt a kis barna lyányt én
Ölelném!','Rég elhuzták az esteli
Harangot.
Ki az, aki még mostan is
Barangol?','Szalkszentmárton, 1846. április 10-24.',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,484,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184603-83','petofi','A jó aggastyán','Béranger után franciából

Vidám fiúk, kik bornál egyesűltök,
Közétek bájol engem dalotok.
Öreg vagyok, de bárha reszket hangom,
Fogadjatok be, én is danolok.
A múlt időkről újakat beszélek;
A vén Panarddal én együtt ivám.
Bor és dicsőség s szerelem baráti,
Mosolygjatok az aggastyán dalán.

Mi ez? mind vágytok engem ünnepelni?
Nemes bor ömlik egészségemért.
E fogadásra büszke szívem, mely fél,
Mely attól tart, hogy mást csak szomorít.
Csak hadd födözzön a vidámság szárnya,
Idővel úgyis máskép lesztek ám!
Bor és dicsőség s szerelem baráti,
Mosolygjatok az aggastyán dalán.

Miként ti most, és is szerelmeskedtem;
Szólhatnak erről nagyanyáitok.
Házam, barátim, kedvesim valának,
Ezek közül már semmit sem birok.
Emlékeim maradtak meg csak; olykor
Sohajtok is, ha más nem néz reám.
Bor és dicsőség s szerelem baráti,
Mosolygjatok az aggastyán dalán.

Volt vészeinkben több hajótörésem,
De Frankhon szép egét nem hagytam el.
Azt a kevés bort, melyet megmentettem,
Sértett kevélység nem zavarja fel,
Sőt énekeltem az új szüretekben
Egykor tulajdon hegyem oldalán.
Bor és dicsőség s szerelem baráti,
Mosolygjatok az aggastyán dalán.

Egy elmult kornak régi katonája,
Mint Nestor nektek nem beszélek én.
Egész időm, hol fénylett bátorságom,
Egy harcotokkal fölcseréleném.
Sőt halhatatlan hősiségtek által
Egy új zászló mellé csatoltatám.
Bor és dicsőség s szerelem baráti,
Mosolygjatok az aggastyán dalán.

Milyen jövendőt biztosít erénytek!
Éltessük, ifjak, végszerelmemet.
Szabadságában a világ megújul,
Jobb napok járnak majd sirom felett.
Kedves fecskéi ti egy szép tavasznak,
Hogy lássalak, azért nem távozám,
Bor és dicsőség s szerelem baráti,
Mosolygjatok az aggastyán dalán.','Béranger után franciából
Vidám fiúk, kik bornál egyesűltök,
Közétek bájol engem dalotok.
Öreg vagyok, de bárha reszket hangom,','Pest, 1846. április 24-30.',1846,'1846',array['Szerelem','Természet']::text[],'{}'::text[],false,485,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184603-84','petofi','Világgyűlölet','Mennybéli isten, ördög és pokol!
Mivé lett a föld, s még mivé lehet?
Minden bokorban egy világfaló
Minden bokorban embergyűlölet.

Gyűlölnek ők, és átkaik kövét
Dobálják szerte irgalmatlanul,
Ugy dől belőlük az átok, miként
Rothadt szag a sirok nyilásibul.

Szerettetek-e, fickók, valaha,
Hogy most gyülöltök? s imádkoztatok
Az emberiség boldogságaért,
Hogy most lehessen átkozódnotok?

Elkérték kebletekből a szivet
S aztán széttépték azt az emberek?
Nem, a világnak ti nem adtatok
Szívet soha, mert nincsen szívetek!

Nincs bennetek szív, nincs! csak zsebetek
És gyomrotok van, s mert ez nincs tele,
Azért rút a világ előttetek,
Azért keltek ki rútul ellene.

Én is gyűlöltem... volt okom reá;
De amióta e bitangokat
Láttam, mint vágnak Byronképeket,
Azóta gyűlölségem megszakadt.

Mióta ők a földi életet
Oly feketére mázolják: nekem
Sokkal, de sokkal jobban tetszik az,
Több fénypontot vesz észre rajt szemem.

Valóban szép, igen szép a világ;
Van minden évben rajta kikelet,
S van szép leánya minden falunak,
S ha itt egy ember sír, ott más nevet.

Mily tréfás még maga a bánat is!
Szív s fejre mily különbözőleg hat;
Sötétre festi a fehér szivet,
S fehérre festi a sötét hajat.','Mennybéli isten, ördög és pokol!
Mivé lett a föld, s még mivé lehet?
Minden bokorban egy világfaló
Minden bokorban embergyűlölet.','Pest, 1846. április 24-30.',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,486,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184603-85','petofi','Sors, nyiss nekem tért...','Sors, nyiss nekem tért, hadd tehessek
Az emberiségért valamit!
Ne hamvadjon ki haszon nélkűl e
Nemes láng, amely úgy hevit.

Láng van szivemben, égbül-eredt láng,
Fölforraló minden csepp vért;
Minden szív-ütésem egy imádság
A világ boldogságaért.

Oh vajha nemcsak üres beszéddel,
De tettel mondhatnám el ezt!
Legyen bár tettemért a díj egy
Uj Golgotán egy új kereszt!

Meghalni az emberiség javáért!
Mily boldog, milyen szép halál!
Szebb s boldogítóbb egy hasztalan élet
Minden kéjmámorainál.

Mondd, sors, oh mondd ki, hogy így halok meg,
Ily szentül!... s én elkészítem
Saját kezemmel azon keresztfát,
Amelyre fölfeszíttetem.','Sors, nyiss nekem tért, hadd tehessek
Az emberiségért valamit!
Ne hamvadjon ki haszon nélkűl e
Nemes láng, amely úgy hevit.','Pest, 1846. április 24-30.',1846,'1846',array['Elmúlás']::text[],'{}'::text[],false,487,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184603-86','petofi','Dalaim','Elmerengek gondolkodva gyakran,
S nem tudom, hogy mi gondolatom van,
Átröpűlök hosszában hazámon,
Át a földön, az egész világon.
Dalaim, mik ilyenkor teremnek,
Holdsugári ábrándos lelkemnek.

A helyett, hogy ábrándoknak élek,
Tán jobb volna élnem a jövőnek,
S gondoskodnom... eh, mért gondoskodnám?
Jó az isten, majd gondot visel rám.
Dalaim, mik ilyenkor teremnek,
Pillangói könnyelmű lelkemnek.

Ha szép lyánnyal van találkozásom,
Gondomat még mélyebb sírba ásom,
S mélyen nézek a szép lyány szemébe,
Mint a csillag csendes tó vizébe.
Dalaim, mik ilyenkor teremnek,
Vadrózsái szerelmes lelkemnek.

Szeret a lyány? iszom örömömben,
Nem szeret? kell inni keservemben.
S hol pohár és a pohárban bor van,
Tarka jókedv születik meg ottan.
Dalaim, mik ilyenkor teremnek,
Szivárványi mámoros lelkemnek.

Oh de míg a pohár van kezemben,
Nemzeteknek keze van bilincsben,
S amilyen víg a pohár csengése,
Olyan bús a rabbilincs csörgése.
Dalaim, mik ilyenkor teremnek,
Fellegei bánatos lelkemnek.

De mit tűr a szolgaságnak népe?
Mért nem kél föl, hogy láncát letépje?
Arra vár, hogy isten kegyelméből
Azt a rozsda rágja le kezéről?
Dalaim, mik ilyenkor teremnek,
Villámlási haragos lelkemnek!','Elmerengek gondolkodva gyakran,
S nem tudom, hogy mi gondolatom van,
Átröpűlök hosszában hazámon,
Át a földön, az egész világon.','Pest, 1846. április 24-30.',1846,'1846',array['Szerelem','Haza']::text[],'{}'::text[],false,488,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184603-87','petofi','Száműztem magamat...','Száműztem magamat az emberek közűl,
Magányba mentem és mélyen rejteztem el;
Magam voltam csak ott és mégsem egyedűl,
Együtt valék a múlt ezer emlékivel.
És minden emlék oly gyászdolgokat beszélt,
Mik fölforgathatnák a szív s ész tengelyét.

Végigtekintettem tulajdon sorsomon
És a világ során. Az és ez oly sötét!
S az éjben, mely minket homályával bevon,
Nem látjuk már az ég vezérlő jobbkezét;
Csak úgy botorkálunk majd ide, majd oda.
Ha botlunk s elesünk, valóban nem csoda.

Igy van. S e gondolat, ez oly engesztelő,
Nagy úr ez, mely minden megbántást eltemet;
E gondolat, miként varázsvessző, elő-
Idézi ama mély rejtekből lelkemet,
Amelybe zárkozék, midőn az emberek
Olyan sokszor s olyan nagyon sértettenek.

Megengesztelt szivem egy zöld olajfa-ág!...
Minden tőled kapott sebem felejtve van;
Megbékűlő jobbom fogadd el, oh világ,
Nem volnál rosz, ha nem volnál boldogtalan.
Boldogtalan vagy s én sajnállak tégedet,
S akit sajnálunk, azt gyülölnünk nem lehet.','Száműztem magamat az emberek közűl,
Magányba mentem és mélyen rejteztem el;
Magam voltam csak ott és mégsem egyedűl,
Együtt valék a múlt ezer emlékivel.','Dömsöd, 1846 május',1846,'1846',array['Természet']::text[],'{}'::text[],false,489,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184604-88','petofi','Salgó','Nógrád s Gömör közt hosszan nyúlik el
A Mátra egyik erdőséges ága,
Miként sörényes, elfáradt oroszlán,
Nézvén sötéten messze tájakig.
E hegytetői kősziklára ül
Borús napokban a pihenni vágyó
Terhes felhőknek vándor serege;
Ez a műhely, hol a komor kovács,
A dörgedelmes égiháború
Készítni szokta a villámokat,
Haragvó isten égő nyilait.
Itt állt Salgóvár, mint egy óriás,
Ki az egekre nyujtja vakmerő
Kezét, hogy onnan csillagot raboljon;
Itt állt Salgó... az éghez oly közel,
És benne mégis a pokol tanyázott.
A századoknak döntő lábai
Elgázolák rég e vár tornyait.
Belőlök egy-két csonka fal maradt, mely
Szomorkodással tölti idejét,
Mint aki lármás ifjuság után
Éltét megunva remetéskedik.
Fölmentem a hegy sziklatetejére
S letelepedtem a romok fölött.
Verőfényes nap volt, tekintetem,
Nem lelve gátot, mérföldekre szállt,
Mint börtönéből megszökött madár,
S vigan köszönté a kék messzeséget,
Hol a faluknak tornyán, a mezőknek
Juhnyájain s a patakok vizén
S mindemhol a nap fénye tündökölt.
De lelkemet nem ily képek körözték,
Nem ily vidámak; lelkemet homályos
Látkörbe vitte a komoly merengés,
Holott körűle kétes ködruhában
Mogorva árnyak lengtek, a kihalt
Sötét középkor véres napjai.

*

Megvirradott a tizennegyedik
Század, s hazánkra éj következék.
Borús éj jött rá... ekkor áldozott le
Az ő napjának, az Árpád-családnak,
Végső sugára. Harmadik Endre halt meg.
Pártok kelének, s a párt fergeteg,
S a fergetegben a folyó zavart,
S zavart folyóban könnyü a halászat.
Elfeledék a hazaszeretetnek
Örök szentségét a fejetlen ország
Önzés bünébe sűlyedt tagjai,
S rabolni kezdék édesanyjokat,
A gyámolától elesett hazát.
Haramjabarlang lett sok sziklavár,
Honnan le a kipusztitott vidékek
Sohajtására gunykacaj felelt,
Miként az őszi bús szellő után
Jön a süvöltő téli zivatar. - -
Salgón Kompolti Péter volt az úr,
Nevét rettegve emlité a táj, mert
Ameddig kardja s buzogánya ért,
Övé lett minden, ami kincs vala,
S hol ellenállás szálla szembe véle,
A kincs helyén vérfoltokat hagyott.
Követte őt a rablás útain
Kompolti Dávid és Kompolti Jób,
Zsivány apjoknak méltó fiai.
Kipusztíták már a szomszéd Somoskőt,
Utána jött a távolabb Fülek,
S most a fölött van a tanácskozás:
Hová fordítsák léptöket jelenleg?
Ottan hevernek, apa és fiúk,
Komor teremben medvebőr felett,
Mit kacagányul vetnek vállaikra,
Ha indulóra a kürt megriad.
Ottan hevernek és Eger borával
Sürítik úgyis sűrü véröket,
Mely ereikben rémesen kereng,
Mint a világok közti téreket
Keresztülkasul-bolygó üstökös.
"Emeljétek föl a kupát, fiúk",
Kiálta Péter, és "koccantsatok
Gedő Simonnak egészségire!...
Ha élünk és az isten megsegít,
Még holnap éjjel vendégei leszünk;
Azért sokáig éljen őkegyelme!"
"Sokáig éljen!" zúgták a fiúk
Utána harsány, mennydörgő torokkal,
És a teremnek hangos boltozatja
Az éljenekre, mint a nyughelyéről
Fölvert szelindek, elkezdett morogni,
S morgott hosszan, mig belefáradott.

*

Gedővár csendes, mintha halva volna;
Reáborult az éj, mint ráborúl a
Halottra a koporsó födele.
Ki virraszt még a késő éjszakán
Gedővár néma falai között?
A szerelem s a hazaszeretet,
Az égnek e két legszebb csillaga.
Mindenki szunnyad, csak Gedő Simontól
Riasztja messze álma nyúgodalmát
A honfigondok éber tábora.
És míg a férj bús lámpa fénye mellett
Pusztult hazája sorsán elmereng,
Szomszéd teremben nője térdepel,
A szépségében ragyogó Perenna,
S imát sohajt az égiek felé,
Hogy boldogítsák a magyar hazát,
Mert míg a honnak boldogsága nincs,
Mindaddig férje is boldogtalan.
Egyszerre a nő felsikolt ijedve,
Hallván közelgő fegyvercsörgetést,
S belép férjéhez és rémülve áll meg.
A másik ajtó ekkor nyilt s azon
Kompolti Péter jött be kardosan.
"Gedő uram, szép jóestét kivánok."
Szólt a haramja, "vendégid jövének;
Remélem, szíves házigazda léssz,
S kérés nélkűl is átadod nekik,
Amit kivánnak... minden vagyonod.
Csodálkozol, hogy ily váratlanúl
Leptünk meg és ily észrevétlenűl
Léptünk eléd?... ez egyszerű dolog:
Megvesztegettük a jó porkolábot,
S ő megnyitotta várad kapuját,
S bejöttünk százan... százan! érted-e?
És most legényid egyig megkötözvék.
A jó fiúk javában álmodoztak,
Midőn kezökre a hurok került.
Azért, Gedő ur, add elő, amid van...
Vagy szavaimban tán kételkedel?
Im hát tekints ki!" Megnyitá az ajtót,
S láthatta a száz fegyverest Gedő,
Köztök Kompolti Jóbot s Dávidot.
"Fossz hát, zsivány, és vidd, amit találsz!"
Szólt megvetőleg a várúr; "Perennám,
Eredj szobádba, és az aggalom
Ne bántsa lelked: tégedet mególak,
Téged, legdrágább kincse életemnek!
A többivel nem gondolok sokat...
Hadd hízzanak rajt e gaz tolvajok."
Kompolti Péter ment kutatni s véle
A martalékra vágyó cinkosok;
Csak Dávid és Jób állt merőn, s ha ajkok
Le nem pecsétli a csodálkozás,
Ezt kérdték volna: milyen látomány ez?
Melyik tündére az álomvilágnak
Szállott a földre, e falak közé?
S midőn a méla bámulás ködében
Eltévedt lelkök ismét visszatért:
Egyszerre léptek az ajtó felé,
Amely Perenna teremébe nyílt,
S amely előtt vont karddal állt a férj,
Vont karddal és rettentőn, mint az angyal,
Ki őrizé a paradicsomot.
"Eddig s tovább nem!" dörgött a jövőkre,
"Eddig s tovább nem!... a kétségbesés, a
Halál szolgája áll e küszöbön,
E szent ajtónak tiszta küszöbén!"
Ekkép a férj; de a két zordon ifjut
Nem rettenték meg a dörgő szavak,
Sem a szemeknek átszuró világa,
Mely villámlásként szállt a hang előtt.
"Utamba állasz?" így kiálta Jób,
"Utamba mersz még állani? jaj neked!
Keresztültörnék, bárha kezeidben
Száz kard villogna s minden kard hegyéről
Ezer halál vigyorgna is reám!"
És összecsaptak csengő fegyverökkel
Gedő és Jób, mint két kőszikla, melyet
Egymás felé sujt a földindulás.
Akközben Dávid rést lelt s besuhant,
Ahol Perenna elszorult kebellel
Az aggodalmak árján fuldokolt.
Egy jajsikoltás és egy halk sohaj...
A nő sikoltott és a férj sohajtott,
A nő, kit Dávid vett ölébe s vitt,
S a férj, kinek Jób átdöfé szivét.

*

Salgó s Gedővár közt emelkedék
Hajnácskő, szinte sziklaormi vár.
Csend volt a várban és a vár alatt.
Mindenki alvék; a toronynak őre
Virraszta csak még félig nyilt szemekkel.
A fövenyóra éjfélt mutatott.
Mi zaj hasítja a csendet keresztül?
Még halk, de percről percre hangosabb.
Az őr keresztet hány és a toronyból
Fél bátorsággal néz a völgybe le;
Ki más zavarná a világ nyugalmát
Az éjszakának kellő közepén,
Mint boszorkányok és kisértetek?
Lenéz az őr... a teljes hold világa
Aranyfátyolként leng a vár körül,
S a vár alatti völgy ezüst ködével,
Mint két szerelmes lélek összeolvad.
A fényhomályban Gedővár felől a
Salgói úton nyargal egy lovag,
Ölében egy hölgy hófehér ruhában
Hollósötét haj lengő fürtivel.
Mögöttök távol ismét egy lovag. -
Olyan tünékeny volt e jelenés,
Hogy a toronynak őre másnap ezt,
Midőn fölébredt, álomnak hivé.

*

Midőn fölére Salgó udvarába
Kompolti Dávid a szép martalékkal,
Ez életének nem adá jelét,
Aléltan fekvék annak karjain;
Szivében a vért és eszméletet
Megállitá a félelem s futás.
Gyöngéd karokkal tette őt az ifju
Egy kerevetre: csínnal bánt vele,
Miként a gyermek a kicsiny madárral,
Melyet fészkébül épen most lopott ki;
S megállt előtte s elmerűlve nézte
És lelkesedve így szólt: "Oh miért
Fejem nem oly nagy, mint az ég, hogy annyi
Szem volna rajt, ahány csillag van ott,
Hadd bámulnálak valamennyivel!...
Ki vagy, ki vagy te? olyan ismerős
Előttem arcod mindenik vonása;
Találkozám már véled?... oh igen, most
Emlékezem, hogy egykor láttalak,
Régen, fölötte régen. Még midőn
Mint gyermek jártam a vadon homályin?
Miként ártatlan gyermek, akinek
Vérzett szive, ha vérezett az őz
Szilaj vadászok gyilkoló nyilától:
Oh akkor, akkor gyakran láttalak.
Ha szenderegtem a kis völgyi forrás
Virágos partján: édes álmaimban
Meg-megjelentél, tündérek leánya!
Hozzám jövél s lehajlottál reám,
Miként lehajlik földre a szivárvány,
S fülemben égi hangokat sugál.
Karom kinyujtám, hogy öleljelek,
S fölébredék... te már távol valál,
A rengeteg sötétzöld mélyiben
Láttam fehérlő árny-alakodat,
S futék utánad, mint az esti szél
A tünedékeny pillangó után,
Futék a hegyre... a hegy tetején
Bámulva álltam és szomorkodám; már
Oly messze voltál tőlem, fönn az égen
Az esti csillag képiben ragyogtál. -
Gyermekkorom tűnt s gyermekéveimmel
Eltünt regényes ábrándim világa,
S vad ifjuvá lett a szelíd fiú,
S azóta véled nem találkozám...
De én beszélek hozzád, és te nem
Hallod beszédem; mozdulatlanul
Fekszel, miként az elesett szobor.
Élsz, vagy meghaltál? oh csak meg ne halj,
Inkább hervadjon el minden virág
A föld szinén, s ne légyen több tavasz!...
Hah, végre, végre nyílnak szemeid;
Milyen szemek, mily égetőn-vakítók...
Hová jutottam? hol vagyok? talán a
Teremtő műhelyében, ahol a
Napok készülnek? ottan, ottan... oh
Ha e két nap az égre fölkerűl,
A mindenséget porrá égeti!"....
''Elég már, bátya, most énrajtam a sor,''
Ily hang szakasztá félbe Dávidot,
Jób hangja, aki mostan érkezett meg,
''Elég volt, bátya, most énrajtam a sor;
E drágakincsen ketten osztozunk!''

*

Eszmélt Perenna, és csodálkozással
Nézett körűl, és töredezve szólt:
"Férjem!... de ez nem férjem... ez sem az;
És e terem... hisz ez nem a mienk.
Hová juték? és férjem hol marad,
Hogy így magára hagyja hitvesét?"
"Férjed, menyecske, messze útazott,"
Ekkép felelt Jób, "kár lesz várnod őt,
Mert míg utából ismét visszajő,
Rég elvirítnak ifju bájaid.
Azért feledd őt s add nekünk magad,
Hogy részesűljünk mink is a gyönyörben,
Mit férjed a mennyországtól bitorlott."
"El oldalamtól! vissza, szemtelen!"
Kiálta a nő, "vissza... és ne szólj,
Mert minden szóért s minden léptedért,
Ha férjem eljön, rémesen lakolsz..."
"Ha férjed eljön, akkor?" szóla Jób.
"Hisz mondtam már, hogy messze útazott,
Oly messzire, hogy onnan, ahová ment,
Porszemnek látja a nagy földtekét.
Szóval - hogy őt ne várd hiába - nézd
E kardot s rajta ezt a szép piros vért;
Ez férjed vére... én megöltem őt.
Most hát szabad vagy, szép asszony, szabad!
A női hűség rabbilincsei
Nem korlátozzák többé lelkedet.
Szabad vagy, használd szabadságodat.
Két kar helyett most négy kar vár reád,
Hogy boldogítson ölelésivel."
Perenna némán és merően állt,
Némán, merően, hidegen, fehéren,
Miként holt, csendes téli éjszakán a
Száraz bokor, mit ellepett a hó.
Ott állt Perenna és a kardra bámult,
Amelyen olyan drága vér aludt meg. -
E mozdulatlan némaság alatt
Szivét, lelkét mily harcok szaggaták!
A lélek benne ugy sírt, ugy nyögött,
Ugy küszködött, ugy jajgatott, miként
A jég alatt a befagyott patak.
Kitört végtére a kétségesés,
Kitört belőle, mint a tűzokádó
Hegy méhéből a füst s lángoszlopok,
És átkokat szórt, rémes átkokat
Zsivány fejére férje gyilkosának.
De mintha minden átok egy virág
Lett volna, egy-egy illatos virág,
Miket feléje dobnak, hogy szagolja,
Olyan kedvtelve állt a hölgy előtt Jób,
S midőn az végzé, így kezdette ez:
"Hah, istenemre, hogyha átkozódva
Ily szép vagy, asszony, menj férjhez naponként,
S én férjedet naponként megölöm!...
Átkozz tovább, szép hölgy, én hallgatom,
Ha minden átkod megfogamszik is."
Perenna Dávid lábaihoz borult,
Átfogta térdét, és így esdekelt:
"Oh, ifju, arcod nem oly ördögi,
Miként ezé itt... légy könyörülő,
És ój meg tőle, ój meg engemet!
Szeretni foglak, szolgálód leszek,
Csak ments meg engem férjem gyilkosától,
Csak e sátán ellen légy paizsom."
"Meg foglak óni, gyermekálmaim
Földönfölűli tündérgyermeke!"
Kiálta Dávid fölemelve őt,
"Meg foglak óni, paizsod leszek;
S ki hozzád nyúlni kíván: annak e
Paizst elébb ketté kell törnie.
Most hát öcsém, Jób, ehhez tartsd magad!"
"Nem ugy, jó bátya," monda Jób s szemében
Ellenszegűlő dacnak lángja gyúlt,
"Nem ugy, jó bátya! igy nem alkuszunk.
Minálunk minden martalék közös,
Azért kettőnké e menyecske is;
És ha nem engedsz, tudd: e kard, amellyel
Férjének írtam úti levelet
A másvilágra, e kard most is éles,
S karomnak sincsen legkisebb baja!"
Egymás elébe állt a két fiú,
Egymás elébe állt és hallgatott,
Nyelvök helyett most kardjaik beszéltek.
Kompolti Péter jött be s rájok ordít:
"Megálljatok!" s a bajvivók megálltak.
"Apánk, te légy hát köztünk a biró,"
Igy szóla Jób, "ez asszonyt itt magának
Akarja Dávid bátya tartani;
De én azt mondom: ehhez nincs joga,
Mert ő kettőnké. Nincs-e igazam?"
"Hitvány fiúk", szólt megvetőleg apjok,
"Ily hasztalanság annyira feltüzel,
Hogy egymás ellen karddal rontotok?
S ilyen mihaszna pörben engemet
Mertek biróul híni, engemet!... jó;
Igazságot hát én szolgáltatok.
Halljátok: e hölgy nem lesz egyiké sem.
Sem egyiké, sem másiké... igen,
E hölgyet bírni én fogom, magam!"
Kihullt a kard a két fiú kezéből,
Vérök föllázadt, sustorgott, miként
A víz, amelybe a villám csapott,
S dörmögni kezdtek bosszus dolgokat.
Keresztülszúró lángtekintetét
Jártatta végig rajtok az apa,
S parancsolólag így kiálta föl:
"Ki mer moccanni és morogni, hogyha
Kompolti Péter ezt kiáltja: csitt!"

*

Miből teremté isten a szivet?
Hogy annyi bútól, kíntól sem hasad meg,
Amennyi érte a szegény Perennát. -
Őrizve Salgó szűk falai között
Ült a fogoly hölgy napok óta csak,
De mindenik nap századokra nyúlt,
Azokra nyujtá azt a szenvedés.
Az árva lélek mennyit szenvedett!
Egy pillanatban keble meggyuladt
A fájdalomtól és más pillanatban
A rettegéstől ismét megfagyott.
Hosszan tünődék, véghetetlenűl:
Hogy szabaduljon e falak közűl,
S hogy álljon bosszut férje gyilkosán?
És nem talála semmi, semmi módot!
S most jött reá a legnagyobb csapás;
Kompolti Péter így nyilatkozék:
"Szép asszony, benned a sátán lakik,
Te megbüvöltél, napról-napra jobban
Tetszel nekem, s ha akarod, ha nem:
Én feleségül veszlek tégedet."
"Hozzád megyek", szólt elhatározottan
Perenna, ámde oly hangon, mikéntha
Lett volna a halálnak angyala,
S ezt mondta volna ama szók helyett:
"Kompolti Péter, végórád ütött!" -
Magához híta Dávidot Perenna,
S így szóla: "Ifju, igazán szerettél?
Vagy pillanatra fellobbant lidércnek
Volt lángja csak, mit érezél irántam?
És ha szerettél, mondd: szeretsz-e még?"
"Szeretlek egyre," válaszolt az ifju,
"Szeretlek, mint a völgyet a patak,
Szeretlek, mint a csillag az eget,
Szeretlek, mint a féreg a gyümölcsöt!
S ha te szeretnél... oh szólj, asszonyom,
Hogy érdemeljem meg szerelmedet?"
"Hogyan?" felelt a nő, "egy módja van:
Öcséd megölte férjemet, s apád most
Engem magának hitvesűl kiván.
De én apádat, ezt a második
Leendő férjemet szintúgy utálom,
Miként első férjemnek gyilkosát.
Szeretsz valóban? úgy hát szabadíts meg
E két gonosztól. - A tiéd leszek, ha
Apádat és öcsédet megölöd."

*

Örök rejtélyű érzés, szerelem!
Te nagy folyó, mely egyszer szemetet,
Máskor virágot hordasz vizeden,
S mind egy helyről: az emberek szivéből.
Oh szerelem, te végtelen óceán,
Melynek határát még nem látta senki,
S melynek le nem szállt fenekére senki.
Ott állsz te, óriások óriása,
Mesés nagyságban... hogyha nyugoszol,
Meglátja széles tükrödben magát a
Határtalan menny minden csillaga;
S ha háborogsz: fölszíneden csatáznak
Az alvilágnak minden szörnyei.
Mindenható erő vagy, szerelem!
Mindenható vagy... angyallá az embert,
Az angyalt ördöggé, az ördögöt
Emberré könnyen átváltoztatod... - -

*

Derűlt kék éj volt, tiszta csendes éj,
Vidáman néztek felhőtlen magasból
A földre a hold és a csillagok,
Olyan vidáman!... hah, pedig mi történt
A földön? apa- s testvérgyilkolás!
Kigyóként csúszott Dávid a terembe,
Hol apja szunnyadt. Ágya függönyét
Széttolta halkan... reszketett keze,
Mintha kősziklát hengerítene.
"Itt fekszik, alszik," így gondolkodék,
Merőn szegezve rá égő szemét,
"De mily szelíd most arca, melynek ébren
Minden vonása egy-egy Lucifer;
Vagy csak te látod tán ilyen szelídnek,
Te mindig-gyáva lelkiismeret?
Eredj, hivatlan vendég, menj tova;
Nem hallgatok rád, nem, nem! hasztalan
Nyujtod felém fenyitő ujjadat,
Hiába intesz oly parancsolólag,
Nem hallgatok rád... nézd, nem hallgatok!"
Az alvót ekkor torkon ragadá,
S beléje fojtá a lélekzetet...
Nem is nyögött... egy rángás, s vége volt.
Bevonta ismét a függönyt s mene,
De a küszöbnél visszafordula,
Hogy megtekintse: nem maradt-e élet
Ama testben? nem támadand-e föl?
Az ágy előtt megállt... állt, s nem meré
A kárpitot szétvonni újolag,
Nem mert benézni rettentő müvére,
S lélekszakadva kifelé rohant
Másik terembe, ahol öccse volt.
A zajra Jób fölébredett s fölült,
S fél eszmélettel nézte a jövőt,
S midőn egészen eszmélt, akkorára
Keblében járt a gyilkoló acél,
Amelyet bátyja a falról ragadt le.
De nem halálos volt Dávid szurása,
Feléje lépett tántorogva öccse,
Hogy megragadja öldöklő kezét...
Egy új suhintás és Jób homlokát
Elboritotta vére, s összedőlt.
A kardot messze dobta Dávid, és
Futott; futott ki, mintha lépteit
Követte volna százezer boszorkány,
Lidérc, kisértet, ördög s minden, ami
Irtóztató a képzeletben él.
Futott, futott és nem tudá: hová fut?
Sötét sarokban megvoná magát,
Szemét behunyta, hogy ne lássa a
Számíthatatlan rémeket; de látta
Még akkor is, ha behunyá szemét.
S majd apja halvány arca állt előtte,
Majd öccse véres, megvagdalt alakja.
Intett kezével, hogy távozzanak;
Nem távozának. Mindig közelebb
Jöttek hozzája... egyre közelebb...
Beléje vágták végre körmüket...
Torkon ragadták... lég után kapott,
S egy jajnyögéssel összeroskada.
Midőn fölébredt, reggeledni kezdett,
A hajnalfény betört az ablakon;
Körűltekinte, s akkor látta meg,
Hogy apja ágya mellett feküvék.
"Apám, ébredj föl, ébredj... hallod-e?"
Szólott megrázva a holttetemet,
"Mit alszol, hosszan, mint a mormotér?
Már fényes nap van. Jer, menjünk rabolni...
Szabad vásár van, minthogy nincs király.
Menjünk rabolni, szálljuk meg Gedővárt;
Tiétek minden kincs, arany... nekem
Nem kell egyéb, csak a vár asszonya.
De kelj föl hát! ne rángattasd magad
Hiába. S mégsem ébredsz föl... no semmi,
Fölébredsz majd az ítéletnapon.
De akkor ki ne böffentsd valahogy
Az istennek, hogy én voltam, ki téged
Elaltatálak, mert megfojtalak!"
Elindult és ment a szomszéd terembe.
"Hát ez ki itten?" kérdé, öccse testét
Megrugva, "mit? te volnál, Jób öcsém?
Mi a manó, hát a földön heversz?
Neked bezeg jó ágyad lehetett.
Bordáidnak becsűletére válik,
Hogy nem jajgatnak ilyen durva ágyon.
Hanem hát kelj föl, s mosd meg arcodat,
Hiszen merő vér; kelj föl, hallod-e?
Mi a tatár, ugy veszem észre, hogy ma
Fölkelni nincsen kedve senkinek.
Annál jobb. Oh ez pompás alkalom!
Szép kedvesem most megszöktethetem..."
S ment a szobába, hol Perenna volt.
"Megölted őket?" kérdezé a hölgy.
"Kit öltem én meg?" fölkiálta Dávid,
"Én nem öltem senkit, senkit is!
Ottan feküsznek szépen, csendesen,
Egyik fehér és a másik piros,
Jer, angyalom, jer. Mélyen alszanak;
Megszökhetünk. Jer. Senki sem vesz észre.
Fölnyargalunk a bástya tetejére,
S onnét aztán az égbe röpülünk!"
"Hah, ez megőrült," gondolá Perenna,
S borzadva hátrált, de az ifju őt
Ölébe fogta s vitte kifelé.
A nő sikoltott. "Csitt, légy csendesen,
Mindenre kérlek, ami szent előtted!"
Szólott az ifjú, "fölkel valaki
Zajodra, s akkor el nem szökhetünk,
Elfognak... hah nézd, nézd, már jőnek is!"
Ezzel rohanni kezde, fölrohant
A bástyafalra. "Most röpülj!" kiálta,
"Mindjárt ott fönn, ott fönn leszünk az égben,"
És átszorítva a hölgyet, leugrott...
Alant a mélység sziklacsúcsai
A vértül és a hajnaltól pirultak

*

Dávidnak már nem kelle temetés,
Elnyelte őt a vár alatti mélység,
El volt temetve. S aki eltemesse
Apját s öcsét: nem volt ember reá.
Kipusztulván mind a Kompoltiak,
Elosztották a rablott kincseket
Legényeik; de osztozás alatt
Egymásnak esvén kardot fogtanak.
Kevés jutott el épen közülök.
Nagyrészt elestek, és holttesteik
Az éhes hollók tápláléki lettek.
Igy állt sokáig Salgó zajtalan,
Csak a hollóknak károgása szólt
Holttetemekkel megtelt udvarában;
S alant a völgyben a népség futott
A szél elől, mely Salgóról jöve.','Nógrád s Gömör közt hosszan nyúlik el
A Mátra egyik erdőséges ága,
Miként sörényes, elfáradt oroszlán,
Nézvén sötéten messze tájakig.','Dömsöd, 1846. május',1846,'1846',array['Természet','Szerelem','Haza']::text[],array['osz','tel']::text[],false,490,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184604-89','petofi','Levél Várady antalhoz','Hát megtörtént a párbaj? s élsz-e még?
Ha főbelőttek, - tudósíts felőle,
Írd meg tüstént, hogy Pestre felrohanjak,
És bosszut álljak éretted, barátom...
Szó ami szó, de nekem igazán
Nem tetszik, hogy te minden balgaságért
Kész vagy kockára tenni éltedet.
Azt gondolod: lelked-tested szakáll? s ha
Leborotválnak, újolag kinősz?
Csalódol; mert az élet csizmatalp,
S ez nem lesz új, ha egyszer elkopott,
Azért kiméld a drága csizmatalpat,
Amelyet nem szab kétszer senkinek
Az ég vargája, a kőszívü sors. -
S azt gondolod tán: annyi a barátom
Mint fönn az égen a csillag? ha egy
Lehull közűlök, észre sem veszem?
Hiszen tudod jól: mily kis számotok van
Nektek, kik engem őszintén szerettek,
Kik fönntartjátok szívem melegét.
Mért e kis számot megfogyasztani? -
És Ida, Ida, e kedves leány,
Ha téged elveszt ő, mivé lesz? ő
Kinek kivűled nincsen senkije.
Te vagy világa... Lennél oly kegyetlen,
Reászakadni hagynád a világot?
S van még egy... a hon! vagy már elfeledted,
Feledhető-e, amiről beszéltünk
A lelkesűlés lángóráiban?
Ki tudja, mit hoz a kétes jövendő,
Mely álmainknak legkedvesbike,
S akkor hazánknak ránk szüksége lesz. -
Látod barátom, élted mily becses,
Azt a világhoz mennyi lánc köti,
S te mégis könnyelmün kockáztatod.
Ha még nem tértél, térj eszedre már,
S ne légy, mint voltál, olyan balgatag,
Vagy igazabban: oly kétségb''esett...
Kétségbeesni!... milyen gyávaság!...
Kinek van erre több s nagyobb oka,
Mint énnekem? de én szégyenleném ezt.
A szenvedésnek lángjában szivem
Szét fog pattanni, mint a porcelán,
De, mint a jégcsap, szétolvadni nem!...
Megállj, ha Pestre ismét fölmegyek,
Majd megtanitlak én kétségbeesni,
Hogy unokád is megemlegeti.
Vásárra ott benn termek nálatok,
S viszek portékát, de nem holmi gyapjút,
Vagy bőrt, vagy posztót s effélét, azért
Nagyon hiszem, hogy nem lesz kelete.
Mert haj, jó gazda ám a magyar ember!
Amit kutyákon, kártyán s más egyében
Eltékozol, meggazdálkodja könyvön.
A könyvvel ugy van, mint hajdan zsinóros
Nadrágjával s prémes mentéivel volt,
Melyet nagyapja s édesapja vett;
Az szolgált még az ő fiának is.
Hazám, mégsem vagy oly boldogtalan,
Minőnek első pillanatra látszol,
A lelki szükség nem bánt tégedet;
Minden szükséged van, de lelki nincs,
Ettől az egytől megmentett az Isten...
- - Amint mondottam: a vásárra majd
Meglátsz barátom: akkor fölmegyek,
S te rám sem ismersz, ugy megváltozám;
A szép természet megváltoztatott,
Beteg kedélyek e hű orvosa,
Beteg valék én ott tinálatok
A pesti utcák holt, hideg kövén,
Hosszú, sötét árnyként vonult utánam
A csüggedés, az életunalom. -
Ujjászülettem!... a falusi lég, a
Sötét erdőnknek zúgó lombjai,
Lombok felett a csattogó madár,
A fák alatt a hallgatag virágok
Föléleszték elájult lelkemet;
Nem gyűlölöm, mint eddig, a virágot:
Már csak haragszom rája, csak haragszom...
Hogy olyan gyáva, hogy föl nem kiált
Elzárt, elorzott boldogságaért, hogy
Meg nem torolja kincse elrablóin
Évezredeknek szenvedéseit. -
De hinni kezdem, hogy dicső napoknak
Érjük maholnap fényes hajnalát,
Midőn a népek mind fölemelik
A föld porába gázolt fejöket,
S végigmennydörgik a föld kerekén:
"Legyünk rabokból ismét emberek!"
Ez nagyszerü, de véres kor leszen,
És úgy is illik, hogy véres legyen!...
Már vizözön volt, most egy vérözön kell,
Hogy megtisztuljon a világ a szennytől,
Amely fölötte meggyülekezék;
Egy vérözön kell! és ha az lefolyt majd,
A megmosdott föld tiszta szép leend,
És lakni fognak emberek fölötte,
Hasonlitók az isten képihez.','Hát megtörtént a párbaj? s élsz-e még?
Ha főbelőttek, - tudósíts felőle,
Írd meg tüstént, hogy Pestre felrohanjak,
És bosszut álljak éretted, barátom...','Dömsöd, 1846. május 22.',1846,'1846',array['Természet','Haza','Szerelem']::text[],'{}'::text[],false,491,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184605-90','petofi','Barna menyecskének...','Barna menecskének szeme közé néztem,
Az én szemem fénye elveszett egészen.
Én teremtőm, ugyan hogy is teremhet már
Olyan sötét szemben olyan fényes sugár!

Elveszett, elveszett az én szemem fénye,
Hej pedig talán már indulnom is kéne!
Hogy induljak? hova menjek, ha nem látok?
Nyakamat szegheti valamelyik árok.

De mégis indulok... állj elém, menyecske,
Ha már el kell esnem: essem az öledbe;
Egyszer ölellek meg, s karomat levágom,
Ne öleljek többé senkit a világon!

Nem kellek, ugyebár, nem kellek én neked?
Van már kit te ölelsz, ki téged ölelget;
Megyek hát, megyek... ha árokba esem is,
Habár az árokban nyakamat szegem is!','Barna menecskének szeme közé néztem,
Az én szemem fénye elveszett egészen.
Én teremtőm, ugyan hogy is teremhet már
Olyan sötét szemben olyan fényes sugár!','Pécel, 1846. június-július',1846,'1846','{}'::text[],'{}'::text[],false,492,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184605-91','petofi','Most kezdem én csak még ismerni...','Most kezdem én csak még ismerni
Az én derék jó szívemet!
Ennél a szívnél a világon
Jobb, derekabb szív sem lehet.

Mint aggódtam, hogy már ezentul
Nem lesz nekem több víg napom!
És ím bokámot ujra össze-
S kalapomat félrecsapom.

Szívem még ép virág, amelynek
Féreg nem bántja gyökerit;
Elhervad minden ősszel, ámde
Minden tavasszal kivirít.','Most kezdem én csak még ismerni
Az én derék jó szívemet!
Ennél a szívnél a világon
Jobb, derekabb szív sem lehet.','Pest, 1846. június-augusztus',1846,'1846',array['Természet']::text[],'{}'::text[],false,493,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184605-92','petofi','F.L. kisasszony emlékkönyvébe','Miért mondjam, hogy nem feledlek el?
Miért mondjam, hogy rólad e kebel,
Oh lyány, örökre megemlékezik?
Hitelt szavamnak szíved úgysem ad!...
Mert mi poéták hazudunk sokat,
S aztán ha szívből szólunk sem hiszik.','Miért mondjam, hogy nem feledlek el?
Miért mondjam, hogy rólad e kebel,
Oh lyány, örökre megemlékezik?
Hitelt szavamnak szíved úgysem ad!...','Pest, 1846. június-augusztus',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,494,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184605-93','petofi','Megfagy a szív, ha nem szeret...','Megfagy a szív, ha nem szeret;
És ha szeret, megég.
Ez és az baj. E két baj közt
Melyik jobb?... tudj'' az ég!','Megfagy a szív, ha nem szeret;
És ha szeret, megég.
Ez és az baj. E két baj közt
Melyik jobb?... tudj'' az ég!','Pest, 1846. június-augusztus',1846,'1846',array['Szerelem']::text[],array['tel']::text[],false,495,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184605-94','petofi','Rabság','Töredék

Milyen vig a világ! folyvást miként vigad!
Örök énekszóval s zenével van tele!
E tombolók között a legzajosbikat
Kérdezzétek meg csak: ha vajon boldog-e?
Én nem hiszem, hogy az; dehogy boldog, dehogy!

Csak a kétségb''esés, mi bennünket vidít,
Azért kelünk csak e rivalgó zajra, hogy
Ne halljuk láncaink csörömpöléseit.
Rab a világ, igen, kezén-lábán bilincs...
Az volna lelkén is, hanem már lelke nincs - -','Töredék
Milyen vig a világ! folyvást miként vigad!
Örök énekszóval s zenével van tele!
E tombolók között a legzajosbikat','Pest, 1846. június-augusztus',1846,'1846',array['Haza']::text[],'{}'::text[],false,496,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184605-95','petofi','Szeretek én...','Szeretek én, miként még ember
Sohasem szeretett talán.
Szeretek én szent szerelemmel.
De kedvesem nem földi lyány.

Szeretek én egy istenasszonyt.
Egy számkiűzött istennőt:
A szabadságot. Fájdalom, hogy
Csak álmaimban látom őt.

De álmaimban igen gyakran,
Majd minden éjjel megjelen.
Mult éjszakán is egy virágos
Mezőben együtt volt velem.

Letérdepeltem s elmondék egy
Égő szerelmi vallomást,
S földhöz hajoltam, hogy virágot
Szakítsak, s néki adjam át.

Ekkor hátam mögött termett a
Hóhér s lesujtá fejemet...
Épen kezembe hulla, és én
Azt adtam át virág helyett.','Szeretek én, miként még ember
Sohasem szeretett talán.
Szeretek én szent szerelemmel.
De kedvesem nem földi lyány.','Pest, 1846. június-augusztus',1846,'1846',array['Szerelem','Természet']::text[],'{}'::text[],false,497,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184605-96','petofi','A nép','Egyik kezében ekeszarva,
Másik kezében kard,
Igy látni a szegény jó népet,
Igy ont majd vért, majd verítéket,
Amíg csak élte tart.

Miért hullatja verítékét?
Amennyit ő kiván
Az eledelbül és ruhábul:
Hisz azt az anyaföld magátul
Megtermené talán.

S ha jő az ellen, vért miért ont?
Kardot miért foga?
Hogy védje a hazát?... valóban!...
Haza csak ott van, hol jog is van,
S a népnek nincs joga.','Egyik kezében ekeszarva,
Másik kezében kard,
Igy látni a szegény jó népet,
Igy ont majd vért, majd verítéket,','Pest, 1846. június-augusztus',1846,'1846',array['Haza']::text[],'{}'::text[],false,498,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184605-97','petofi','Képzelt utazás','Béranger után franciából

Az ősz sietve jő és nedves szárnyán
Az én számomra uj fájdalmat hoz.
Mindegyre szenvedek, szegény félénk én,
És jókedvem virága hervadoz.
Ragadjatok ki Párizsnak sarából,
Megújulok, ha szép tájt láthatok.
Mint ifju már Hellasról álmadoztam,
Ottan szeretnék én meghalni, ott!

Értem Homért, igen, hisz görög voltam.
Pythagorasnak igazsága van.
Athén szűlt engem Perikles korában,
Láttam Sokratest rabláncaiban,
Megtömjéneztem Phydias csodáit,
Látám Ilissust, mint virágozott,
S Hymett hegyén a méheket fölkeltém;
Ottan szeretnék én meghalni, ott!

Oh ég, csak egyszer éledhetne szívem
E szemderítő nap sugáritul!
A szabadság, kit távolból köszöntök,
Rám így kiált: jer, győzött Thrasybul!
Menjünk, induljunk, készen áll a sajka.
Tenger, ne nyeljen engem el habod,
Hagyd múzsámat Pyréumnál kikötni,
Ottan szeretnék én meghalni, ott!

Szép Olaszország ege, de azurját
Rabszolgaság homályosítja el.
Evezz, kormányos, távolabb evezz le,
Hol a nap olyan tiszta fényben kel.
Milyen hullám ez? hogy híják e sziklát?
Milyen virító a vidék amott!
A zsarnokság haldoklik ama parton;
Ottan szeretnék én meghalni, ott!

Athén szűzei, fogadjatok a révbe,
És bátorítsatok föl engemet.
Oly földet hagytam el, hol a királyok
Rabszolgává teszik a szellemet.
Védjétek lantom, melyet üldöznek; s ha
Dalom sziveitek meglágyítaná,
Tegyétek hamvam Tirteus hamvához,
Meghalni jöttem e szép ég alá!','Béranger után franciából
Az ősz sietve jő és nedves szárnyán
Az én számomra uj fájdalmat hoz.
Mindegyre szenvedek, szegény félénk én,','Pest, 1846. június-augusztus',1846,'1846',array['Természet','Elmúlás','Szerelem']::text[],'{}'::text[],false,499,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184605-98','petofi','A hevesi rónán','Hátrább vonúl mindegyre
És halványúl a Mátra.
Az esti nap piros fényt
Lövel kék homlokára.

Olyan ez a piros fény,
Mely a kék Mátrán lángol,
Mint kékszemű lyány arcán
A rózsaszínű fátyol.

Zörg a szekér, az ostor
Koronként egyet pattan...
Ezenkivűl a róna
Oly néma, oly zajatlan.

Leszálla a nap; vége
A piros alkonyatnak.
A messze látkör szélén
Pásztortüzek pislognak.

De pásztortűz-e az, vagy
Tán csillag, mely lelépett
Egy síró furulyának
Meghallgatása végett?

Emelkedik föl a hold;
Olyan szép s olyan halvány,
Mint a meghalt menyasszony
Bús vőlegénye karján.

S talán a hold valóban
Egy holt menyasszony árnya,
Kit a koporsóból visz
Az égbe szellemszárnya.

Oly szomorú ez a hold,
És mégis rája nézek,
Nem nézhetek le róla,
Sugári megigéztek.

Oly mondhatatlanul bús
Ez a hold, hogy láttára
Eszembe jut éltemnek
Legkínosabb órája.

Magam sem tudom én, hogy
Mi történt ekkor rajtam?
De sírnom kell, zokognom,
Miként akkor zokogtam!','Hátrább vonúl mindegyre
És halványúl a Mátra.
Az esti nap piros fényt
Lövel kék homlokára.','?, 1846. augusztus végén',1846,'1846',array['Természet','Szerelem','Elmúlás']::text[],'{}'::text[],false,500,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184605-99','petofi','Csalogányok és pacsírták','Ugyan még meddig zengitek,
Ti holdvilágos emberek,
A régi kort,
Mit elsodort
Hullámival már az enyészet?
Mikor rontjátok le a fészket,
Mit várromokban raktatok,
Hogy ott versenyt huhogjatok
Vércsékkel és bagolyfiakkal?
Milyen kisértetes ez a dal! -
S dalolnak egyre még,
És szemeikben ég
A lelkesűlés lángja
Vagy a bánat könnyárja.
Ál lelkesűlés, gyáva könnyek!
Miket nekik meg nem köszönnek. -
Tudjátok-e, mik vagytok,
Kik a multról daloltok?
Halottrablók!
Halottrablók!
Sírjából fölássátok
A holt időt,
Hogy őt
Babérokért árulhassátok.
Én nem irígylem koszorútokat;
Penész van rajta és halotti szag!

Sínlődik az emberiség,
A föld egy nagy betegház,
Mindegyre pusztít a láz,
S már egy egész ország esék
Áldozatául,
És több elájul;
S ki mondja meg:
Hol ébrednek föl majd e nemzetek,
Ezen-e vagy a másvilágon,
Muló-e vagy örök az álom? -
De ím a bajnak közepette
Fiait az ég el nem feledte,
Megszána minket nagy fájdalmainkban,
Orvost küld hozzánk, és ez útban is van,
És már maholnap meg is érkezik,
Midőn hóhérink észre sem veszik. -
Tiéd minden dal, minden hang,
Melyet kezemben ád a lant,
Te lelkesítesz engemet,
Tenéked ontom én könyűimet,
Én tégedet köszöntelek,
Te a beteg
Emberiségnek orvosa, jövendő!

*

És ti elkésett dalnokok,
Hallgassatok!
Hallgassatok,
Bár lenne oly szívszaggató
S egyszersmind oly szívgyógyitó,
Mint csalogányé, szavatok.
A csalogány az alkony madara,
Már vége felé jár az éjszaka,
A hajnal közeleg;
Most a világnak
Nem csalogányok,
Hanem pacsírták kellenek.','Ugyan még meddig zengitek,
Ti holdvilágos emberek,
A régi kort,
Mit elsodort','Szatmár, 1846. szeptember elején',1846,'1846',array['Elmúlás','Természet']::text[],'{}'::text[],false,501,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184605-100','petofi','Nagykárolyban','Szeptember 7. 1846

Hát e falak közt hangozának
Nagy szavaid, oh Kölcsey?...
Ti emberek, nem féltek: épen
E szent helyet ily nagy mértékben
Megszentségteleníteni?

Nem féltek-e, hogy sírgödréből
Kikél a megbántott halott?
Hogy sírgödréből ide jő el,
S - hogy hallgassatok - csontkezével
Szorítja össze torkotok?

Nem, ő a sírt el nem hagyandja;
De lenn, sírjában, nem hiszem,
Hogy könnyei ne omlanának
Éretted, te az aljasságnak
Sarába sűlyedt nemzetem!

Mily szolgaság, milyen hizelgés!
S mindig tovább mennek, tovább,
S ki legszebben hizelg, az boldog. -
Ha már kutyákká aljasodtok:
Miért nem jártok négykézláb?

Isten, küldd e helóta népre
Földed legszörnyübb zsarnokát,
Hadd kapjon érdeme dijába''
Kezére bilincset, nyakába
Jármot, hátára kancsukát!','Szeptember 7. 1846
Hát e falak közt hangozának
Nagy szavaid, oh Kölcsey?...
Ti emberek, nem féltek: épen','Nagykároly, 1846. szeptember 7.',1846,'1846',array['Haza']::text[],'{}'::text[],false,502,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184605-101','petofi','A bilincs','Szabadságért küzdött az ifju,
S börtönbe dobták, ottan űl,
És meg-megrázza és átkozza
Bilincsét nagy kegyetlenűl.
Bilincse ekkép szóla hozzá:
"Csörgess, de oh ne átkozzál!
Csörgess, ifjú, csörgésem átok,
Mely a zsarnok fejére száll!

Ugye nem ismersz? a szabadság
Csatáiban kard voltam én,
S épen talán a te kezedben
Villogtam a vér mezején.
Szerencsétlen te, szerencsétlen
Kardoddal hol találkozál!
Csörgess, ifjú, csörgésem átok,
Mely a zsarnok fejére száll.

Bilincset vertenek belőlem,
Belőlem, aki kard valék,
S ki vélem vítt a szabadságért,
Most azt szorítom... szörnyüség!
Szégyennek és haragnak pirja
A rozsda, amely rajtam áll.
Csörgess ifjú, csörgésem átok,
Mely a zsarnok fejére száll."','Szabadságért küzdött az ifju,
S börtönbe dobták, ottan űl,
És meg-megrázza és átkozza
Bilincsét nagy kegyetlenűl.','Nagykároly, 1846. szeptember 5-12.',1846,'1846',array['Haza']::text[],'{}'::text[],false,503,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184605-102','petofi','Júliához','Piros orca, piros ajkak,
Barna fürtök, barna szem,
És ez arcon és e szemben
Mennyi lélek, istenem!

Óh, ha birhatnám e lelket,
Ezt a lelkes kisleányt!
Szólj, leányka, mondd, hogy téged
A szerelem még nem bánt.

Nem, nem! Azt mondd, hogy szeretsz már.
Mondd, hogy engemet szeretsz,
És ez a szó életemnek
Egy új teremtője lesz.

Én szeretlek, és szerelmem,
E végtelen áradat,
Mint a földet az özönvíz,
Eltemette multamat.

Nem tudom, mi voltam eddig,
Ámde azt sem, mi leszek;
Tőled függ, hogy sötét árnyék
Vagy fényes sugár legyek.

Mit határzasz?... Már látásod
Megépíté mennyemet;
Oh leányka, ezt a mennyet
Nem szabad ledöntened.

Im, letérdelek előtted
S esdve nyujtom föl karom;
Vonj föl engem kebeledre,
Vagy borúlj rám, angyalom.','Piros orca, piros ajkak,
Barna fürtök, barna szem,
És ez arcon és e szemben
Mennyi lélek, istenem!','Nagykároly, 1846. szeptember 8-10.',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,504,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184605-103','petofi','Kinn a kertben voltunk...','Kinn a kertben voltunk,
Egymás mellett űltünk,
Az úristen tudja,
Mi történt körűlünk?
Azt sem tudtam, mi van,
Ősz-e vagy kikelet?
Csak egyet tudtam, hogy
Veled vagyok, veled!

Mélyen belenéztem
Fekete szemedbe,
S fehér kezecskédet
Tartottam kezembe''.
Hogy úgy egymást néztük,
Ily szókat ejtettem:
Ha mi most itt kővé
Válnánk mind a ketten!

Azt mondtad: nem bánnád;
Vajon miért mondtad?
Azért-e, hogy már az
Életet meguntad?
Oh vagy tán azért, hogy
Boldogság lenne rád,
Ha együtt maradnánk
Örök időkön át?','Kinn a kertben voltunk,
Egymás mellett űltünk,
Az úristen tudja,
Mi történt körűlünk?','Erdőd, 1846. szeptember 19.',1846,'1846',array['Természet']::text[],'{}'::text[],false,505,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184605-104','petofi','Költői ábránd volt, mit eddig érzék...','Költői ábránd volt, mit eddig érzék,
Költői ábránd és nem szerelem.
Mert meggyógyult e szív, amely úgy vérzék,
És nem maradt a sebnek helye sem.
Ha szerelem lett volna keblem hullámzása,
Időknek multával sem nyúgodt volna el.
Vad ár e szenvedély; amerre medrét ássa,
Sodor magával s végre belehalni kell.

Most értem én csak e szilaj folyóra.
Mint von magával, mint von, mint ragad!
Kiáltsatok rá a harangozóra,
Hogy verje félre a harangokat;
Nagy a veszély, s talán, majd mentésemre jőnek...
De nem! hisz félrevert harang lázas szivem,
Hallá zaját a lyány és nem jött megmentőnek,
És hogyha ő nem jött, ne jőjön senki sem!

Oh lyány, oh lyány, hogy rám ily bánatot hozz,
Nem olvasám sejtésim könyviből!
Azért vontál csak oly közel magadhoz,
Hogy megvakúljak lelked fényitől?
Ugy fénylik lelked, mint a nap világa fénylett,
Midőn fogyatkozás még nem szennyezte meg;
De amily hideg lesz a nap, ha minden élet
Kifogy, kihal kebléből, kebled oly hideg.

Mondád - és nem is reszketett beszéded -
Mondád, hogy soha senkit nem szeretsz.
Nem féled a boszúló istenséget,
Hogy szent céljával ellenkezni mersz?
Vagy tán azt gondolod, hogy nincsen olyan férfi,
Ki megérdemlené a te szerelmedet?
Attól tartasz, hogy kincsét szíved elfecsérli,
És aztán vissza többé nem szerezheted?

Hisz meglehet, hogy tán csalódni fognál,
Ám nem szeretni, oknak ez kevés;
A mozdulatlan, a holt nyúgalomnál,
Hidd, többet ér az élő szenvedés.
És csak azért nem fogsz-e építtetni házat,
Mert hátha egykor azt a tűz emészti fel?
S ezért türöd, midőn a nyár esője áztat,
S midőn a tél hideg karjával átölel?

De láttam én jól, hogy ajkad sohajta,
S innen hiszem: van szíved, lángoló,
Csakhogy az észnek jégpáncélja rajta,
Miként a volkán tetején a hó.
Szólj, oh leány, hogy így van, s várok türelemmel,
Mindaddig várok, míg nem mondod, hogy elég,
Várok békével, míg az óra nem jövend el,
Midőn birod hüségem nemcsaló jelét.

Hosszú idő, egy örökkévalóság
Lesz várásomnak minden napja majd.
Nézem magam, mint tengerek hajósát,
Kit a szél a part közelébe hajt,
De itt megfordul a szél, s látja bár a révet
A küszködő hajós: nem közeledhetik.
Kinoskeserves lesz ez örökszomju élet,
Hanem éretted még e kín is jólesik!

Nem fájhat úgy a betegek testének,
Ha éles vas jár át sebeiken,
Nem fájna ugy, ha tűzzel égetnének,
Mint e sovárgó vágy fáj énnekem.
Csak egy kis cseppet önts e fájdalom tüzére,
Egy cseppet a remény kútjából, oh leány,
Hogy évek mulva bár, de meg fog jőni bére
Gyötrelmeimnek, oh csak azt mondd, hogy: talán -

Nem, nem, ne biztass a jövővel engem,
Ne alamizsnát: üdvességet adj!
Hazudtam én, hogy várok türelemben,
Türelmem máris messze, messze hagy;
Fut, mint szilaj ló, s lelkem rája van kötözve,
S pályája mindig sűrübb rengetegbe vész,
Ahol talán majd egy vadállat tépi össze,
Tudod, melyik vadállat?... a megőrülés!

Adj vissza, lyány, adj vissza enmagamnak,
Adj a világnak vissza engemet...
Vagy mit beszélek? tarts meg, tarts magadnak,
Tiéd éltem, te el nem vetheted.
Oh, mondd, hogy elfogadtad, mondd, hogy elfogadtad!
E nagy szavadra tán ég-föld reám szakad;
Mit bánom én? az isten szebb halált nem adhat,
Mint sírba dőlni a gyönyör terhe alatt! -

S ha nem szeretsz, ha soha nem szeretnél?
Mindegy! hozzád van nőve szellemem,
Mint a levél a fához... eljön a tél,
S akkor lehull, de már élettelen.
Ez sorsunk a sirig. Bár járj be messze földet,
Kerűlj bár, mindhiába, engem el nem hagysz,
A soha el nem váló sötétség melletted,
Mit árnyékodnak vélsz, az én bús lelkem az!','Költői ábránd volt, mit eddig érzék,
Költői ábránd és nem szerelem.
Mert meggyógyult e szív, amely úgy vérzék,
És nem maradt a sebnek helye sem.','Szatmár, 1846. szeptember 27.',1846,'1846',array['Természet','Szerelem']::text[],array['tel']::text[],false,506,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184605-105','petofi','Te vagy, te vagy, barna kislyány...','Te vagy, te vagy, barna kislyány.
Szemem s lelkem fénye!
Te vagy mind a két életem
Egyetlen reménye!
Ha ez az egy reményem is
Elmulandó álom,
Nem leszek boldog sem ezen
Sem a másvilágon!

Álldogálok a tó partján
Szomorúfűz mellett.
Nekem való hely; engem ily
Bús szomszédság illet.
Nézem lecsüggő ágait
Szomorúfűzfának,
Mintha azok csüggedt lelkem
Szárnyai volnának.

Elszállott már a madár a
Hervadt őszi tájról,
Hej, ha én is kiszállhatnék
Búmnak országából!
Nem szállhatok, mert búm oly nagy,
Oly nagy, mint szerelmem,
És szerelmem... és szerelmem...
Oh ez véghetetlen!','Te vagy, te vagy, barna kislyány.
Szemem s lelkem fénye!
Te vagy mind a két életem
Egyetlen reménye!','Erdőd, 1846. szeptember végén',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,507,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184606-106','petofi','Szerelemnek rózsákkal...','Szerelemnek rózsákkal
Hintett nyoszolyája!
Megint lefektettem a
Lelkemet reája.
Szerelem rózsáiból
Tövis-e vagy illat,
Mely szívemig, életem
Gyökeréig elhat?

Akár tövis jut nekem,
Akár az illatja,
Mindegy! feküdj rá lelkem,
S álmodozzál rajta;
Álmodd meg azt a nagy szót,
Amely nincsen még meg,
Amely kifejezze majd:
Milyen forrón érzek!','Szerelemnek rózsákkal
Hintett nyoszolyája!
Megint lefektettem a
Lelkemet reája.','Nagybánya, 1846. szeptember végén',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,508,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184606-107','petofi','Szerelmes vagyok én...','Szerelmes vagyok én,
Vagy tán tűzbe estem?
Nem tudom, de igaz,
Hogy ég lelkem, testem.

Látjátok pirúlni
Halovány orcámat?
Hajnal-e vagy alkony,
Ami ottan támad?

Hajnal is, alkony is;
Örömim hajnala,
Örömim hajnala,
Bánatim alkonya.

Megvallom: nem első
Bennem e szerelem,
De hogy az utósó,
Arra esküdhetem.

Szerelmem sasmadár;
Vagy égbe száll velem,
Vagy széjjelszaggatja
Körmeivel szivem.','Szerelmes vagyok én,
Vagy tán tűzbe estem?
Nem tudom, de igaz,
Hogy ég lelkem, testem.','Nagybánya, 1846. szeptember végén',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,509,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184606-108','petofi','Szerelmes vagyok én...','Szerelmes vagyok én;
Megmondjam-e kibe?
Egy barna kisleány
Hófehér lelkibe!

Hófehér a lelke
Ennek a kislyánynak;
Liliomszála ő
Az ártatlanságnak.

Fehér, mint a galamb,
Amelynek képibe''
Isten a szent lelket
Az égből küldte le.

Szállj rám, fehér galamb,
Galambomnak lelke,
Hadd legyek megáldva,
Legyek megszentelve.

Hogyha már hallottam
Szárnyad csattogását,
Hadd halljam egyúttal
Szíved dobogását!','Szerelmes vagyok én;
Megmondjam-e kibe?
Egy barna kisleány
Hófehér lelkibe!','Nagybánya, 1846. szeptember végén',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,510,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184606-109','petofi','Nehéz, nehéz a szivem...','Nehéz, nehéz a szivem,
Rajta csügg a szerelem,
A szerelem bánata,
Roskadozok alatta.

Sem éjem, sem nappalom,
Egyre csak gondolkodom,
Csak arról gondolkodom:
Gondolsz-e rám, angyalom?

Hogyha neked nem kellek,
Ne kelljek én senkinek;
Ha te nem szeretsz engem,
Az isten se szeressen!','Nehéz, nehéz a szivem,
Rajta csügg a szerelem,
A szerelem bánata,
Roskadozok alatta.','Szatmár, 1846. szeptember végén',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,511,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184606-110','petofi','Száll a felhő...','Száll a felhő, magasan, magasan,
Az én rózsám messze van, messze van.
Száll a felhő nyugatra, nyugatra,
A napnak is arra van az utja.

Szállj, felhő, szállj a rózsám fölébe,
Mondd, hogy oly bús a szivem, miként te.
Szállj te is, nap, a rózsám fölébe.
Mondd, hogy úgy ég a szivem, miként te.','Száll a felhő, magasan, magasan,
Az én rózsám messze van, messze van.
Száll a felhő nyugatra, nyugatra,
A napnak is arra van az utja.','Berence, 1846. szeptember végén',1846,'1846',array['Természet']::text[],'{}'::text[],false,512,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184606-111','petofi','Borús, ködös őszi idő...','Borús, ködös őszi idő;
A nap nem is pillant elő.
Hidegen jár a nap
Sötét felhők megett;
A kandalló tüze
Ád egy kis meleget.

Ajtóm, ablakom bezárva,
Üldögélek a szobába''.
Bánatosan nézek
Kandallom tüzére,
Gondolván életem
Elmult idejére.

A mult idő nagy mezein
Hervadt lombok emlékeim;
Összeszedem őket,
Kötöm egy csomóba,
Úgy vetem bele az
Égő kandallóba.

Mint füstölnek, mint füstölnek!
De nem csoda, mert nedvesek;
Nedvesek, de nem az
Ősznek esőjétől,
Hanem szemeimnek
Sokszor folyt könnyétől.

Egy könny most is pillámon áll...
Barna lyányka, ha itt volnál,
Letörlenéd-e azt
Egy selyemkendővel,
Édes mosolygásod
Selyemkendőjével?','Borús, ködös őszi idő;
A nap nem is pillant elő.
Hidegen jár a nap
Sötét felhők megett;','Cseke, 1846. október 1-7.',1846,'1846',array['Természet']::text[],array['osz']::text[],false,513,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184606-112','petofi','Az én képzeletem nem...','Az én képzeletem nem a por magzatja,
Mennydörgés volt apja, villámlás volt anyja,
Csecsemőkorában sárkánytejet szopott,
Ifjú korában oroszlánvért ivott.

Nem is birtam vele, vad képzeletemmel,
Országról-országra vándorolni ment el,
Tenger zúgásával összekeveredett,
Ugy barangolta be a földet és eget.

Mint üstökös, nyargalt sivatag pusztákra,
Zöld vadonerdőkbe, kék hegyek ormára;
A vadonerdőkben tölgyeket szaggatott,
A hegyek tetején sziklákat ingatott.

Hol most e vad fiú?... egy kis virág mellett,
Melletted, barna lyány, mindig csak melletted,
Ott eped, suttog, mint a beteg esti szél...
Szilaj képzeletem, be megszelidűltél!','Az én képzeletem nem a por magzatja,
Mennydörgés volt apja, villámlás volt anyja,
Csecsemőkorában sárkánytejet szopott,
Ifjú korában oroszlánvért ivott.','Cseke, 1846. október 1-7.',1846,'1846',array['Természet']::text[],'{}'::text[],false,514,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184606-113','petofi','Ereszkedik le a felhő...','Ereszkedik le a felhő,
Hull a fára őszi eső,
Hull a fának a levele,
Mégis szól a fülemile.

Az óra jó későre jár.
Barna kislyány, alszol-e már?
Hallod-e a fülemilét,
Fülemile bús énekét?

Záporeső csak ugy szakad,
Fülemile csak dalolgat.
Aki bús dalát hallgatja
Megesik a szíve rajta.

Barna kislyány, ha nem alszol,
Hallgasd, mit e madár dalol;
E madár az én szerelmem,
Az én elsohajtott lelkem!','Ereszkedik le a felhő,
Hull a fára őszi eső,
Hull a fának a levele,
Mégis szól a fülemile.','Cseke, 1846. október 1-7.',1846,'1846',array['Természet','Szerelem']::text[],'{}'::text[],false,515,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184606-114','petofi','Ha szavaid megfontolom...','Ha szavaid megfontolom,
Szeretsz engem, azt gondolom.
Mért nem mondod meg, ha szeretsz?
Ha nem szeretsz, mért hitegetsz?

Nem hiszed, hogy én szeretlek?
Az isten is ugy áldjon meg,
Ugy áldjon az isten engem,
Amily igaz a szerelmem.

Megszerettem szépségedet,
De még inkább szép lelkedet,
Szeretlek én oly igazán,
Mint engem az édes anyám.

Nem ohajtok én egy tavaszt,
Hogy véled átmulassam azt,
Sem egy tavaszt, sem egy telet,
Hanem egész életemet!

Egy napja van csak az égnek,
Egy holdja van csak az éjnek,
Egy isten van a világon,
Egy, csak egy a kívánságom.

Azt várom én, azt az órát,
Mikor így szólhatok hozzád
Ölelésem szent hevében:
"Édes kedves feleségem!"','Ha szavaid megfontolom,
Szeretsz engem, azt gondolom.
Mért nem mondod meg, ha szeretsz?
Ha nem szeretsz, mért hitegetsz?','Cseke, 1846. október 1-7.',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,516,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184606-115','petofi','Te a tavaszt szereted...','Te a tavaszt szereted,
Én az őszt szeretem.
Tavasz a te életed,
Ősz az én életem.

Piros arcod a tavasz
Virító rózsája,
Bágyadt szemem az ősznek
Lankadt napsugára.

Egy lépést kell tennem még,
Egy lépést előre,
S akkor rájutok a tél
Fagyos küszöbére.

Lépnél egyet előre,
Lépnék egyet hátra,
S benne volnánk közösen
A szép meleg nyárba''.','Te a tavaszt szereted,
Én az őszt szeretem.
Tavasz a te életed,
Ősz az én életem.','Szatmár, 1846. október 7-10.',1846,'1846',array['Természet','Szerelem']::text[],array['tavasz','osz']::text[],false,517,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184606-116','petofi','Sz. J. kisasszony emlékkönyvébe','Senki sem szól így a fellegekhez:
"Napkeletre vándoroljatok, mert
Napkelet a szép hajnal hazája,
Ki rózsákat mosolyog reátok,
Lángrózsákat sötét arcotokra."
Senki sem szól így a fellegekhez,
És ők mégis napkeletre mennek,
Napkeletre vonja őket egy mély
Titkos sejtés lágy szellemkezekkel.
Mennek, mennek és ha odaértek,
Megfürödnek a piros tengerben,
A hajnalnak sugártengerében,
És ha egyszer megfürödhetének,
Nem törődnek aztán életökkel,
Nem bánják, ha mindjárt elenyésznek,
Vagy ha hosszu pálya vár reájok,
Hosszu pályán vihar és sötétség.
Akkor is, ha szétszaggatta őket
A vihar s ők este haldokolnak:
Fölgyulad még egyszer arculatjok,
S e pirúlás, végső órájokban,
Ifjuságuk visszaálmodása,
A dicső, az édes ifjuságé,
Midőn rájok a hajnal mosolygott. -
Mint a felhők, titkos sejtelemből,
Napkeletre vándoroltam én is... -','Senki sem szól így a fellegekhez:
"Napkeletre vándoroljatok, mert
Napkelet a szép hajnal hazája,
Ki rózsákat mosolyog reátok,','Szatmár, 1846. október 8.',1846,'1846',array['Természet']::text[],'{}'::text[],false,518,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184606-117','petofi','Mint megfogamszott átok...','Mint megfogamszott átok, az őszi köd
Sötéten űl a puszta világ fölött.

Mi sötétebb, mint e ködborulat?
Az ifjunak arca, ki benne halad.

Megy a komor ifju, ragadja lova.
Száguldó paripán, komor ifju, hova?

"Mit tudta, hová megyen ősapánk, midőn
A paradicsomból kiűzve lőn?

Mit tudja, hová megyen az, ki szerelmet
Nem nyerve, a lyánytul örökre bucsút vett?"

S így céltalanúl az ifju halad.
Előtte, utána ködborulat.

Minden komor, minden sötét,
Csak két dolog, ami kis csillámot vét:

Egy sárga tövisfa, a reggeli dértül
S az ifju halvány arca szeme könyétül.

S nagy a csend, s a csendben nem hallani mást,
Mint egy sohajt és varju-károgást.','Mint megfogamszott átok, az őszi köd
Sötéten űl a puszta világ fölött.
Mi sötétebb, mint e ködborulat?
Az ifjunak arca, ki benne halad.','Szatmár, 1846. október 10. után',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,519,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184606-118','petofi','Oda járok, hova...','Oda járok, hova senki nem megyen,
Hogy a világ szeme észre se vegyen.
Nekiadom ott magam a bánatnak,
Szememből a könnyek csak úgy szakadnak.

Soha, soha ilyen őrült szerelem!
Nem tudom én, mit fog tenni énvelem!
Mérföldekre belátom a világot,
Szerelmemben egy lépésre sem látok.

Örökös bujdosásban van a lelkem,
Egyre űzi nyughatatlan szerelmem,
Hol lesz, hol lesz az én megpihenésem?
Öledben-e, lyány, vagy a sír ölében?','Oda járok, hova senki nem megyen,
Hogy a világ szeme észre se vegyen.
Nekiadom ott magam a bánatnak,
Szememből a könnyek csak úgy szakadnak.','Szatmár, 1846. október 10. után',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,520,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184606-119','petofi','Mi vagy keblem?...','Mi vagy keblem? nem más, mint egy szoba,
E szobának szívem az asztala,
Ez asztalon nagy ezüst pohárba''
Pezsgett, habzott a vidámság árja,
S gondtalanság volt a ház lakója,
S a pohárnak szomjas fölhajtója,
Ki, midőn a poharat kiitta,
Szívemet, az asztalt teleírta,
Teleírta fényes aranytollal,
Pávatollnál tarkább gondolattal. -

Nem lakik már itt a gondtalanság,
E jó fiút messze elzavarták,
Elzavarta egy hatalmas szellem,
A szerelem. Ez lakik most bennem,
Ez lakik most keblem szobájában
Halvány arccal és sötét ruhában.
Az asztalhoz ment és leült mellé,
A pohárból az italt kiönté,
Letörölte a szép arany írást
Az asztalról, és helyébe írt mást;
S oh, szerelem, az, amit te írtál,
Feketébb a halálnál s a sírnál!','Mi vagy keblem? nem más, mint egy szoba,
E szobának szívem az asztala,
Ez asztalon nagy ezüst pohárba''
Pezsgett, habzott a vidámság árja,','Szatmár, 1846. október 7-21.',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,521,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184606-120','petofi','Álmodtam szépet, gyönyörűt...','Álmodtam szépet, gyönyörűt,
Álmodtam és fölébredék.
Mért keltettél föl oly korán?
Mért nem hagyál álmodni még?
Mit a való nem küld reám,
A boldogságról álmodám.
Miért bántottad álmamat?...
Oh istenem, oh istenem!
Hát a boldogságról nekem
Még csak álmodni sem szabad?

Mondád többször, hogy nem szeretsz,
De nem hivém, nem hihetém.
Ne mondd, ne mondd már! mostan, ha
Nem mondod is, elhiszem én.
S midőn tudom, hogy szíveden
Fölirva nincs az én nevem:
Maradjak-e, elmenjek-e?...
marasztasz... és miért?... talán
Mulatni vágysz lelkem baján,
Melyet te hoztál rája, te!

Oh lyány, ez nagy kegyetlenség.
Bocsáss, bocsáss, hadd menjek el.
Nekünk egymástól válni, és...
És mindörökre válni kell.
Futnék tőled, miként a por,
Mit a forgószél elsodor
Ember-nemjárta földekig;
De csak alighogy léphetek,
Mert a bú, melyet elviszek,
Nagyon reám nehezedik.

Isten veled hát ... jaj nekem,
hogy e szót ki kell mondanom;
Miért nem válik rögtöni
Halállá e hang ajkamon?
Isten veled... nem, nem lehet!
Hagyd még megfogni kezedet,
Mely üdvemet szétszaggatá,
Mely jövőmet gyilkolta meg...
Add kezed, hadd ömöljenek
Könyűim s csókjaim reá!

Könyűim-e vagy csókjaim,
Mi égeti jobban kezed?
Csók és könyű, mind a kettő
Nagyon, nagyon forró lehet,
Mert szerelmemmel egy helyen,
A szív mélységes mélyiben,
E tűzhegyben termettenek...
Mint ájtatos zarándokok
Jövének fel, s ők boldogok,
Hogy kezeden halhatnak meg.

Egyet kérek... ne félj, ne félj,
Nem kérem már szerelmedet,
Csak azt a kis vigasztalást,
Hogy nem feledsz el engemet.
Az emlékezet fonalát
Jövődön meddig nyujtod át?
Ha rám addig emlékezel,
Mig olyat lelsz, ki tégedet,
Mint én, olyan forrón szeret:
Ugy sohasem felejtesz el!

De nem kivánom, hogy ne lelj
Oly hű szivet, mint az enyém.
Nem szeretnélek oly nagyon,
Ha ezt a vágyat érzeném.
Ohajtom én: élj boldogul,
Szedj bármi fának ágirul,
Csak szedj te zöld leveleket,
S aztán vesd el, mint elvirúlt,
Elszáradt régi koszorút,
Az én emlékezetemet!','Álmodtam szépet, gyönyörűt,
Álmodtam és fölébredék.
Mért keltettél föl oly korán?
Mért nem hagyál álmodni még?','Szatmár, 1846. október 7-21.',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,522,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184606-121','petofi','Egy pár rövid nap...','Egy pár rövid nap, és én mennyit éltem!
Tükörbe nézni szinte nem merek,
Attól félek, hogy már hajam megőszült...
Ez a szív itten, oh ez oly öreg.

Az éjszakákat keresztűlvirasztom.
Az álmot már nem is keresem én,
Ugysem találnám. Nem tudok alunni,
Mióta bennem alszik a remény.

A kínok is már mind elfáradának,
Elfáradának engem bántani;
Pedig könnyebb a kínok gyilkait, mint
Holttestöket keblünkben hordani.

Én hordom őket és azt gondolom, hogy
Egy század óta hordom őket már.
Olyan nehéz és oly hideg halottak!
Fagy tőlök vérem, csak alig hogy jár.

Erőtlen szemmel nézek szerteszéjjel,
Mint aki kőhöz vágta homlokát,
Aztán föleszmél félig, s két alakban
Lát mindent, s tisztán még semmit se'' lát.

Nincs bennem élet, nincs a lélek bennem,
Kétségeim azt messze zavarák.
Ugy hull reám egy szebb idő emléke,
Mint sírhalomra a tépett virág.','Egy pár rövid nap, és én mennyit éltem!
Tükörbe nézni szinte nem merek,
Attól félek, hogy már hajam megőszült...
Ez a szív itten, oh ez oly öreg.','Szatmár, 1846. október 7-21.',1846,'1846',array['Természet']::text[],'{}'::text[],false,523,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184606-122','petofi','Nem csoda, ha ujra élek...','Nem csoda, ha ujra élek,
Mert hisz ujra láttam őt!
Visszaszállt belém a lélek,
Eszmélek, mint azelőtt.

Kín s reménység kebelemben
Ujra fáklyát gyujtanak,
És e fénynél e teremben
Kergetőznek, játszanak. -

Tudni most csak az szeretném:
Mi volt e találkozás?
Csak azon tünődik elmém:
Véletlen vagy számitás?

Oh e lyányka oly rejtélyes,
Szíve olyan mély folyam,
Hogy szemem, bármilyen éles
Néz beléje hasztalan!

Rejtély vagy te, lyányka, nékem,
S állsz megfejthetetlenűl;
Kárhozatom? üdvességem?
Egyik a kettő közül.

Oh de melyik?... törhetetlen
Lánc körűlem e titok;
Vonna már el sorsom innen,
És nem szabadúlhatok.

Bontsd ki, lyányka, e titoknak
Fátyolából homlokod,
Mert én addig el nem hagylak,
Míg le nem hull fátyolod...

Jaj de kell, kell mennem, bárha
Bizonytalanság kisér;
Úr a sors, hajlok szavára,
Ő parancsol és nem kér.

Elmegyek, de nem örökre!
Majd ha fris virágokat
Hint a tavasz fürteidre,
Dalnokod meglátogat.

Én leszek az első fecske,
Mely tihozzátok röpűl,
S minden reggel, minden este
Cseveg ablakod körűl.

Le a kertbe, a mezőre
Együtt járunk, úgyebár?
S nézzük, lyányka, a föld vére,
A patak, mi pezsgve jár.

Nézzük majd a sok virágot,
Amint nyílnak kelyheik,
S ha ezeket nyílni látod,
Szíved is tán megnyilik.','Nem csoda, ha ujra élek,
Mert hisz ujra láttam őt!
Visszaszállt belém a lélek,
Eszmélek, mint azelőtt.','Nagykároly, 1846. október 22-23.',1846,'1846',array['Szerelem','Természet']::text[],'{}'::text[],false,524,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184606-123','petofi','Volt egy szegény fiú...','Volt egy szegény fiú,
Ki mindig éhezék;
Nem volt egy megevő falatja,
Nem szánta őt sem föld, sem ég.

Hosszú, nagyon hosszú inség után
Igy szóla hozzá egy sötét alak:
"Én téged minden földi bajtól
Megszabadítalak."

Az éhhalál volt, akinek
Szavai ekkép hangozának;
És a fiú, hogy mentül hamarabb
Pihenjen, ment sírt ásni önmagának.

S amint így sírján dolgozék,
A földben egy edényt talál,
Amely arannyal, drágakővel,
Csordultig áll.

A koldusból nagyúr lett.
Él fejedelmileg,
Körűle pompa, fény
És drága ételek.

Mért a fiú ezen dúsgazdagságban
Csak féligmeddig és csak néha vig?
Mert fél szegény, fél a fölébredéstől,
Azt véli, hogy csak álmodik. -

Én vagyok e szegény fiú,
S te a talált kincs, édes angyalom!
Nem merem hinni, hogy szeretsz;
Ugy félek, félek, hogy csak álmodom!...','Volt egy szegény fiú,
Ki mindig éhezék;
Nem volt egy megevő falatja,
Nem szánta őt sem föld, sem ég.','Nagykároly, 1846. október 22-23.',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,525,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184606-124','petofi','T. M. kisasszony emlékkönyvébe','A szerelemnek asztaláról
Nem ittunk mi közös pohárból;
Mégis, ha egy hosszú öröm lesz életem,
Azt én, leányka, csak neked köszönhetem.
S ha meg fogom siratni a napot,
Amelyben életem fogantatott,
Ha nem lesz a világon többé örömem,
Azt is, leányka, csak neked köszönhetem. -
Csodálkozol? ezt föl nem foghatod?
Gondolkozzál csak... kitalálhatod.','A szerelemnek asztaláról
Nem ittunk mi közös pohárból;
Mégis, ha egy hosszú öröm lesz életem,
Azt én, leányka, csak neked köszönhetem.','Nagykároly, 1846. október 23.',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,526,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184607-125','petofi','Erdélyben','Barangol és zúg, zúg az őszi szél.
Csörögnek a fák száraz lombjai,
Mint rab kezén a megrázott bilincs.
Hallgass, zugó szél, hadd beszéljek én!
Ha el nem hallgatsz, túlkiáltalak,
Mint nősirást az égiháború.
Egy nemzet és két ország hallja meg,
Mi bennem eddig titkon forra csak,
S amit keblemből mostan kiröpítek,
Mint a volkán az égő köveket.
Az forra bennem, az fájt énnekem,
Hogy egy nemzetnek két országa van, hogy
E kétországos nemzet a magyar!
Ez tette lelkem pusztává, a bánat
Pusztájává, hol egy tigris lakik:
A vérszemű, a lángszemű harag.
Oh e vadállat hányszor verte el
Magányos éjim csendét, amidőn
Besüvöltötte puszta lelkemet! -
Mely ördög súgta, hogy kettészakadjunk,
Hogy szétrepesszük a szent levelet,
Mit diadalmas őseink írának,
Szivök vérébe mártván kardjokat?
Kettészakadtunk, és a szép levélből
Rongyok levének, miket elsodort
És sárba dobott a századok viharja.
Lábbal tiportak bennünket. Könyűket
És jajkiáltást küldöttünk az égbe,
De panaszunkat az be nem fogadta.
A rabszolgákat nem hallgatja az meg,
Mert aki jármot hágy nyakába tenni.
Méltó reá, hogy azt hurcolja is,
Míg össze nem dől a korbács alatt.
Tartottunk volna össze: a világ most
Tudná hirünket, nem volnánk kizárva
A templomból, hol a nagy nemzeteknek
A tisztelet tömjénét égetik.
Tartottunk volna össze, nem törölnénk
Szemünkből annyi fájdalmas könyűt,
Midőn forgatjuk reszkető kezünkkel
Történetünknek sötét lapjait.
A porszemet, mely csak magában áll,
Elfúja egy kis szellő, egy lehellet;
De hogyha összeolvad, összenő, ha
A porszemekből szikla alakúl:
A fergeteg sem ingathatja meg!
Fontoljuk ezt meg, elvált magyarok,
Amit mondtam, nem új, de szent igaz.
Az események romboló szele
Nem fú jelenleg, és a porszemek
Nyugton hevernek biztos helyökön;
De ha föltámad a szél, mielőtt
Eggyé olvadnánk, el-szétszór örökre
A nagy világnak minden részibe,
És soha többé meg nem leljük egymást.
Iparkodjunk. A század viselős,
Születni fognak nagyszerű napok,
Élet-halálnak vészes napjai.
Fogjunk kezet, hogy rettegnünk ne kelljen
Az eljövendő óriásokat.
Tartsuk meg a szép, a szent kézfogást,
Tartsuk meg azt, oh édes nemzetem!
Ki legelőször nyujtja ki kezét,
Azé legyen a hála s a dicsőség;
S ki elfogadni azt vonakodik?
Annak porára szálljon minden átok,
Melyet sirunkra majd virág helyett
Ültetni fognak maradékaink,
Kiket örökre megnyomoritánk!','Barangol és zúg, zúg az őszi szél.
Csörögnek a fák száraz lombjai,
Mint rab kezén a megrázott bilincs.
Hallgass, zugó szél, hadd beszéljek én!','Koltó, 1846. október 26.',1846,'1846',array['Természet','Haza']::text[],'{}'::text[],false,527,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184607-126','petofi','Szeretsz tehát...','Szeretsz tehát, kedves szép angyalom?
Szeretsz valóban, én nem álmodom!
De mért hagyád a végső pillanatnak:
Megfejtését e drága szent titoknak?

Egy pillanat hozá meg üdvemet
És elválási gyötrelmeimet;
Ugy jártam, mint ki palotát építtet,
S midőn fölépül, számkiűzik őtet.

Sovár szivemre föl nem tűzhetéd
Az ölelésnek tündér gyűrüjét;
Nem szakíthattam ajkad szép bokrárul
Egy csókvirágot édes útitársul.

Távol tetőled oly bús életem!
De egy eszmével meg-megszépitem:
Egykor mi mélyen, mélyen szállok én be
A viszonlátás gyönyörtengerébe!','Szeretsz tehát, kedves szép angyalom?
Szeretsz valóban, én nem álmodom!
De mért hagyád a végső pillanatnak:
Megfejtését e drága szent titoknak?','Koltó, 1846. október 26. - november 5.',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,528,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184607-127','petofi','Mikor a lánc lehull...','Mikor a lánc lehull
A rab lábairul,
Még sokáig ugy jár,
Mintha rajta volna,
A szomorú terhet
Annyira megszokta.

Te is, hogy megszoktad,
Szívem, a fájdalmat,
Most, mikor jósorsom
Rólad azt lerázta,
Nem tudsz még örülni
Istenigazába''.

Örülj, örülj, szivem!
Ki örül, ha te nem?
Kinek van, mint neked,
Ilyen boldogsága?
Kinek van a földön
Ilyen mennyországa?','Mikor a lánc lehull
A rab lábairul,
Még sokáig ugy jár,
Mintha rajta volna,','Koltó, 1846. október 26. - november 5.',1846,'1846',array['Haza']::text[],'{}'::text[],false,529,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184607-128','petofi','Busúlnak a virágok...','Busúlnak a virágok,
Szegénykék betegek.
Nincs messze már halálok,
Mert a tél közeleg.

Miként az aggastyánnak
Megőszült fürtei,
Ugy hullanak a fáknak
Sárgult levelei.

Hiába a vidéken
Körültekintenem,
Nincs a nagy messzeségben
Egy zöld bokrocska sem.

Van egy! majd elfeledtem...
Lelkem, te vagy, te vagy
A zöld bokor, amelyben
Az ősz nyomot nem hagy;

Rajtad folyvást teremnek
S fognak virítani
A boldog szerelemnek
Örökzöld lombjai.','Busúlnak a virágok,
Szegénykék betegek.
Nincs messze már halálok,
Mert a tél közeleg.','Koltó, 1846. október 26. - november 5.',1846,'1846',array['Természet']::text[],'{}'::text[],false,530,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184607-129','petofi','Rövidre fogtam a kantárszárat...','Rövidre fogtam a kantárszárat,
Régóta fut a lovam, kifáradt,
Szájában tajtékos a zabola,
Sarkantyúmtól véres az oldala.

Egy gondolat kergetett engemet,
Ha galambom az enyim nem lehet!
Mint hegyes nyílvessző a madarat,
Úgy űzött engem ez a gondolat.

Lassan, lassan, jó lovam, lassan járj,
Ez a rosz gondolat elmaradt már,
Egy kökényfa bokrában megakadt,
A bokor tüskéi közt szétszakadt.

Kökényszemeket szerettem hajdan,
De szerencsés ezekkel nem voltam.
Most fekete szem tőrébe estem,
Ennél tán majd megsegít az isten.','Rövidre fogtam a kantárszárat,
Régóta fut a lovam, kifáradt,
Szájában tajtékos a zabola,
Sarkantyúmtól véres az oldala.','Koltó, 1846. október 26. - november 5.',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,531,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184607-130','petofi','Kellemetlen őszi reggel...','Kellemetlen
Őszi reggel.
Kedvtelen, borús idő.
Hulldogál az
Elvirított
Őszi tájra az eső.

A szobában
Ketten űlünk
Együtt: én s az unalom.
Terhes vendég!
Mint malomkő
Csügg rajtam. De megcsalom.

Szépen titkon
A szobából
Kiröpítem lelkemet.
Szállj, lelkem, szállj
Messze, messze...
Útad napnyugatra vedd.

Napnyugatra
Vannak, akik
Én előttem kedvesek:
Agg szülők és
Ifju lyányka
S mind, akiket szeretek.

Járd be őket,
Járd be sorra,
S jőj meg késő est felé
Édességgel
Megterhelve,
Mint virágokról a méh.','Kellemetlen
Őszi reggel.
Kedvtelen, borús idő.
Hulldogál az','Koltó, 1846. október 26. - november 5.',1846,'1846',array['Természet','Szerelem']::text[],array['osz']::text[],false,532,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184607-131','petofi','Véres napokról álmodom...','Véres napokról álmodom,
Mik a virágot romba döntik,
S az ó világnak romjain
Az új világot megteremtik.

Csak szólna már, csak szólna már
A harcok harsány trombitája!
A csatajelt, a csatajelt
Zajongó lelkem alig várja!

Örömmel vágom én magam
Föl paripámra a nyeregbe!
A bajnokok sorába én
Szilaj jókedvvel nyargalok be!

Ha megvagdalják mellemet,
Fog lenni, aki bekötözze,
Fog lenni, aki sebemet
Csókbalzsammal forrasztja össze.

Ha rabbá tesznek, lesz aki
Homályos börtönömbe jő el,
S föl fogja azt deríteni
Fényes hajnalcsillag-szemével.

Ha meghalok, ha meghalok
A vérpadon vagy csatatéren,
Lesz, aki majd holttestemről
Könyűivel lemossa vérem!','Véres napokról álmodom,
Mik a virágot romba döntik,
S az ó világnak romjain
Az új világot megteremtik.','Berkesz, 1846. november 6.',1846,'1846',array['Természet']::text[],'{}'::text[],false,533,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184607-132','petofi','Gróf teleky sándorhoz','Te elfáradsz, mig őseidnek
Végigtekintesz névsorán,
Én jóformán azt sem tudom, hogy
Ki és mi volt a nagyapám.
Te fényes, csilláros teremben
Bárson pólyában születél,
Én szalmazsákon születém egy
Kis mécs borongó fényinél.
Téged sétára cifra hintón
Négy, öt szép drága ló ragad,
Én az apostolok postáján
Viszem sétára magamat.
Bősége van mindennek nálad,
Amit kiván a száj s a szem,
Nekem ma még csak van mit enni,
Holnap talán már éhezem.
Szóval: nagy úr vagy és én koldus,
S mégis, légy büszke rá, igen,
Légy büszke rá, jó gróf druszám, hogy
Itten nyugodtál keblemen.
Mert, hej nem mindenik nagy úrnak
Jut a szerencse, elhihetd.
Hogy megöleljem s barátomnak
Nevezzem, úgy, mint tégedet.
S mért tettem ezt? mert... de nem szükség,
Hogy elbeszéljem érdemed:
Már az elég dicséretedre,
Hogy itt könyvemben áll neved.','Te elfáradsz, mig őseidnek
Végigtekintesz névsorán,
Én jóformán azt sem tudom, hogy
Ki és mi volt a nagyapám.','Koltó, 1846. november 7-10.',1846,'1846',array['Természet']::text[],'{}'::text[],false,534,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184607-133','petofi','Világoskék a csillagos éjszaka...','Világoskék a csillagos éjszaka,
Tárva-nyitva szobámnak az ablaka,
Az ablakból tekintetem az égen,
Lelkem pedig angyalomnak ölében.

A csillagos ég és az én angyalom
Mindennél szebb, ami csak szép, mondhatom.
Én legalább a világot bejártam,
De ezeknél szebbet sehol nem láttam.

Fogytán van a hold, úgy ballag lefelé
A megé a messze kéklő hegy megé.
A fogyó hold talán az én bánatom,
Oly halvány, hogy már csak alig láthatom.

Magasan áll a Fiastyúk az égen,
Szólanak a kakasok a vidéken,
Hajnalodik, hüvös csipős szél támad,
Hüvös szárnya legyintgeti orcámat.

Itt hagynám már ablakom, hogy elmenjek
Lefekünni és álmodni; de minek?
Álmodni ugysem tudnék én oly szépet,
Mint amily szép most előttem az élet.','Világoskék a csillagos éjszaka,
Tárva-nyitva szobámnak az ablaka,
Az ablakból tekintetem az égen,
Lelkem pedig angyalomnak ölében.','Koltó, 1846. november 7-10.',1846,'1846',array['Természet']::text[],'{}'::text[],false,535,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184607-134','petofi','Kovács jánosné emlékkönyvébe','Jellemtelenség e kor bélyege;
Pedig csak egy, csak egy: a jellem az,
Ami az embert emberré teszi,
E nélkül hitvány, öntudatlan tárgyak,
Vagy legfölebb is állatok vagyunk.
Oh hölgy! könyörgök hozzád, a haza
S az emberiség kettős szent nevében:
Ha gyermekekkel áld meg majd az isten,
Olts gyermekid szivébe jellemet,
Szeplőtelent s megtántoríthatatlant.
És nem szükség, hogy mást is adj nekik,
Mindent adál, ha jellemet adál.','Jellemtelenség e kor bélyege;
Pedig csak egy, csak egy: a jellem az,
Ami az embert emberré teszi,
E nélkül hitvány, öntudatlan tárgyak,','Debrecen, 1846. november 15.',1846,'1846',array['Gyermekkor']::text[],'{}'::text[],false,536,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184607-135','petofi','E. R. kisasszony emlékkönyvébe','Tavasszal menj ki a szabadba,
Hol fris patak suttog szaladva,
Kergetvén az est szellejét,
Mely a virágok illatával
És a csalogányok dalával
Fut a mezőben szerteszét,
Míg mosolyogva néz le rája
A csillagok s a hold sugára. -
S ha patakzajjal, madarak dalával,
Virágillattal, csillag- s holdsugárral
Ifjúi lelked, lyányka, megtelik,
Eredj haza, s aludjál reggelig,
És amit ekkor álmodol jót, szépet,
Adja meg mindazt a jövendő néked!','Tavasszal menj ki a szabadba,
Hol fris patak suttog szaladva,
Kergetvén az est szellejét,
Mely a virágok illatával','Debrecen, 1846. november 15.',1846,'1846',array['Természet']::text[],'{}'::text[],false,537,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184607-136','petofi','K. J. kisasszony emlékkönyvébe','Szived bölcsőben fekvő csecsemő;
Ott fekszik és még mélyen alszik ő,
De majd fölébred és keservesen sír...
Akkor, szép gyermekem,
Legyen szelíden ringató dajkája
A nyájas szerelem.','Szived bölcsőben fekvő csecsemő;
Ott fekszik és még mélyen alszik ő,
De majd fölébred és keservesen sír...
Akkor, szép gyermekem,','Debrecen, 1846. november 15.',1846,'1846',array['Gyermekkor']::text[],'{}'::text[],false,538,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184607-137','petofi','Hazaértem...','Hazaértem és letettem
A vándorbotot kezembül,
S veszem a lantot helyébe;
Mely sokáig félretéve
Hallgatott, most ujra zendül.

Melyik a leglélekrázóbb,
A legfájóbb húr e lanton?
Azt verem, hogy ujjaimtól
A húr, s ennek hangjaitól
Bennem a szív megszakadjon!

Messze jártam, sokat láttam...
Sokat? oh nem! mindig egyet.
Azt, hogy a hon ereje fogy,
Hogy meghalni készülünk, hogy
Elfajult a magyar nemzet.

Alkotmányunk egy vásártér,
Melyen lelket adnak, vesznek,
Adnak-vesznek olcsó pénzért,
Egy kis címért, egy ebédért -
Jó éjszakát ily nemzetnek!

Elmegyünk a másvilágra,
S nem a magasról esünk le,
Mint madár, melyet lelőnek
Közeléből a felhőnek,
S onnan hull a mély tengerbe.

A pornak vagyunk lakói,
Az alacsony úti-pornak,
Nincsen emberméltóságunk,
Mint a féreg, csúszunk-mászunk,
Mint a férget, eltipornak.

Jaj azoknak, jaj azoknak,
Kiket magyar anyák szűltek,
S kik hazájok pusztulását,
Nemzetök végvonaglását
Nem nézhetik egykedvűleg!','Hazaértem és letettem
A vándorbotot kezembül,
S veszem a lantot helyébe;
Mely sokáig félretéve','Pest, 1846. november 20. után',1846,'1846',array['Haza','Természet']::text[],'{}'::text[],false,539,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184607-138','petofi','Mi van innen távol...','Mi van innen távol? a Tisza...
Mi van a Tiszán túl? Hortobágy...
Hortobágyon túl? egy szép leány,
Kihez lelkem visszavágy!

Szép leány, szép barna kisleány,
Tőled oh be messze estem el!...
Csak azt tudhatnám, hogy legalább
Néha rám emlékezel!

Engemet sokszor meglátogat
A jó angyal, az emlékezet,
És karon fog, s öntudatlanúl,
Kedvesem, hozzád vezet.

Az ős vár, melynek tündére vagy,
Mely a dombról a rónára lát,
Hol a kék Szamosban tölti a
Holdvilág az éjszakát,

És a kert a vári domb alatt,
És a kertben a tó partinál
A gyászfűzek néma lombjai -
Mindez, mind előttem áll.

Oh e kertben kert volt életünk,
Minden óránk benne egy virág;
Mult- s jövőnket a gazdag jelen
Koszorúi takarák. -

Lyányka, hogyha visszagondolod
E dicső kort: dobog-e szived?
Költ-e benned, mint énbennem, oly
Édes érzeményeket?

Várod-e ugy, mint én a napot,
Mely kettőnket összehoz megint?
Én hiszem, hogy e szép kor felé
Szép szemed gyakran tekint!','Mi van innen távol? a Tisza...
Mi van a Tiszán túl? Hortobágy...
Hortobágyon túl? egy szép leány,
Kihez lelkem visszavágy!','Pest, 1846. november 20. után',1846,'1846',array['Szerelem','Természet']::text[],'{}'::text[],false,540,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184607-139','petofi','Nem ért engem a világ','Nem ért engem a világ!
Nem fér a fejébe,
Egy embernek éneke
Hogy lehet kétféle?
Hogy dalolhat az jelenleg
Szívrepesztő bánatot,
Ki elébb egy pillanattal
Úgy örűlt, ugy vígadott?

Ember és polgár vagyok.
Mint ember mi boldog!
És mint polgár, lelkemen
Mily keservet hordok!
Az örömnek könnyét sírom,
Ha lyánykámra gondolok;
Fájdalomnak könnyét sírom,
Ha hazámhoz fordulok.

Keblemen a szerelem
Virágbokrétája,
Fejemen honszeretet
Töviskoronája;
Igy lantomra majd megsebzett
Homlokom vércseppje hull,
Majd egy illatos levelke
Bokrétám virágibul.','Nem ért engem a világ!
Nem fér a fejébe,
Egy embernek éneke
Hogy lehet kétféle?','Pest, 1846. november 20. után',1846,'1846',array['Természet','Szerelem']::text[],'{}'::text[],false,541,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184607-140','petofi','Reszket a bokor, mert...','Reszket a bokor, mert
Madárka szállott rá.
Reszket a lelkem, mert
Eszembe jutottál,
Eszembe jutottál,
Kicsiny kis leányka,
Te a nagy világnak
Legnagyobb gyémántja!

Teli van a Duna,
Tán még ki is szalad.
Szivemben is alig
Fér meg az indulat.
Szeretsz, rózsaszálam?
Én ugyan szeretlek,
Apád-anyád nálam
Jobban nem szerethet.

Mikor együtt voltunk,
Tudom, hogy szerettél.
Akkor meleg nyár volt,
Most tél van, hideg tél.
Hogyha már nem szeretsz,
Az isten áldjon meg,
De ha még szeretsz, úgy
Ezerszer áldjon meg!','Reszket a bokor, mert
Madárka szállott rá.
Reszket a lelkem, mert
Eszembe jutottál,','Pest, 1846. november 20. után',1846,'1846',array['Szerelem','Természet']::text[],'{}'::text[],false,542,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184607-141','petofi','Halhatatlan a lélek...','Halhatatlan a lélek, hiszem,
De más világba nem megy át,
Csak itt lenn a földön marad,
A földön él és vándorol.
Többek közt én, emlékezem,
Rómában Cassius valék,
Helvéciában Tell Vilmos,
Párizsban Desmoulins Kamill...
Itt is leszek tán valami.','Halhatatlan a lélek, hiszem,
De más világba nem megy át,
Csak itt lenn a földön marad,
A földön él és vándorol.','Pest, 1846. november 20. után',1846,'1846','{}'::text[],'{}'::text[],false,543,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184607-142','petofi','Láttál-e a róna felett...','Láttál-e a róna felett
Elszállni madársereget,
Ha rája lövének?
Igy szállnak az évek!
Egy pillanatig
Még hallani szárnysuhogásaikat,
Már a másikban alig
Kisérheti a szem a kétes utat,
Mely röptük iránya,
Melyet hasitottanak egyre rohanva;
És annakutána
Se'' híre, se'' hamva
Az egész karavánnak.
A messzeség
Ködében az ég
Felhőivel összefolyának.
S te állasz a néma, a puszta határon,
Tünődve: mi volt ez? való-e vagy álom?...','Láttál-e a róna felett
Elszállni madársereget,
Ha rája lövének?
Igy szállnak az évek!','Pest, 1846. december',1846,'1846',array['Természet']::text[],'{}'::text[],false,544,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184607-143','petofi','Karácsonkor','Énhozzám is benézett a karácson,
Tán csak azért, hogy bús orcát is lásson
És rajta egy pár reszkető könyűt.

Menj el, karácson, menj innen sietve,
Hiszen családok ünnepnapja vagy te,
S én magam, egyes-egyedűl vagyok.

Meleg szobám e gondolattól elhül.
Miként a jégcsap függ a házereszrül,
Ugy függ szivemről ez a gondolat.

Hej, be nem így volt, nem így néhanapján!
Ez ünnep sokszor be vigan viradt rám
Apám, anyám és testvérem között!

Oh aki együtt látta e családot,
Nem mindennapi boldogságot látott!
Mi boldogok valánk, mert jók valánk.

Embert szerettünk és istent imádtunk;
Akármikor jött a szegény, minálunk
Vigasztalást és kenyeret kapott.

Mi lett a díj? rövid jólét multával
Hosszú nagy inség... tenger, melyen által
Majd a halálnak révéhez jutunk.

De a szegénység énnekem nem fájna,
Ha jó családom régi lombos fája
Ugy állna még, mint álla hajdanán.

Vész jött e fára, mely azt szétszaggatta;
Egy ág keletre, a másik nyugatra,
S éjszakra a törzs, az öreg szülők.

Lelkem szülőim, édes jó testvérem,
Ha én azt a kort újolag megérem,
Hol mind a négyünk egy asztalhoz űl!...

Eredj, reménység, menj, maradj magadnak,
Oly kedves vagy, hogy hinnem kell szavadnak,
Ámbár tudom, hogy mindig csak hazudsz...

Isten veled, te szép családi élet!
Ki van rám mondva a kemény itélet,
Hogy vágyam űzzön és ne érjen el.

Nem nap vagyok én, föld és hold körében;
Mint vészt jelentő üstökös az égen,
Magányos pályán búsan bújdosom.','Énhozzám is benézett a karácson,
Tán csak azért, hogy bús orcát is lásson
És rajta egy pár reszkető könyűt.
Menj el, karácson, menj innen sietve,','Pest, 1846. december',1846,'1846',array['Család','Természet','Szerelem']::text[],'{}'::text[],false,545,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184607-144','petofi','A magyar nemzet','Járjatok be minden földet,
Melyet isten megteremtett,
S nem akadtok bizonyára
A magyar nemzet párjára.
Vajon mit kell véle tenni:
Szánni kell-e vagy megvetni? -
Ha a föld isten kalapja,
Hazánk a bokréta rajta!
Oly szép ország, oly virító,
Szemet-lelket andalító,
És oly gazdag!... aranysárgán
Ringatózik rónaságán
A kalászok óceánja;
S hegyeiben mennyi bánya!
És ezekben annyi kincs van,
Mennyit nem látsz álmaidban.
S ilyen áldások dacára
Ez a nemzet mégis árva,
Mégis rongyos, mégis éhes,
Közel áll az elveszéshez.
S szellemének országában
Hány rejtett gyöngy és gyémánt van!
S mindezek maradnak ott lenn.
Vagy ha épen a véletlen
Föl találja hozni őket,
Porban, sárban érnek véget,
Vagy az inség zivatarja
Őket messze elsodorja,
Messze tőlünk a világba,
Idegen nép kincstárába,
És ha ott ragyogni látjuk,
Szánk-szemünket rájok tátjuk,
S ál dicsőséggel lakunk jól,
Hogy ez innen van honunkból.
Ez hát nemes büszkeségünk,
Melyről annyiszor mesélünk?
Azzal dicsekedni váltig,
Ami szégyenünkre válik!...
Csak a magyar büszkeséget,
Csak ezt ne emlegessétek!
Ezer éve, hogy e nemzet
Itt magának hazát szerzett,
És ha jőne most halála,
A jövendő mit találna,
Mi neki arról beszélne,
Hogy itt hajdan magyar éle?
S a világtörténet könyve?
Ott sem lennénk följegyezve!
És ha lennénk, jaj minékünk,
Ezt olvasnák csak felőlünk:
"Élt egy nép a Tisza táján,
Századokig, lomhán, gyáván." -
Oh hazám, mikor fogsz ismét
Tenni egy sugárt, egy kis fényt
Megrozsdásodott nevedre?
Mikor ébredsz önérzetre?','Járjatok be minden földet,
Melyet isten megteremtett,
S nem akadtok bizonyára
A magyar nemzet párjára.','Pest, 1846. december',1846,'1846',array['Haza','Természet']::text[],'{}'::text[],false,546,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184607-145','petofi','Egy gondolat bánt engemet...','Egy gondolat bánt engemet:
Ágyban, párnák közt halni meg!
Lassan hervadni el, mint a virág,
Amelyen titkos féreg foga rág;
Elfogyni lassan, mint a gyertyaszál,
Mely elhagyott, üres szobában áll.
Ne ily halált adj, istenem,
Ne ily halált adj énnekem!
Legyek fa, melyen villám fut keresztül,
Vagy melyet szélvész csavar ki tövestül;
Legyek kőszirt, mit a hegyről a völgybe
Eget-földet rázó mennydörgés dönt le... -
Ha majd minden rabszolga-nép
Jármát megunva síkra lép
Pirosló arccal és piros zászlókkal
És a zászlókon eme szent jelszóval:
"Világszabadság!"
S ezt elharsogják,
Elharsogják kelettől nyúgatig,
S a zsarnokság velök megütközik:
Ott essem el én,
A harc mezején,
Ott folyjon az ifjui vér ki szivembül,
S ha ajkam örömteli végszava zendül,
Hadd nyelje el azt az acéli zörej,
A trombita hangja, az ágyudörej,
S holttestemen át
Fújó paripák
Száguldjanak a kivivott diadalra,
S ott hagyjanak engemet összetiporva. -
Ott szedjék össze elszórt csontomat,
Ha jön majd a nagy temetési nap,
Hol ünnepélyes, lassu gyász-zenével
És fátyolos zászlók kiséretével
A hősöket egy közös sírnak adják,
Kik érted haltak, szent világszabadság!','Egy gondolat bánt engemet:
Ágyban, párnák közt halni meg!
Lassan hervadni el, mint a virág,
Amelyen titkos féreg foga rág;','Pest, 1846. december',1846,'1846',array['Természet','Haza','Elmúlás']::text[],'{}'::text[],false,547,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184701-01','petofi','Szabadság, szerelem!','Szabadság, szerelem!
E kettő kell nekem.
Szerelmemért föláldozom
Az életet,
Szabadságért föláldozom
Szerelmemet.','Szabadság, szerelem!
E kettő kell nekem.
Szerelmemért föláldozom
Az életet,','Pest, 1847. január 1.',1847,'1847',array['Szerelem','Haza']::text[],'{}'::text[],false,548,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184701-02','petofi','Egy barátom az ifjúság...','Egy barátom az ifjúság,
Maholnap már ez is itt hágy,
S másra, tudom, helyébe nem
Akadok,
Jaj istenem, be magamra
Maradok.

Attól tartok, hogy ezután
Nem szeret már engem leány,
Vagy ha szeret, én nem tudom
Szeretni,
Kacsintanak, de hiába,
Szemei.

Attól tartok, hogy ezután
Nem gyűlölök már igazán,
Tán magam sem leszek rosz, de
Mi haszna?
Ha hidegen vállat rántok
A roszra.

Ha már ifjuságom elmegy,
Csak e kettő maradjon meg,
Legyek képes, aki hogyan
Érdemli,
Teljes szívből szeretni és
Gyűlölni.','Egy barátom az ifjúság,
Maholnap már ez is itt hágy,
S másra, tudom, helyébe nem
Akadok,','Pest, 1847. január',1847,'1847',array['Szerelem']::text[],'{}'::text[],false,549,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184701-03','petofi','Ha férfi vagy, légy férfi...','Ha férfi vagy, légy férfi,
S ne hitvány gyönge báb,
Mit kény és kedv szerint lök
A sors idébb-odább.
Félénk eb a sors, csak csahol;
A bátraktól szalad,
Kik szembeszállanak vele...
Azért ne hagyd magad!

Ha férfi vagy, légy férfi,
S ne szád hirdesse ezt,
Minden Demosthenesnél
Szebben beszél a tett.
Építs vagy ronts, mint a vihar,
S hallgass, ha műved kész,
Mint a vihar, ha megtevé
Munkáját, elenyész.

Ha férfi vagy, légy férfi,
Legyen elved, hited,
És ezt kimondd, ha mindjárt
Véreddel fizeted.
Százszorta inkább éltedet
Tagadd meg, mint magad;
Hadd vesszen el az élet, ha
A becsület marad.

Ha férfi vagy, légy férfi,
Függetlenségedet
A nagyvilág kincséért
Árúba ne ereszd.
Vesd meg, kik egy jobb falatért
Eladják magokat.
"Koldusbot és függetlenség!"
Ez légyen jelszavad.

Ha férfi vagy, légy férfi,
Erős, bátor, szilárd.
Akkor, hidd, hogy sem ember
Sem sors könnyen nem árt.
Légy tölgyfa, mit a fergeteg
Ki képes dönteni,
De méltóságos derekát
Meg nem görbítheti.','Ha férfi vagy, légy férfi,
S ne hitvány gyönge báb,
Mit kény és kedv szerint lök
A sors idébb-odább.','Pest, 1847. január',1847,'1847',array['Természet']::text[],'{}'::text[],false,550,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184701-04','petofi','Kutyakaparó','Kivül-belül szomorú csárda ez
A Kutyakaparó,
Éhen-szomjan szokott itt maradni
A jámbor útazó,
Mert eledelt nem kap, és hogyha csak
Rápillant borára,
Megátkozza Nóét, hogy szőlőt is
Vett be a bárkába.

A kis szobán hosszu vékony asztal
Nyujtózkodik végig,
Feldőléstül erőtlen lábai
Már csak alig védik.
Amily hosszu az asztal, mellette
Olyan hosszu a pad,
Közepe, nem a sok űlés, hanem
Vénség miatt horpad.

Átellenben az ágy. Réges-régen
Lehetett megvetve;
Lefekünni beléje, nem támad
Senkinek is kedve.
Fejét egyik vállára bocsátá
A pufók kemence,
Redők gyanánt tisztes agg homloka
Meg van repedezve.

Mogorva vén ember itt a csaplár,
Szavát sem hallani,
Szájat ő csak azért tart, hogy legyen
Mivel ásítani.
Ilyen a csaplár, a vén Dömötör;
Hát a felesége?
Ez takaros menyecske lehetett
Annak idejébe''.

De az idő a szegény jó asszonyt
Megviselte rútul,
Noha ötven, ötvenöt esztendőn
Még nem igen van túl.
Boglyas fakó haja beillenék
Repce-petrencének,
És melléje mindjárt szörnyü képe
Madárijesztőnek.

Ő sem igen beszél; s ha szól, száját
Szidalomra nyitja,
Hogy a vármegye a betyárokat
Már mind kipusztítja;
Még mikor a világ ezeké volt,
Ha nem csordult, cseppent,
De ezek híjával a kereset
Egészen megcsökkent. -

Odabenn a Kutyakaparóban
Igy forog a világ,
Ily szomorún, s az ember vidámabb
Dolgot kivűl se'' lát.
Ablaka csak egy van, és annak is
Üveg csak a fele,
Fele pedig ó kalendáriom
Kitépett levele.

Pendelyes gyerek voltam még, mikor
Az az eső esett,
Mely falának kétharmad részéről
Levitte a meszet,
S ami rajta imitt-amott maradt,
Az egészen sárga,
S korommal írt furcsa figurákkal
Van telefirkálva.

Pózna végén abroncs a cégére,
Ha véle összevesz
A szellő, mint az akasztott ember,
Oly búsan lengedez.
Jószágból a csaplárnak nem jutott
Egyéb egy kuvasznál;
A ház végén szundikál naphosszat,
Nem árt, nem is használ.

És amilyen maga ez a csárda,
Olyan a vidéke,
Körülötte a homokbuckáknak
Se'' hossza, se'' vége.
A meztelen homokban alig teng
Egy-két gyalogbodza,
Mely fekete gyümölcsét nyaranként
Kedvetlenül hozza.

A harangszó a távol falukból
Meghalni jár ide,
S az eltévedt madár körülnéz csak
S odább megy ízibe.
Még a nap sem süt itt úgy, mint máshol;
Bágyadtabb sugára,
Mintha szánakozva tekintene
Ez árva csárdára.

A csárdától vagy száz lépésnyire,
Kopár dombtetőn fent,
Senki által meg nem látogatva,
Áll egy régi kőszent;
Ennek is valaki egy kopott tarisznyát
Akasztott nyakába,
Mintha mondta volna: menj isten hirével,
Mit állsz itt hiába!','Kivül-belül szomorú csárda ez
A Kutyakaparó,
Éhen-szomjan szokott itt maradni
A jámbor útazó,','Pest, 1847. január',1847,'1847',array['Természet']::text[],'{}'::text[],false,551,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184701-05','petofi','Szomorú éj','Éjfél lesz, és én mégsem alhatom,
Mert gondomat el nem altathatom.
Mi fog történni vélem s a hazával?
E kettős kérdés tépi lelkemet.
Ah, nem érem be a magam bajával,
Még te is gyötresz, hazaszeretet!

Ez hát a költő sorsa, mindig ez,
Hogy örök vészű tengeren evez?
S mit ér, ha őt a haragos habokból
Mentő sajkával partra is tevék,
Ha itt az bántja, hogy mi lesz azokból,
Kik ott maradtak a hajóba'' még?

Apám, apám, mért is taníttatál,
Miért az eke mellett nem hagyál?
A könyvet szép, de csalfa tündér lakja;
Ha fölnyitod, megkapja szívedet,
És fölvisz a legragyogóbb csillagra,
De le nem hoz... a magasból levet.

Inkább a napba, mint a könyvbe nézz.
A napvilágtól szemed fénye vész.
Nem így a könyvvel; oly világ van ebben,
Mely erősíti még szemeidet,
S közel hoz mindent... s minden vajmi szebben
Tünik föl, hogyha távol nézheted.

Miért tanultam? mért nem maradék
Földmívelő, aminek szánt az ég?
Nem tölteném most kínos virrasztással
A végtelenbe nyúló éjszakát;
Lelkem fölött az álom víg dallással
Madár módjára ringatná magát.

Volnék földmíves, vagy volnék juhász!
Ki messze, kint a pusztákon tanyáz,
S mig ellegelget kolompolva nyája,
Ő hűs bokorba vészi bé magát,
S nem hallja senki sem, úgy fujdogálja
Saját kedvéért a kis furulyát.

Vasárnap tisztát venni hazajár,
Hol a szerelmes lyányka várja már.
A lyányka jó, friss, szereti a dolgot,
S oly szép, mint a megszületett tavasz;
Csókot kap és ád a juhász, s ő boldog,
Hiszi tehát, hogy a világ is az.','Éjfél lesz, és én mégsem alhatom,
Mert gondomat el nem altathatom.
Mi fog történni vélem s a hazával?
E kettős kérdés tépi lelkemet.','Pest, 1847. január',1847,'1847',array['Szerelem','Természet','Haza']::text[],'{}'::text[],false,552,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184701-06','petofi','A kutyák dala','Süvölt a zivatar
A felhős ég alatt;
A tél iker fia,
Eső és hó szakad.

Mi gondunk rá? mienk
A konyha szöglete.
Kegyelmes jó urunk
Helyheztetett ide.

S gondunk ételre sincs.
Ha gazdánk jóllakék,
Marad még asztalán,
S mienk a maradék.

Az ostor, az igaz,
Hogy pattog némelykor,
És pattogása fáj,
No de: ebcsont beforr.

S harag multán urunk
Ismét magához int,
S mi nyaljuk boldogan
Kegyelmes lábait!','Süvölt a zivatar
A felhős ég alatt;
A tél iker fia,
Eső és hó szakad.','Pest, 1847. január',1847,'1847',array['Természet']::text[],'{}'::text[],false,553,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184701-07','petofi','A farkasok dala','Süvölt a zivatar
A felhős ég alatt,
A tél iker fia,
Eső és hó szakad.

Kietlen pusztaság
Ez, amelyben lakunk;
Nincs egy bokor se'', hol
Meghúzhatnók magunk.

Itt kívül a hideg,
Az éhség ott belül,
E kettős üldözőnk
Kinoz kegyetlenül;

S amott a harmadik:
A töltött fegyverek.
A fehér hóra le
Piros vérünk csepeg.

Fázunk és éhezünk
S átlőve oldalunk,
Részünk minden nyomor...
De szabadok vagyunk!','Süvölt a zivatar
A felhős ég alatt,
A tél iker fia,
Eső és hó szakad.','Pest, 1847. január',1847,'1847',array['Természet']::text[],'{}'::text[],false,554,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184701-08','petofi','Palota és kunyhó','Miért vagy oly kevély, te palota?
Uradnak fényében kevélykedel?...
Azért van rajta gyémánt, hogy szive
Mezítelenségét takarja el.
Szakítsd le a cafrangokat,
Mit rá szolgája aggatott,
S nem ismersz isten munkájára,
Oly nyomorúság marad ott.

S hol vette gazdád ama kincseket,
Mik semmiből őt mindenné teszik?
Ott, hol a héja a kis madarat,
Mit szétszakít, melynek vérén hizik.
A héja vígan lakomáz,
S szomszéd bokornak fészkiben
Madárfiúk zokognak, várván
Anyjokra, mely meg nem jelen.

Fitogtasd csak, te gőgös palota,
Az orzott kincsek ragyogásait,
Ragyogj csak, ugysem ragyogsz már soká,
Meg vannak már számlálva napjaid.
S kivánom, hogy minél elébb
Láthassam omladékodat,
S hitvány lakóid összezúzott
Csontját az omladék alatt! - -

S te kis kunyhó a magas palota
Szomszédságában, mért szerénykedel?
Miért bújtál a lombos fák mögé,
Azért-e, hogy inséged födjed el?
Fogadj be, kis sötét szoba;
Nekem nem kell szép öltözet,
De szép szív... s a sötét szobákban
Találni fényes szíveket.

Szent a küszöb, melyen beléptem én,
Oh szent a szalmakunyhók küszöbe!
Mert itt születnek a nagyok, az ég
A megváltókat ide küldi be.
Kunyhóból jő mind, aki a
Világnak szenteli magát,
S a nép mégis mindenfelől csak
Megvetést és inséget lát.

Nem féljetek, szegény jó emberek,
Jön rátok is még boldogabb idő;
Ha mult s jelen nem a tiétek is,
Tiétek lesz a végtelen jövő. -
A földre hajtom térdemet
E szűk, de szent födél alatt:
Adjátok rám áldástokat, s én
Rátok adom áldásomat!','Miért vagy oly kevély, te palota?
Uradnak fényében kevélykedel?...
Azért van rajta gyémánt, hogy szive
Mezítelenségét takarja el.','Pest, 1847. január',1847,'1847',array['Természet']::text[],'{}'::text[],false,555,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184701-09','petofi','A XIX. Század költői','Ne fogjon senki könnyelműen
A húrok pengetésihez!
Nagy munkát vállal az magára,
Ki most kezébe lantot vesz.
Ha nem tudsz mást, mint eldalolni
Saját fájdalmad s örömed:
Nincs rád szüksége a világnak,
S azért a szent fát félretedd.

Pusztában bujdosunk, mint hajdan
Népével Mózes bujdosott,
S követte, melyet isten külde
Vezérül, a lángoszlopot.
Ujabb időkben isten ilyen
Lángoszlopoknak rendelé
A költőket, hogy ők vezessék
A népet Kánaán felé.

Előre hát mind, aki költő,
A néppel tűzön-vízen át!
Átok reá, ki elhajítja
Kezéből a nép zászlaját.
Átok reá, ki gyávaságból
Vagy lomhaságból elmarad,
Hogy, míg a nép küzd, fárad, izzad,
Pihenjen ő árnyék alatt!

Vannak hamis próféták, akik
Azt hirdetik nagy gonoszan,
Hogy már megállhatunk, mert itten
Az ígéretnek földe van.
Hazugság, szemtelen hazugság,
Mit milliók cáfolnak meg,
Kik nap hevében, éhen-szomjan,
Kétségbeesve tengenek.

Ha majd a bőség kosarából
Mindenki egyaránt vehet,
Ha majd a jognak asztalánál
Mind egyaránt foglal helyet,
Ha majd a szellem napvilága
Ragyog minden ház ablakán:
Akkor mondhatjuk, hogy megálljunk,
Mert itt van már a Kánaán!

És addig? addig nincs megnyugvás,
Addig folyvást küszködni kell. -
Talán az élet, munkáinkért,
Nem fog fizetni semmivel,
De a halál majd szemeinket
Szelíd, lágy csókkal zárja be,
S virágkötéllel, selyempárnán
Bocsát le a föld mélyibe.','Ne fogjon senki könnyelműen
A húrok pengetésihez!
Nagy munkát vállal az magára,
Ki most kezébe lantot vesz.','Pest, 1847. január',1847,'1847',array['Természet']::text[],'{}'::text[],false,556,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184701-10','petofi','Egressy Etelke','Ez a te lyányod, Gábor? én nem hihetem.
Barátom, ember lyánya ilyen nem lehet.
Csupán a képzelet s az is ritkán teremt
Ily kedves kisleányt, ily tündér gyermeket.

Shakspeare, kit úgy szeretsz, Shakspeare képzelete
Teremté e leányt egy boldog perciben,
S megtestesité a múzsa, ki téged ugy
Szeret, s ajándokúl hagyá ott kebleden.

Gyönyörrel nézem én e szép kis alakot,
De őt illetni kézzel szinte nem merem,
Még csak melléje is aggódva lépek én,
Félvén, hogy őt elfúja majd lehelletem.

Oly szellemi e lyány, oly tisztán szellemi!
Eszembe is jut róla a mesés világ;
Ily lényekkel lehettek az Olymp körűl
Megnépesítve a források és a fák.

S ha ő reám tekint... barátom, mondd neki,
Mondd meg leányodnak: ne nézzen énreám!
Ki gondolná, milyen fájó emlékezet
Kél bennem e szelíd szemeknek sugarán?

Ha ő reám tekint: előttem föltünik
Az első, gyermeki ártatlanság kora.
Amit már elveszték, még minden megjöhet;
Ez egy, mi nem jön el többé soha, soha! -

Boldog vagy, férfiú, és boldog vagy te, nő,
Kik azt mondjátok e lyánykának: gyermekem,
Hanem tinálatok még boldogabb lesz az,
Ki ekkép fogja majd szólítni: kedvesem!

Őt bírni, mily öröm, mily boldogság leszen.
Midőn e lyányka a világra született,
Az isten levevé a legszebb csillagot
Az égről, és szívnek tevé keblébe ezt.','Ez a te lyányod, Gábor? én nem hihetem.
Barátom, ember lyánya ilyen nem lehet.
Csupán a képzelet s az is ritkán teremt
Ily kedves kisleányt, ily tündér gyermeket.','Pest, 1847. január',1847,'1847',array['Szerelem','Gyermekkor']::text[],'{}'::text[],false,557,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184701-11','petofi','Szent sír','Messze, messze, messze,
Honnan a madár jő
Tavasz kezdetével,
Messze, messze, messze,
Hova a madár megy
Hűvös, ködös ősszel.

Messze tengerparton
Áll a szent sír, a zöld
Tenger sárga partján;
Vadbokor fölötte,
Rá sötét fátyolként
Árnyékot boritván.

E vadbokron kívül
Nem gyászolja senki
A dicső halottat,
Ki a zajos élet
Lejártával itt most
Század óta hallgat.

Végső volt honában,
Ki a szabadságért
Hősi kardot ránta,
Hogy lett volna híve
A sors, ha hazája
Sem volt hű iránta?

Számüzé magát, hogy
Gyáva nemzetét ne
Lássa; mert ha látná:
Megátkozná, míg a
Messzeségből néma
Fájdalommal néz rá.

Itten nézte a hős
A szülőföldéről
Ballagó felhőket,
Melyeken az estfény,
(Vagy talán honának
Szégyenpírja?) égett.

Itten űlt a parton,
S hallgatá a csendes
Tenger mormogását,
S gondolá, hogy hallja
Fölriadt népének
Távoli zugását.

S várta, várta, várta,
Mikor jön már a hír,
Hogy szabad hazája?
S addig várt, addig várt,
Míg a halál jött e
Hír helyett hozzája.

S otthon már nevét is
Alig ismerik; csak
Egy emlékszik rája,
Egyedűl csak egy... a
Költő, a szabadság
Ez örök-lámpája.','Messze, messze, messze,
Honnan a madár jő
Tavasz kezdetével,
Messze, messze, messze,','Pest, 1847. január',1847,'1847',array['Természet','Elmúlás','Haza']::text[],'{}'::text[],false,558,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184701-12','petofi','Ide, kislyány...','Ide, kislyány, ide hozzám, egy szóra,
Vagy ha tán jobb neven veszed: egy csókra,
Azt sem bánom, ha kettő lesz belőle,
De még ez is, ha ugy tetszik, pengőbe''.

Jer ide már, jer ide már, ha mondom,
Ne légy olyan akaratos, galambom!
Eszem azt a képmutató szivedet,
Ugyis tudom, hogy a csókot szereted.

Mit beszélsz, hogy nem értesz te hozzája?
Kopasz mentség! megtanítlak én rája,
Megtanítlak amugy hirtelenében,
Mert nekem ez már régi mesterségem.

Mestere voltam már gyerekkoromba'',
Lesbe álltam amott a kis ajtóba,
Ha jöttek az iskolából a lyányok,
Kiugrottam, csókkal estem utánok.

Add ide hát azt a piros kis szádat,
Most láttam az ólba menni anyádat,
Tudod, soká szedi össze a tojást,
Addig akár agyoncsókoljuk egymást!','Ide, kislyány, ide hozzám, egy szóra,
Vagy ha tán jobb neven veszed: egy csókra,
Azt sem bánom, ha kettő lesz belőle,
De még ez is, ha ugy tetszik, pengőbe''.','Pest, 1847. január',1847,'1847',array['Szerelem']::text[],'{}'::text[],false,559,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184701-13','petofi','Arany jánoshoz','TOLDI írójához elküldöm lelkemet
Meleg kézfogásra, forró ölelésre!...
Olvastam, költőtárs, olvastam művedet,
S nagy az én szivemnek ő gyönyörűsége.

Ha hozzád ér lelkem, s meg talál égetni:
Nem tehetek róla... te gyujtottad ugy fel!
Hol is tehettél szert ennyi jóra, ennyi
Szépre, mely könyvedben csillog pazar fénnyel?

Ki és mi vagy? hogy így tűzokádó gyanánt
Tenger mélységéből egyszerre bukkansz ki.
Más csak levelenként kapja a borostyánt,
S neked rögtön egész koszorút kell adni.

Ki volt tanítód? hol jártál iskolába?
Hogy lantod ily mesterkezekkel pengeted.
Az iskolákban nem tanulni, hiába,
Ilyet... a természet tanított tégedet.

Dalod, mint a puszták harangja, egyszerű,
De oly tiszta is, mint a puszták harangja,
Melynek csengése a rónákon keresztűl
Vándorol, s a világ zaja nem zavarja.

S ez az igaz költő, ki a nép ajkára
Hullatja keblének mennyei mannáját.
A szegény nép! olyan felhős láthatára,
S felhők közt kék eget csak néhanapján lát.

Nagy fáradalmait ha nem enyhíti más,
Enyhítsük mi költők, daloljunk számára,
Legyen minden dalunk egy-egy vigasztalás,
Egy édes álom a kemény nyoszolyára! -

Ezen gondolatok elmém környékezték,
Midőn a költői szent hegyre jövék fel;
Mit én nem egészen dicstelenül kezdék,
Folytasd te, barátom, teljes dicsőséggel!','TOLDI írójához elküldöm lelkemet
Meleg kézfogásra, forró ölelésre!...
Olvastam, költőtárs, olvastam művedet,
S nagy az én szivemnek ő gyönyörűsége.','Pest, 1847. február',1847,'1847',array['Természet']::text[],'{}'::text[],false,560,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184701-14','petofi','Három fiú','Szólt az édesapa legelső fiához,
Amint ez paripát nyergel és kantároz:
"Csapd vissza, fiam, a gyepre paripádat,
Ne űlj rá; ne hagyd itt szegény vén apádat!"

De felelt a fiú: "apám, el kell mennem,
Háború zajában hírt-nevet szereznem!"
S fölugrott a lóra, kengyelben két lába,
Sebes vágtatva ment háború zajába.

Hazajött a ló, de bezzeg üres nyerge,
Ott áll a kapunál kapálva, nyerítve.
Hova lett gazdája? ellenség leszúrta,
Fejét lenyiszálta és karóra húzta. -

Szólt az édesapa középső fiához,
Amint ez paripát nyergel és kantároz:
"Csapd vissza, fiam, a gyepre paripádat,
Ne űlj rá: ne hagyd itt szegény vén apádat!"

De felelt a fiú: "apám, el kell mennem,
Minden úton-módon kincseket szereznem!"
S fölugrott a lóra, kengyelben két lába,
Sebes vágtatva ment erdők vadonába.

Hazajött a ló, de bezzeg üres nyerge,
Ott áll a kapunál kapálva, nyerítve.
Hova lett gazdája? rabla, fosztogata,
A nemes vármegye végre megsokalta.

Egyszer borozgatott fényes jókedvébe'',
Elfogták, s bevitték tömlöc-sötétségbe.
Nedves tömlöc-falról sok víz csorga rája,
Kivitték száradni az akasztófára. -

Szólt az édesapa legkisebb fiához:
"Eredj fiam, te is, nyergelj és kantározz;
Szerezz hírt és kincset, kövesd két bátyádat,
Menj te is, menj, hagyd el szegény vén apádat!"

De felelt a fiú: "apám, én nem megyek,
Hírvágy, kincsvágy soha nem bántott engemet.
Gondolatom sem száll falu határán túl;
Ásó-kapa választ el minket egymástul."

Állott is szavának, szent volt fogadása.
Nem lett híre, kincse, de lett boldogsága,
S apjával fogadta őt be egy sírverem,
Rajta zöld pázsit és tarka virág terem.','Szólt az édesapa legelső fiához,
Amint ez paripát nyergel és kantároz:
"Csapd vissza, fiam, a gyepre paripádat,
Ne űlj rá; ne hagyd itt szegény vén apádat!"','Pest, 1847. február',1847,'1847',array['Család']::text[],'{}'::text[],false,561,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184701-15','petofi','Magyar vagyok','Magyar vagyok. Legszebb ország hazám
Az öt világrész nagy terűletén.
Egy kis világ maga. Nincs annyi szám,
Ahány a szépség gazdag kebelén.
Van rajta bérc, amely tekintetet vét
A Kaszpi-tenger habjain is túl,
És rónasága, mintha a föld végét
Keresné, olyan messze-messze nyúl.

Magyar vagyok. Természetem komoly,
Mint hegedűink első hangjai;
Ajkamra fel-felröppen a mosoly,
De nevetésem ritkán hallani.
Ha az öröm legjobban festi képem:
Magas kedvemben sírva fakadok;
De arcom víg a bánat idejében,
Mert nem akarom, hogy sajnáljatok.

Magyar vagyok. Büszkén tekintek át
A multnak tengerén, ahol szemem
Egekbe nyúló kősziklákat lát,
Nagy tetteidet, bajnok nemzetem.
Európa színpadán mi is játszottunk,
S mienk nem volt a legkisebb szerep;
Ugy rettegé a föld kirántott kardunk,
Mint a villámot éjjel a gyerek.

Magyar vagyok. Mi mostan a magyar?
Holt dicsőség halvány kisértete;
Föl-föltünik s lebúvik nagy hamar
- Ha vert az óra - odva mélyibe.
Hogy hallgatunk! a második szomszédig
Alig hogy küldjük életünk neszét
S saját testvérink, kik reánk készítik
A gyász s gyalázat fekete mezét.

Magyar vagyok. S arcom szégyenben ég,
Szégyenlenem kell, hogy magyar vagyok!
Itt minálunk nem is hajnallik még,
Holott máshol már a nap úgy ragyog.
De semmi kincsért s hírért a világon
El nem hagynám én szülőföldemet,
Mert szeretem, hőn szeretem, imádom
Gyalázatában is nemzetemet!','Magyar vagyok. Legszebb ország hazám
Az öt világrész nagy terűletén.
Egy kis világ maga. Nincs annyi szám,
Ahány a szépség gazdag kebelén.','Pest, 1847. február',1847,'1847',array['Haza','Természet','Szerelem']::text[],'{}'::text[],false,562,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184701-16','petofi','Keserű élet, édes szerelem','Másnak szívem mindig jót kivánt,
S engem mégis minden ember bánt.
Szétszaggatják rajtam takarómat
S tüskékkel tömik meg vánkosom;
Reggelenként aztán kinevetnek,
Amiért rémekkel álmodom.
Cseppenj bé keserü életem
Poharába, édes szerelem!

Meghasadt lant keblem; húrjain
Vad kezekkel nyargal át a kín,
S olyan a dal, melyet rajta penget,
Mint a szélbe zúgó tőzharang.
Néha téved a harmóniátlan
Hangzavarba egy-két tiszta hang.
Cseppenj bé keserü életem
Poharába, édes szerelem!

Ez az egy, mi tépett lelkemet
Összeolvaszthatná némileg;
Ez az egy fa, mit kétségb''esésem
Vízözönje még el nem lepett,
Melynek ágán bujdosó reményem
Még lel egy kis menedékhelyet.
Cseppenj bé keserü életem
Poharába, édes szerelem!

Lyányka, tőled egy tekintetet,
Milyet a nap őszi tájra vet,
Melynek nincs már éltető erője,
S mégis olyan kedves, olyan szép!
Mert meghozza boldogabb napoknak,
A tavasznak emlékezetét.
Cseppenj bé keserű életem
Poharába, édes szerelem!','Másnak szívem mindig jót kivánt,
S engem mégis minden ember bánt.
Szétszaggatják rajtam takarómat
S tüskékkel tömik meg vánkosom;','Pest, 1847. február',1847,'1847',array['Szerelem','Természet']::text[],'{}'::text[],false,563,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('c19','petofi','A Tisza','Nyári napnak alkonyúlatánál
Megállék a kanyargó Tiszánál
Ott, hol a kis Túr siet beléje,
Mint a gyermek anyja kebelére.

A folyó oly símán, oly szelíden
Ballagott le parttalan medrében,
Nem akarta, hogy a nap sugára
Megbotoljék habjai fodrába''.

Síma tükrén a piros sugárok
(Mint megannyi tündér) táncot jártak,
Szinte hallott lépteik csengése,
Mint parányi sarkantyúk pengése.

Ahol álltam, sárga föveny-szőnyeg
Volt terítve, s tartott a mezőnek,
Melyen a levágott sarju-rendek,
Mint a könyvben a sorok, hevertek.

Túl a réten néma méltóságban
Magas erdő: benne már homály van,
De az alkony üszköt vet fejére,
S olyan, mintha égne s folyna vére.

Másfelől, a Tisza tulsó partján,
Mogyoró- s rekettye-bokrok tarkán,
Köztök egy csak a nyilás, azon át
Látni távol kis falucska tornyát.

Boldog órák szép emlékeképen
Rózsafelhők usztak át az égen.
Legmesszebbről rám merengve néztek
Ködön át a mármarosi bércek.

Semmi zaj. Az ünnepélyes csendbe
Egy madár csak néha füttyentett be,
Nagy távolban a malom zugása
Csak olyan volt, mint szunyog dongása.

Túlnan, vélem átellenben épen,
Pór menyecske jött. Korsó kezében.
Korsaját mig telemerítette,
Rám nézett át; aztán ment sietve.

Ottan némán, mozdulatlan álltam,
Mintha gyökeret vert volna lábam.
Lelkem édes, mély mámorba szédült
A természet örök szépségétül.

Oh természet, oh dicső természet!
Mely nyelv merne versenyezni véled?
Mily nagy vagy te! mentül inkább hallgatsz,
Annál többet, annál szebbet mondasz. -

Késő éjjel értem a tanyára
Fris gyümölcsből készült vacsorára.
Társaimmal hosszan beszélgettünk.
Lobogott a rőzseláng mellettünk.

Többek között szóltam én hozzájok:
"Szegény Tisza, miért is bántjátok?
Annyi rosszat kiabáltok róla,
S ő a föld legjámborabb folyója."

Pár nap mulva fél szendergésemből
Félrevert harang zugása vert föl.
Jön az árvíz! jön az árvíz! hangzék,
S tengert láttam, ahogy kitekinték.

Mint az őrült, ki letépte láncát,
Vágtatott a Tisza a rónán át,
Zúgva, bőgve törte át a gátot,
El akarta nyelni a világot!','Nyári napnak alkonyúlatánál
Megállék a kanyargó Tiszánál
Ott, hol a kis Túr siet beléje,
Mint a gyermek anyja kebelére.','Pest, 1847. február',1847,'1847',array['Természet','Haza']::text[],array['nyar']::text[],false,564,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184701-18','petofi','A felhők','Ha én madár volnék: örökké
A felhők közt szállonganék.
Ha festő volnék: egyebet sem,
Csupán felhőket festenék.

Ugy kedvelem én a felhőket!
Megüdvözlöm mindegyiket
Érkeztekor, s elmondom néki
Távoztakor: isten veled.

Oh nékem olyan jó barátim
E tarka égi vándorok.
Ugy ismernek már, hogy talán még
Azt is tudják, mit gondolok.

Oly sokszor néztem én őket, ha
Szép halkan szenderegtenek
A hajnal és az alkony keblén,
Mint ártatlan kis gyermekek.

És néztem őket, hogyha jöttek
Mint haragos vad férfiak,
Hogy a viharral, e zsarnokkal,
Élet-halálra vívjanak.

És néztem, hogyha virrasztott a
Beteg ifjú, a holdvilág,
S ők halvány arccal ezt, miként hű
Lyánytestvérek, körűlfogák.

Láttam már minden változásban,
Melyen csak általmentenek;
S akármikor s akárhogy látom,
Mindég egyformán tetszenek.

Miért vonzódom úgy hozzájok?
Mert ők lelkemnek rokoni,
Mely mindig új s új alakot vált
S mégis folyvást az egykori.

Lehet még másban szinte hozzám
A felhőt hasonlítani:
Vannak neki, miként szememnek,
Könyűi és villámai.','Ha én madár volnék: örökké
A felhők közt szállonganék.
Ha festő volnék: egyebet sem,
Csupán felhőket festenék.','Pest, 1847. február',1847,'1847',array['Természet']::text[],'{}'::text[],false,565,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184701-19','petofi','Csuklyában jár a barát...','Csuklyában jár a barát,
Szentnek kell lennie,
Menyecskéknél, lyányoknál
Nincs őneki helye.

Kabátban jár a deák,
Ha mozog is szive,
Menyecskékhez, lyányokhoz
Korán még mennie.

Mentében jár a huszár,
Trombita megharsan,
Menyecskéktől, lyányoktól
Káplárhoz fut gyorsan.

Subában jár a juhász,
Kutyabaja néki,
Menyecskékkel, lyányokkal
Szép világát éli!','Csuklyában jár a barát,
Szentnek kell lennie,
Menyecskéknél, lyányoknál
Nincs őneki helye.','Pest, 1847. február',1847,'1847',array['Szerelem']::text[],'{}'::text[],false,566,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184701-20','petofi','A magyar ifjakhoz','Lesz-e gyümölcs a fán, melynek nincs virága?
Avvagy virág vagy te, hazám ifjúsága?...
Jaj az olyan kertnek,
Jaj még annak is, mert megverte az isten,
Ahol, mint ti vagytok, magyar ifjak, ilyen
Virágok teremnek!

Felhő alakjába lelkem átöltözik,
Ugy száll a hon fölött nyugattól keletig
Sötéten, csendesen:
Ha volna mennyköve, mint van a felhőnek,
Csapásitól, ifjak, sokan hevernétek
A port, élettelen.

Mert ti az életet meg nem érdemlitek,
Egész nagy csillagok voltak őseitek,
És ti? csak parányok!
Ne adja a balsors, hogy e szegény haza
Bajában reátok szorúljon valaha...
Ti meg nem ónátok.

Szivetek mindig-nyilt-ajtajú palota,
Tódulnak, tódulnak seregestül oda
Víg, zajos vendégek;
Garázda népséggel telik meg a terem,
S ezek között helye nincs az örömtelen
Honfiérzeménynek.

Sziveteknek alig marad egy szöglete,
Ahol titkon magát pók gyanánt szövi be
A hazaszeretet,
S ez is csak addig van, míg jön az önérdek,
És azt javasolja, hogy lesöpörjétek,
Mint hitvány szemetet.

Oh mily gyöngék vagytok! kiknél a hazának
Fénye nem ér annyit, mint a hiuságnak
Mulandó csilláma.
Oh mily gyöngék vagytok! nap süthetne rátok,
S e helyett kis lámpa, melyet körülálltok,
Nyomorú kis lámpa.

Szent hazaszeretet, mibe mártsam tollam?
Hogy dicső képedet híven lerajzoljam,
Oly híven, oly szépen,
Hogy megbűvöld, ki rád szemét fogja vetni,
Hogy örök tanyára tégy szert valamennyi
Magyar kebelében.

Ti bálványimádók, hiúság rabjai!
Jertek, gyilkot fogok szivembe mártani,
Hadd feccsenjen vére
Szét fejeitekre... tán sikere leszen.
Tán megtértek tőle... jertek hozzám ezen
Uj keresztelésre!','Lesz-e gyümölcs a fán, melynek nincs virága?
Avvagy virág vagy te, hazám ifjúsága?...
Jaj az olyan kertnek,
Jaj még annak is, mert megverte az isten,','Pest, 1847. február',1847,'1847',array['Haza','Természet','Szerelem']::text[],'{}'::text[],false,567,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184701-21','petofi','A szél','Ma lágyan suttogó, szelíd szellő vagyok,
Zöldelő mezőkön föl s alá sétálok,
Csókot lehelek a bimbók ajakára,
Édes meleg csókom hű szerelmi zálog.
"Nyíljatok, nyíljatok, tavasz szép leányi,"
Ezt sugom fülökbe, "nyíljatok, nyíljatok!"
És ők szemérmesen levetik leplöket,
S én szép keblökön a kéjtől elájulok.

Holnap süvöltő hang, vad fuvalom leszek,
Reszket előttem a bokor, mert fél tőlem,
Látja, hogy kezemben kés van, köszörült kés,
S tudja, hogy lombjait azzal lemetélem.
A virágoknak ezt sziszegem fülébe:
"Balga, könnyenhivő lyányok, hervadjatok!"
Ők hervadtan hullnak az ősz kebelére,
S én rajtok hidegen, gúnyosan kacagok.

Ma lágy szellő vagyok, csendes folyó gyanánt
Úszom át a léget néma nyúgalomban,
Létezésemet csak a kis méhe tudja,
Mely hazafelé tart a rétről fáradtan;
Ha fáradtan száll a kis méh a tehertől,
Melyet oldalán visz, melyből mézet készít,
Tenyeremre veszem a kicsiny bogarat,
Ugy segítem elő lankadt röpülésit.

Holnap vihar leszek, zúgó-bőgő vihar,
Szilaj paripámon a tengert bejárom,
S mint a tanító a csintalan gyermeknek,
Sötétzöld üstökét haragosan rázom.
Bejárom a tengert, s ha hajót találok:
Szárnyát, a lobogó vitorlát kitépem,
S árbocával írom a habokba sorsát,
Hogy nem fog pihenni többé kikötőben!','Ma lágyan suttogó, szelíd szellő vagyok,
Zöldelő mezőkön föl s alá sétálok,
Csókot lehelek a bimbók ajakára,
Édes meleg csókom hű szerelmi zálog.','Pest, 1847. február',1847,'1847',array['Természet','Szerelem']::text[],array['osz']::text[],false,568,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184701-22','petofi','Édes öröm, ittalak már...','Édes öröm, ittalak már,
És hova lett az a pohár,
Amelyből ittalak téged?
Összetörött, cseréppé lett.

Keserű bú, ittalak már,
És hova lett az a pohár,
Amelyből ittalak téged?
Összetörött, cseréppé lett.

Fényes nap a szív öröme,
Sötét felhő takarja be.
Sötét felhő a szív búja,
Szellő jön és odább fúja.

Olyan vagyok, mint az árnyék,
Mintha temetőben járnék.
Elmult idő, elmult idő,
Te vagy, te vagy a temető.

A temető éjjelében
Bolygótűz az én vezérem.
Mult napjaim sírja felett
Bolygótűz az emlékezet.

Mozdúlni kezd a levegő,
Halk, de hűvös fuvalom jő,
És tőlem suttogva kérdi:
Nem legjobb-e sosem élni?','Édes öröm, ittalak már,
És hova lett az a pohár,
Amelyből ittalak téged?
Összetörött, cseréppé lett.','Pest, 1847. február',1847,'1847',array['Természet','Elmúlás']::text[],'{}'::text[],false,569,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184701-23','petofi','Ujonnan visszajött a régi baj...','Ujonnan visszajött a régi baj,
Amely a másvilágnak követe,
S hozzám így szól: szedd össze magadat,
El fogsz utazni a föld mélyibe. -
Erőm fut, mint a gyáva hadsereg,
Itt hágy magamra, gyöngén, egyedűl,
És vérem, a vég-búcsuzásra tán,
Elhagyván arcomat, szivembe gyűl.

Mit tétovázol úgy, halál, miért
Meg nem halok? vagy mért vagyok beteg?
Félsz hozzám nyúlni, te hatalmas úr?
Vagy csak ijesztesz?... meg nem ijedek.
Ki az élettel, mint én, szembeszállt,
Az bátoran néz a halál szemébe!
Az élet rövid béke s hosszu harc
És a halál rövid harc s hosszu béke.

De még kár lenne érettem talán.
Oh keblemben még annyi dal szunyad,
Egész egy erdő magva, mely ha felnő,
Sok fáradt útasnak hüs árnyat ad.
S eddig csak írtam, hol van még a tett?
Piros betűk az ünnep napjai,
S így életemnek nincs még ünnepe,
Hogy az legyen, vérem kell ontani!

Megérem-e ezt én? vagy mielőtt
Rivalgó zaj közt harci paripára
Pattanhatnék föl: tán szép csendesen
Ráfektetnek majd szent Mihály lovára?
Ha meg kell halnom, hogyha most halok meg,
Jőj el sietve, kedves kikelet,
Jőj el hamar, hadd láss még egyszer engem,
Hogy lássalak még egyszer tégedet.

Kettőztesd meg lépésid, szép tavasz,
A déli tájról gyorsan jőj elő:
Ha már az élet oly borús vala,
Legyen halálom napján jó idő.
Jőj, drága vendég, s hozz virágokat,
- A föld most olyan rideg puszta rom -
Ha már virágtalan volt életem,
Legyen virágos legalább sirom!','Ujonnan visszajött a régi baj,
Amely a másvilágnak követe,
S hozzám így szól: szedd össze magadat,
El fogsz utazni a föld mélyibe. -','Pest, 1847. március 1.',1847,'1847',array['Természet','Elmúlás','Haza']::text[],'{}'::text[],false,570,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184702-24','petofi','A nép nevében','Még kér a nép, most adjatok neki!
Vagy nem tudjátok, mily szörnyű a nép,
Ha fölkel és nem kér, de vesz, ragad?
Nem hallottátok Dózsa György hirét?
Izzó vastrónon őt elégetétek,
De szellemét a tűz nem égeté meg,
Mert az maga tűz; ugy vigyázzatok:
Ismét pusztíthat e láng rajtatok!

S a nép hajdan csak eledelt kivánt,
Mivelhogy akkor még állat vala;
De az állatból végre ember lett,
S emberhez illik, hogy legyen joga.
Jogot tehát, emberjogot a népnek!
Mert jogtalanság a legrútabb bélyeg
Isten teremtményén, s ki rásüti:
Isten kezét el nem kerűlheti.

S miért vagytok ti kiváltságosok?
Miért a jog csupán tinálatok?
Apáitok megszerzék a hazát,
De rája a nép-izzadás csorog.
Mit ér, csak ekkép szólni: itt a bánya!
Kéz is kell még, mely a földet kihányja,
Amíg föltűnik az arany ere...
S e kéznek nincsen semmi érdeme?

S ti, kik valljátok olyan gőgösen:
Mienk a haza és mienk a jog!
Hazátokkal mit tennétek vajon,
Ha az ellenség ütne rajtatok?...
De ezt kérdeznem! engedelmet kérek,
Majd elfeledtem győri vitézségtek.
Mikor emeltek már emlékszobort
A sok hős lábnak, mely ott úgy futott?

Jogot a népnek, az emberiség
Nagy szent nevében, adjatok jogot,
S a hon nevében egyszersmind, amely
Eldől, ha nem nyer új védoszlopot.
Az alkotmány rózsája a tiétek,
Tövíseit a nép közé vetétek;
Ide a rózsa néhány levelét
S vegyétek vissza a tövis felét!

Még kér a nép, most adjatok neki;
Vagy nem tudjátok: mily szörnyű a nép,
Ha fölkel és nem kér, de vesz, ragad?
Nem hallottátok Dózsa György hirét?
Izzó vastrónon őt elégetétek,
De szellemét a tűz nem égeté meg,
Mert az maga tűz... ugy vigyázzatok:
Ismét pusztíthat e láng rajtatok!','Még kér a nép, most adjatok neki!
Vagy nem tudjátok, mily szörnyű a nép,
Ha fölkel és nem kér, de vesz, ragad?
Nem hallottátok Dózsa György hirét?','Pest, 1847. március',1847,'1847',array['Haza']::text[],'{}'::text[],false,571,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184702-25','petofi','Háboru volt...','Háború volt mindig éltem
Legszebb gondolatja,
Háború, hol vérét a szív
Szabadságért ontja!

Egy szentség van a világon,
Melyért fegyverünkkel
Sírunkat megásni méltó,
Melyért vérzenünk kell;

Ez a szentség a szabadság!
Őrültek valának
Mindazok, kik más egyébért
Éltet áldozának.

Békét, békét a világnak,
De ne zsarnokkénytől,
Békét csupán a szabadság
Fölszentelt kezéből.

Majd ha így lesz a világon
Általános béke,
Vessük akkor fegyverünket
Tenger fenekére.

De míg így nincs: addig fegyvert,
Fegyvert mindhalálig!
Tartson bár a háború az
Itélet napjáig!','Háború volt mindig éltem
Legszebb gondolatja,
Háború, hol vérét a szív
Szabadságért ontja!','Pest, 1847. március',1847,'1847',array['Haza']::text[],'{}'::text[],false,572,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184702-26','petofi','De mért is gondolok rá?...','De mért is gondolok rá?
Mért gyötrődöm?... hiszen
Még csak hírét sem hallom,
Még csak nem is izen.

Hát ily hamar felejt, ily
Hamar felejthetett?
Az még valószinűbb, hogy
Sohasem szeretett.

Azt tartják: nem a nyelv, de
A szem mond igazat.
Én hittem ezt, s hitemnek
Gyümölcse kárhozat.

Hittem szemének, amely
Azt mondá, hogy szeret...
Szégyeld magad, szégyeld, te
Könnyenhivő gyerek!

Most már egyéb nincs hátra,
Mint őt felejteni.
Ki innen, ki szivemből,
Emlékem kincsei!

Hajós vagyok, ki vészkor
Mindent tengerbe vét,
Hogy az üres hajóban
Megmentse életét.','De mért is gondolok rá?
Mért gyötrődöm?... hiszen
Még csak hírét sem hallom,
Még csak nem is izen.','Pest, 1847. március',1847,'1847',array['Szerelem']::text[],'{}'::text[],false,573,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184702-27','petofi','Az árva lyány','1

Csak egy lénnyel van kevesebb,
Mint tennap volt,
S nekem ugy tetszik: az egész
Világ kiholt.

Meghalt anyám, le is tevék
A sírba őt:
Lelkemből varrtam én reá
A szemfedőt.

Anyám, miért nem vitted el
Életemet,
Ha már belőle elvivéd
Az örömet?

Te nap valál, én sugarad.
Itt mért hagyál?
Hisz sugarát elviszi a
Nap, ha leszáll.

Beszélek hozzád; hallod-e
A bús panaszt?
Hiába van szóm, te, anyám,
Nem hallod azt.

Itt állok, ahol rajtad a
Sír halma kél.
S messzebb vagy mégis a világ
Legvéginél.

Midőn koporsód szögezék,
Ezt rebegém:
"Ébredj föl, kedves jó anyám,
Édes szülém!"

Fölkelt-e a föltámadás
Majd tégedet,
Kit gyermeked siralma sem
Ébreszthetett?!

2

Virasztánk kínosan
Anyám, te s én;
Kis mécsünk reszketett,
Haldokló éltedet
Jelképezvén.

Magam valék anyám
Fájdalminál;
De nem soká közénk
Egy vendég érkezék...
Jött a halál.

Anyácskám, édesem,
Jó szívedet
Keze megérinté,
S verése szűnt belé
S hidegedett.

Midőn közel vala
A szörnyü vég,
Mint hervadt fára le
Az ősz esős köde
Rád borulék.

Beléd akartam én
En éltemet
Csókolni... s oh szülém,
Te csókolád belém
A tiedet!

3

Virágot ültettem
Anyám sírhalmára,
Harmat nem is kell, mert
Könnyem csorog rája.

Még holta után is
Kedvét keresem én,
Ezen virágokat
Csak azért ültetém.

Kedvelője volt a
Virágoknak anyám,
Szép intését mintha
Még most is hallanám:

"Szeresd a virágot
És ne féltsd szívedet,
Mert, ki ezt szereti,
Rosz ember nem lehet;

A virág s az erény
Két atyafi-gyermek,
Egy szívben egymással
Nem ellenkezhetnek.

Tudod, mi a virág?
A földnek jósága;
Tudod, mi a jóság?
A lélek virága."

Virágot ültettem
Anyám sírhalmára.
Le az égből anyám,
Tekintesz-e rája?

Látod-e az égből
Viruló sírodat,
S viruló sírodnál
Hervadt leányodat?','1
Csak egy lénnyel van kevesebb,
Mint tennap volt,
S nekem ugy tetszik: az egész','Pest, 1847. március',1847,'1847',array['Természet','Család','Elmúlás']::text[],array['osz']::text[],false,574,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184702-28','petofi','Két sóhaj','Kecskemét városa
Siralomházában
Két ifjú legény űl
Nagy szomoruságban.

Hadd üldögéljenek!
Ugysem űlnek hónap,
Hónap ilyen tájon
Levegőben lógnak.

Előttök étel, bor,
De nem kell nekiek,
Hisz ők éhen-szomjan
Már ugysem halnak meg.

Előttök van a tál,
Előttök az üveg...
Az étel meghűlt, s a
Bor megmelegedett.

Csak ugy űldögélnek
Hallgatag kedvökben;
Nagyot sohajtanak
Egyszer mind a ketten.

"Ki után sohajtasz,
Édes jó pajtásom?"
- "Szeretőmhöz röpült
Az én sohajtásom.

Szeretőmhöz küldöm
Haldokló lelkemet,
Az egyetlenegyhez,
Ki engemet szeret.

Széles e világon
Senki meg se látott,
De kipótolta ő
Az egész világot.

Alig vettem észre,
Hogy meghalt az anyám,
Szegény jó leányzó
Ugy gondot viselt rám.

Áldom a jó lelkét,
Áldja meg az isten,
Soha életében
Egy könnyet se ejtsen!

Hát te, cimborám, te
Kiért sohajtottál?"
- "Az én sohajom is
Ott jár galambomnál.

Galamb?... majd mit mondok!
Kigyó, mérges kigyó.
Ő volt engemet a
Rosz utra csábító.

Miatta elhagytam
Jó öreg anyámat,
Aztán cserbe hagyott,
Szépen odább állott.

Átkozom-rosz lelkét
Verje meg az isten,
Holtig sírjon-ríjon,
Mást ne is tehessen.

Váljék pokolkővé
Mindenik könnycseppje,
S szivét elevenen
Hamúvá égesse!"','Kecskemét városa
Siralomházában
Két ifjú legény űl
Nagy szomoruságban.','Pest, 1847. március',1847,'1847',array['Szerelem']::text[],'{}'::text[],false,575,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184702-29','petofi','Mi volt nekem a szerelem?','Mi volt nekem
A szerelem?
Számos ízben könny patakja,
Gyönge sajka úszott rajta,
Benne lelkem volt a sajkás,
Hajtó szellőm a sohajtás.

Mi volt nekem
A szerelem?
Aggodalmak erdősége,
Hangzott sűrü közepébe
Farkasoknak ordítása,
Denevérek vijjogása.

Mi volt nekem
A szerelem?
Oktalan kis balga gyermek,
A pillangókat kerget,
Kergeti lélekszakadva,
Mig bebotlik egy árokba.

Mi volt nekem
A szerelem?
Holt remények szemfedője,
Sötét búbánatból szőve,
Vagy piros szekér, amelyen
Vesztőhelyre vittek engem.

Mi most nekem
A szerelem?
Rózsafán kis madárfészek,
Melyben vígan fütyürészek,
S ha földulja a fergeteg,
Odább szállok, mást építek.','Mi volt nekem
A szerelem?
Számos ízben könny patakja,
Gyönge sajka úszott rajta,','Pest, 1847. március',1847,'1847',array['Szerelem','Természet']::text[],'{}'::text[],false,576,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184702-30','petofi','Tedd le, bojtár, a subádat...','Tedd le, bojtár, a subádat,
Mennykő szántsa meg a hátad,
Látod, már a patak is letette,
Vele a langy tavasz letétette.

Falu végén foly a patak,
Fehér keble csak ugy dagad,
Dagad, dagad széles jókedvében,
Hogy az ég lenéz megint rá kéken.

Hová szállott a cinege?
Honnan jöttél, fülemile?
Akárhonnan, semmi gondom rája,
Csak te dalolj, bokrok furulyája.

Kizöldült a kis kert fája,
Mintha toll nőtt volna rája;
El ne röpülj, megtollasodott fa,
Hadd űljek rózsámmal árnyékodba.

Minek mégy a boltba, kislyány,
Pántlikát akarsz venni tán?
Nézd a mező szebb pántlikát árul,
Szebbet, ingyen, sok ezer virágbul.','Tedd le, bojtár, a subádat,
Mennykő szántsa meg a hátad,
Látod, már a patak is letette,
Vele a langy tavasz letétette.','Pest, 1847. március',1847,'1847',array['Természet']::text[],'{}'::text[],false,577,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184702-31','petofi','Világosságot!','Sötét a bánya,
De égnek benne mécsek.
Sötét az éj,
De égnek benne csillagok.
Sötét az ember kebele,
S nincs benne mécs, nincs benne csillag,
Csak egy kis hamvadó sugár sincs.
Nyomoru ész,
Ki fénynek hirdeted magad,
Vezess, ha fény vagy,
Vezess csak egy lépésnyire!
Nem kérlek én, hogy átvilágíts
A másvilágnak fátyolán,
A szemfedőn.
Nem kérdem én, hogy mi leszek?
Csak azt mondd meg, hogy mi vagyok
S miért vagyok?...
Magáért születik az ember,
Mert már magában egy világ?
Vagy ő csak egy gyürűje
Az óriási láncnak,
Melynek neve emberiség?
Éljünk-e önnön öröminknek,
Vagy sírjunk a síró világgal? -
Hány volt, ki más szivéből
Kiszíta a vért
Saját javára,
És nem lett büntetése!
S hány volt, ki más javáért
A vért kiontá
Saját szivéből,
S nem lett jutalma!
De mindegy; aki áldozatnak
Od''adja életét,
Ezt nem dijért teszi,
De hogy használjon társinak.
S használ-e vagy sem?
A kérdések kérdése ez,
És nem a "lenni vagy nem lenni?"
Használ-e a világnak, aki érte
Föláldozá magát?
Eljön-e a kor,
Melyet gátolnak a roszak
S amelyre a jók törekednek,
Az általános boldogság kora?
S tulajdonképen
Mi a boldogság?
Hisz minden ember ezt másban leli;
Vagy senki sem találta még meg?
Talán amit
Mi boldogságnak nevezünk,
A miljom érdek,
Ez mind egyes sugára csak
Egy új napnak, mely még a láthatáron
Túl van, de egykor feljövend.
Bár volna így!
Bár volna célja a világnak,
Bár emelkednék a világ
Folyvást, folyvást e cél felé,
Amíg elébb-utóbb elérné!
De hátha ugy vagyunk,
Mint a fa, mely virágzik
És elvirít,
Mint a hullám, amely dagad
Aztán lesímul,
Mint a kő, melyet fölhajítnak,
Aztán lehull,
Mint a vándor, ki hegyre mászik,
S ha a tetőt elérte,
Ismét leballag,
S ez így tart mindörökké:
Föl és alá, föl és alá...
Irtóztató, irtóztató!
Kit még meg nem szállott e gondolat,
Nem fázott az soha,
Nem tudja még: mi a hideg?
E gondolathoz képest
Meleg napsúgár a kigyó,
Mely keblünkön jégcsap gyanánt
Vérfagylalón végigcsuszik,
Aztán nyakunkra tekerőzik,
S torkunkba fojtja a lélekzetet - - -','Sötét a bánya,
De égnek benne mécsek.
Sötét az éj,
De égnek benne csillagok.','Pest, 1847. március',1847,'1847',array['Természet']::text[],'{}'::text[],false,578,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184702-32','petofi','Szőke asszony, szőke asszony...','Szőke asszony, szőke asszony,
Fehér hattyu, fehér hattyu!
Sorsod olyan fekete,
Mint a holló, mint a holló.

Mért adá neked az isten
E szépséget? vagyis inkább
Ezt a férjet mért adá,
Ki nem tudja, hogy mi a szép?

Kebeledbe mért tevé az
Isten ezt a gazdag szívet?
Ezt a tündér zongorát,
Mit nem tud pengetni férjed.

Oh ha én birnám e hangszert!...
Pillanatra érintém csak,
És dalától reszketett
Örömében a teremtés.

Vége, vége már e dalnak,
Elváltunk, és nem tudom, hogy
Nézek-e még valaha
Szép szemed kék csillagára?

Be-benéztem elmerengve
Gyönyörű kék szemeidbe,
Mint a tenger mélyibe
Néz a sajkás, holdas éjben.

De fölöttünk sötét felhő
Támadott, mely elborítá
A holdfényes éjszakát...
Férjed jött sötét orcával.

Szörnyü ember! van hatalma,
Tőled mindent megtagadni,
És a mellett van joga,
Tőled mindent követelni.

Meggyülöltem őt, meg; mert él
Hatalmával és jogával:
Tőled mindent követel,
És nem enged semmit, semmit.

Volnál képes őt szeretni?
És lehetnél véle boldog?
Soha, sohasem hiszem,
Noha mindig oly vidám vagy.

Mért mosolygál én előttem?
Engem el nem ámitottál;
Jól tudom, hogy a mosoly
Gyakran könnyek álorcája.

Jól tudom, hogy éjjelenként,
Hogyha férjed mélyen alszik,
Te virasztasz, mert szobád
És a város bármi csendes:

De szived rémek tanyája,
Melyek csengő poharakba
Töltik és isszák megölt
Örömidnek omló vérét.

Mit tevő légy? Mit tevő légy?
Legalább átkozd meg őket,
Átkozd meg, kik tégedet
Ily nyomoruságba löktek;

Mondj megsemmisítő átkot
Hajlékukra, ha még élnek,
És ha már meghaltanak,
Mondj átkot koporsójokra!...

Szegény asszony, hogy tennéd ezt?
Nem szabad megátkoznod, sőt
Tisztelned s szeretned kell,
Mert hiszen ezek szülőid. -

Szőke asszony, szőke asszony,
Fehér hattyu, fehér hattyu!
Sorsod olyan fekete,
Mint a holló, mint a holló.','Szőke asszony, szőke asszony,
Fehér hattyu, fehér hattyu!
Sorsod olyan fekete,
Mint a holló, mint a holló.','Pest, 1847. március',1847,'1847',array['Természet']::text[],'{}'::text[],false,579,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184702-33','petofi','Katonaélet','"Nehéz nekem már a bocskor,
Könnyü nekem már az ostor,
Csizmát húzok a lábamra,
Kardot fogok a markomba.
Muzsika szól, verbuválnak,
Fölcsapok én katonának, hahaha!"

Ezt az egyet bölcsen teszed;
Látom, már megjön az eszed.
Aranyélet, bizony isten!
Megpróbáltam, párja sincsen.
Muzsika szól, verbuválnak,
Csapj föl, öcsém, katonának, hahaha!

Katonának kutyabaja,
Van mit enni és innia,
Hogyna volna? öt napra jár
Tizenhat garas két krajcár.
Muzsika szól, verbuválnak,
Csapj föl, öcsém, katonának, hahaha!

Csak minden harmadnap strázsálsz,
Akkor is csak nyolc órát állsz,
Ha hideg van is, meg nem fagysz,
Ott a körmöd, belefujhatsz.
Muzsika szól, verbuválnak,
Csapj föl, öcsém katonának, hahaha!

Tisztogatás sem igen kell,
Minek is bajlódnál ezzel?
Ne félj: ha poros nadrágod,
Kiporozza a káplárod.
Muzsika szól, verbuválnak,
Csapj föl, öcsém katonának, hahaha!

És az embert hogy szeretik!
Visszaviszik, ha elszökik,
És azalatt, míg vesszőzik,
Sétál vagy fut, ahogy tetszik.
Muzsika szól, verbuválnak,
Csapj föl, öcsém, katonának, hahaha!

Ha pedig az időd lejárt,
Obsitot kapsz, de mekkorát!
S tudod, mért kapsz ilyen nagyot?
Hogy legyen itthon paplanod.
Muzsika szól, verbuválnak,
Csapj föl, öcsém katonának, hahaha!','"Nehéz nekem már a bocskor,
Könnyü nekem már az ostor,
Csizmát húzok a lábamra,
Kardot fogok a markomba.','Pest, 1847. március',1847,'1847',array['Család']::text[],'{}'::text[],false,580,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184702-34','petofi','A szerelem','Üljetek föl képzetemnek
Csónakára, s ússzatok.
Ússzatok szivem taván át,
Szép leányok, s asszonyok,
Mindnyájan, kiket szerettem,
Amióta szeretek,
Üljetek föl képzetemnek
Csónakára; jertek, jertek,
Hadd mulassak veletek.

És előjött valamennyi,
S istenemre, szép sereg!
És közöttök olyan is van,
Kit már alig ismerek,
Pedig őket mind egyenlőn,
Mind egy hévvel szeretém,
De hiába, a szerelmet
Még mint kicsi gyönge gyermek,
Régen, régen kezdtem én.

S ez mutatja bölcseségem!
Már mint gyermek bölcs valék.
Tudtam akkor már, amit más
Vén korában sem tud még,
Tudtam azt, hogy a világra
Csak egy nap süt melegen,
S ez a nap nem fönn az égen,
Hanem lenn a szív mélyében
Van, s e nap a szerelem.

Higyetek nekem ti, akik
Fáradoztok kincsekér'':
A föld minden gyémántjánál
Egy pár szép szem többet ér;
S higyetek ti, kiknek lelke
Hír-dicsőségért a vér
Vagy virasztás ösvényén megy:
Egész babérerdőnél egy
Rózsabimbó többet ér.

A fukar hadd számítgassa,
A gyülő aranyokat,
Mást számítok én... a kedves
Hölgyektől nyert csókokat.
S nékem a sors csak virággal
Ékesítse kalapom,
Nem kérek babért ujabban.
Sőt amit már eddig kaptam,
Ha kell, azt is vissz''adom.','Üljetek föl képzetemnek
Csónakára, s ússzatok.
Ússzatok szivem taván át,
Szép leányok, s asszonyok,','Székesfejérvár, 1847. március',1847,'1847',array['Szerelem','Természet']::text[],'{}'::text[],false,581,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184702-35','petofi','A virágok','Ki a mezőre ballagok,
Hol fű között virág terem,
Virágok, szép virágaim,
Be kedvesek vagytok nekem!
Ha látom, mintha lyányt látnék,
Szivem reszket, keblem dagad. -
Siromra, hogyha meghalok,
Ültessetek virágokat.

Leűlök a virág mellé,
És elbeszélgetek vele.
Szerelmet is vallok neki,
S megkérdem: engem szeret-e?
Nem szól, de úgy hiszem, hogy ért,
Hogy érti jól szavaimat. -
Siromra, hogyha meghalok,
Ültessetek, virágokat.

S ki tudja: az illat vajon
Nem a virág beszéde-e?
Csakhogy nem értjük, nem hat át
Testünkön lelkünk fülibe;
Szagolja csak s nem hallja meg
A test e szellemhangokat. -
Siromra, hogyha meghalok,
Ültessetek, virágokat.

Igen, az illat a virág
Beszéde, annak dala ez,
S ha lényem durvább része a
Sírban rólam lefejledez:
Nem szagolom többé, hanem
Hallom majd e szép dalokat. -
Siromra, hogyha meghalok,
Ültessetek virágokat.

Virágillat, virág dala,
Te lész majd ott bölcsődalom,
Melynek lágy zengedelminél
Tavaszonként elaluszom,
S következendő tavaszig
Lelkem szép álmakkal mulat. -
Siromra, hogyha meghalok,
Ültessetek virágokat.','Ki a mezőre ballagok,
Hol fű között virág terem,
Virágok, szép virágaim,
Be kedvesek vagytok nekem!','Pest, 1847. április',1847,'1847',array['Természet','Elmúlás','Szerelem']::text[],'{}'::text[],false,582,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184702-36','petofi','Kit feledni vágytam...','Kit feledni vágytam
S már-már elfeledtem,
Oh leány, mért tünsz föl
Ujra képzetemben?
Miért tünsz föl ujra
Piros orcáiddal,
Fekete szemeddel,
Fekete hajaddal?
Miért jut eszembe
Dús lelked kincstára,
Mely hét színbe játszik
Szivárvány módjára,
Melynek ellenállni
Hasztalan törekvés,
Mert bűvös háló az,
Honnan nincs menekvés.
Miért jut eszembe
A boldogság képe,
Mely, míg nálad voltam,
Szállt szivem fölébe,
Mint vándormadár, hogy
Ottan megpihenjen,
S megpihenvén, róla
Ismét elröppenjen.
Szép de nem jó csillag
Vitt engem tehozzád!
E csillag vezérli
A hajósok sorsát,
Kik egy ismeretlen
Hang után eveznek,
Amely vonja őket,
Míg örvénybe vesznek.
Mit használt, mit használt,
Tégedet találnom.
Ha megint eltűnél,
Mint az éji álom,
S most reményem is, e
Vakmerő kalandor,
Addig megy csak, hogy tán
Még meglátlak egykor,
De hogy összeforraszt
Véled ölelésem,
Oh ezt nem igéri
Még a reménység sem. -
Űzött a lemondás
A bú vadonába.
S hogy ennek határát
Keresém hiába,
Könnyelműség szárnyát
Vállaimra vettem,
És a csapodárság
Pillangója lettem.
Átröpűltem már nagy
Hosszu messzeséget,
Amidőn egyszerre
Utolért emléked,
S szárnyamat kitépte,
S átadott ujonnan
Régi bánatomnak,
Mely gyötör most jobban,
Mint a börtönőr a
Foglyot, aki tőle
Elszökött és aki
Ujra megkerűle.
Csörög lelkemen a
Fájdalom bilincse;
Lesz-e kéz, amely ezt
Róla lefeszítse?
Nyujtsd kezed, leányka,
Mondd ki, hogy szerettél,
És hogy ott vagy még a
Régi érzelemnél,
Mondd ki, hadd hulljon le
Fájdalmam bilincse,
A szép szabadságot
Lelkem hadd köszöntse!
És ha szeretél s ha
Még szeretsz: mi gátol,
Elszakadnod értem
Az egész világtól?
Én leszek világod,
És te istenem lész...
Oh jer karjaimba...
Vagy még többet remélsz?... -
Vagy ha szembeszállni
Nincs erőd a vésszel,
Melyet egyesűlő
Szerelmünk idéz fel,
Mondd, hogy a boldogság
Senki mástól nem kell,
S bárha tőlem örök
Elválás rekeszt el,
Hidd, hogy lelkeink e
Kínos állapotját
Még a boldogok is
Irigyelni fogják!','Kit feledni vágytam
S már-már elfeledtem,
Oh leány, mért tünsz föl
Ujra képzetemben?','Pest, 1847. április',1847,'1847',array['Szerelem','Természet']::text[],'{}'::text[],false,583,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184702-37','petofi','Az itélet','A történeteket lapozám s végére jutottam,
És mi az emberiség története? vérfolyam, amely
Ködbevesző szikláibul a hajdannak ered ki,
És egyhosszában szakadatlan foly le korunkig.
Azt ne higyétek, hogy megszűnt már. Nincs pihenése
A megeredt árnak, nincsen, csak a tenger ölében.
Vértengerbe szakad majd a vér hosszu folyója.
Rettenetes napokat látok közeledni, minőket
Eddig nem látott a világ; s a mostani béke
Ez csak ama sírcsend, amely villámnak utána
A földrendítő mennydörgést szokta előzni.
Látom fátyolodat, te sötét mélytitku jövendő,
És, meggyujtván a sejtés tündéri tüzét, e
Fátyolon átlátok, s attól, ami ott van alatta,
Borzadok, iszonyodom, s egyszersmind kedvre derűlök
És örülök szilajan. A háború istene újra
Fölveszi páncélját s kardját markába szorítván
Lóra ül és végigszáguld a messze világon,
És a népeket, eldöntő viadalra, kihíja.
Két nemzet lesz a föld ekkor, s ez szembe fog állni:
A jók s a gonoszak. Mely eddig veszte örökké,
Győzni fog itt a jó. De legelső nagy diadalma
Vértengerbe kerűl. Mindegy. Ez lesz az itélet,
Melyet igért isten, próféták ajkai által.
Ez lesz az ítélet, s ez után kezdődik az élet,
Az örök üdvesség; s érette a mennybe röpűlnünk
Nem lesz szükség, mert a menny fog a földre leszállni.','A történeteket lapozám s végére jutottam,
És mi az emberiség története? vérfolyam, amely
Ködbevesző szikláibul a hajdannak ered ki,
És egyhosszában szakadatlan foly le korunkig.','Pest, 1847. április',1847,'1847',array['Természet']::text[],'{}'::text[],false,584,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184702-38','petofi','Első esküm','Fiú valék még, iskolás fiú,
Tizenöt éves; és az iskolázás
Rám nézve nyűg volt, nagy nehéz nyűg, amely
Rajtam napestig szomorún csörömpölt,
S még álmaimból is föl-fölriasztott.
Lerázni vágytam e nyűgöt magamról,
Lerázni vágytam minden áron azt.
Már akkor, akkor úgy szerettelek,
Olyan világ-fölgyujtó szenvedéllyel,
Mint most szeretlek, drága szent szabadság! -
Gondolkodám a mód felől: miként
Szakíthatnám le rólam a bilincset?...
Szinészek jöttek, s elhatározám
Közéjök állni és elmenni vélök,
El, habár a földhözragadt nyomor
Mindkét kezével átölelne is,
Habár apámnak átka és anyámnak
Könyűi lesznek útitársaim,
Csak hogy szabad, hogy független legyek.
S elmentem volna, ámde megtudá
E lázadó szándékomat tanítóm,
S az indulásnak napján elfogott,
És rám csuká szobámnak ajtaját,
S rab voltam, míg a színésztársaság
Határunkon túl messze, messze járt.
Sírás, könyörgés, lárma, mindhiába!...
Nem az fájt már, hogy nem leszek szinész,
De hogy maradni kényszerítenek.
A kényszerítés égett lelkemen,
Mint a görögtűz, olthatatlanúl.
Itt tettem első esküvésemet,
Nagy és szent esküt mondék börtönömben,
Hogy életemnek egy főcélja lesz,
S ez: a zsarnokság ellen küzdeni.
S ez eskü most is olyan szent előttem,
Amilyen volt az első pillanatban,
S verjen meg engem a hatalmas isten,
Verjen meg még a másvilágon is,
Ha valaha ez esküt elfelejtem!','Fiú valék még, iskolás fiú,
Tizenöt éves; és az iskolázás
Rám nézve nyűg volt, nagy nehéz nyűg, amely
Rajtam napestig szomorún csörömpölt,','Pest, 1847. április',1847,'1847',array['Szerelem']::text[],'{}'::text[],false,585,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184702-39','petofi','A türelemről','Türelem, te a birkák s a
Szamarak dicső erénye,
Tégedet tanuljalak meg?
Menj a pokol fenekére!

Hogyha mint koldús járod be
A földet s kérsz menedéket:
Kérj akárhol, csak ne tőlem,
Szívem nem fogad be téged;

S ha bejárod, mint hódító,
Diadallal a világot;
Lesz egy szikla, s ez szivem lesz,
Melyre nevedet nem vágod.

Türelem, kicsépelt szalma,
Melyet a bárgyú világnak
Telt kalászokként árulnak,
Kik magodból jóllakának;

Te üres fazék, melyből a
Macska a tejfölt kiette,
S a szakácsné most szájtátva,
Fejcsóválva áll mellette.

Türelem, te... nem tudom, mi?
Mint gyülöllek, mint utállak!
Mert ahol van kezdeted, ott
Vége van a boldogságnak.

Oh a föld boldog lehetne,
Hogyha rajta te nem volnál,
S míg te rajta lész, mindaddig
Megmaradunk a nyomornál.

El veled, te élet átka,
El veled, le a pokolba!
Nyeljen el, ki rút pofádat
Erre a szép földre tolta!','Türelem, te a birkák s a
Szamarak dicső erénye,
Tégedet tanuljalak meg?
Menj a pokol fenekére!','Pest, 1847. április',1847,'1847','{}'::text[],'{}'::text[],false,586,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184702-40','petofi','F. A. emlékkönyvébe','Olvastad úgyebár a bibliába''
Az olajos-korsó történetét?
Az van megírva róla, hogy hiába
Ömlött, mert ujra mindig megtelék.

Ez olajos-korsó az élet kéje;
Azért kacagom a bolondokat,
Kik alig mártják nyelvöket beléje
Eszélytelen gazdálkodás miatt.

A bölcs hosszú kortyokban hajtogatja
E korsó édes nedvét untalan;
Mért gazdálkodnék? amidőn jól tudja,
Hogy minden percben ismét tele van.','Olvastad úgyebár a bibliába''
Az olajos-korsó történetét?
Az van megírva róla, hogy hiába
Ömlött, mert ujra mindig megtelék.','Pest, 1847. április 26.',1847,'1847',array['Természet']::text[],'{}'::text[],false,587,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184703-41','petofi','Rongyos vitézek','Föl tudnám én is öltöztetni
Szép rím- s mértékbe versemet,
Amint illő meglátogatni
A társasági termeket.

De eszméim nem henye ifjak,
Kik élnek, hogy mulassanak,
Hogy felfürtözve, kesztyűs kézzel
Látogatóba járjanak.

Nem cseng a kard, nem dörg az ágyú,
A rozsda-álom lepte meg;
De tart a harc... a kard s az ágyú
Helyett most eszmék küzdenek.

Ott állok én is a csatában
Katonáid közt, századom!
Csatázok verseimmel... egy-egy
Harcos legény minden dalom.

Rongyos legények, de vitézek,
Mind bátran harcol, bátran vág,
S a katonának bátorsága
Teszi diszét, nem a ruhák.

S nem kérdem én, hogy költeményim
Túlélnek-e majd engemet?
Ha el kell esniök talán e
Csatában: ám hadd essenek.

Még akkor is szent lesz a könyv, hol
Meghalt eszméim nyugszanak,
Mert hősök temetője az, kik
A szabadságért haltanak.','Föl tudnám én is öltöztetni
Szép rím- s mértékbe versemet,
Amint illő meglátogatni
A társasági termeket.','Pest, 1847. április',1847,'1847',array['Haza']::text[],'{}'::text[],false,588,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184703-42','petofi','Zöld Marci','Négyágú épűlet, amely be sincs fedve,
Mely akasztófának vagyon keresztelve,
Akasztófa mellett hollók károgása,
Nem volt Zöld Marcinak két országban mása.

Pej csikó szájában fényes acélzabla,
Hányta a szikrát, ha a csikó harapta.
Rajta, Zöld Marci, te futottál, röpültél,
Mint a lobogó láng, kit elkapott a szél.

Ugyancsak megteszi!... Marci, hol vehetted
Lobogó gatyádat, lobogó ingedet?
Szép menyecskék varrták fehér patyolatból,
Csók lett érte díjok piros ajakadról.

Szép legény volt Marci, szerették a lyányok.
Ha én utánam is annyian volnának!...
Amerre Marci járt, volt harang szólása,
Sok szerelmes szívnek hangos dobogása.

Minek volt sarkantyú kordován csizmáján?
A szép szó is fogott sörény paripáján.
Nem is a ló, hanem hát a tánc számára
Verette a csengőt csizmája sarkára.

Rátermett a táncra Marci, nem tanulta;
De őtőle sokan tanulhattak volna.
Betért a csárdába, ha szólt a muzsika,
S szilaj kedvvel amugy magyarán megrakta.

Nem kivánkozott ő Bakony erdeibe,
Oda csak a félénk tolvaj rejtezik be,
Bokrok közé búvik, onnan ugrik elő,
Ugy ragadja torkon, aki arra menő.

Marcinak Hortobágy volt rendes tanyája,
Hortobágy, a puszták óriás királya,
Kiállt az országút síkjára, s az utas
Száz lépésről látta, hogy majd lesz ne-mulass.

Ha gazdag útas jött, Marci így kiáltott:
"Ide az erszénnyel, ha nem kell halálod!"
Ha szegény utas jött, ezt mondta szívesen:
"Nesze az erszényem, s áldjon meg az isten!"

Fegyverneki puszta, fegyverneki puszta
Szegény jó Zöld Marci halálát okozta,
Négyágú épület volt halálos ágya
S temetési dala varjak károgása.','Négyágú épűlet, amely be sincs fedve,
Mely akasztófának vagyon keresztelve,
Akasztófa mellett hollók károgása,
Nem volt Zöld Marcinak két országban mása.','Pest, 1847. április',1847,'1847',array['Szerelem','Természet','Elmúlás']::text[],'{}'::text[],false,589,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184703-43','petofi','Ha én kedvesemről gondolkodom...','Ha én kedvesemről gondolkodom,
Egy-egy virág minden gondolatom,
Gondolkodom rólad, szép kedvesem,
Ezt teszem napestig, egyebet sem.

Foly a lemenő nap arany vére
Violaszín hegyek tetejére.
Még messzebb van tőlem, kit szeretek,
Mint azok a violaszín hegyek.

Mért jár a nap keletről nyugatra?
Ha nap volnék, nem járnék én arra,
Nyugatról járnék én kelet felé,
Mert a legszebb lyány ott keleten él.

Feljött az égre az esti csillag,
Ma megint oly különösen csillog,
Felöltözött ünnepi ruhába,
Tán azért, mert kedvesemet látta.

Mikor látlak, mikor látlak, rózsám?
Mikor leszesz megint közel hozzám?
Vajjon mikor nézek már szemedbe,
Szép szemedbe, hetedik egembe?','Ha én kedvesemről gondolkodom,
Egy-egy virág minden gondolatom,
Gondolkodom rólad, szép kedvesem,
Ezt teszem napestig, egyebet sem.','Pest, 1847. május',1847,'1847',array['Szerelem','Természet']::text[],'{}'::text[],false,590,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184703-44','petofi','Tűz<a/></h3> </td> <td><a href="vrsk1847.htm"><img src="back.gif" border="0" >','Nem akarok elrohadni,
Mint a fűzfa a mocsárban;
El akarok égni, mint a
Tölgy a fellegek lángjában.

Tűz kell nékem; víz maradjon
A békának és a halnak
És a rosz poétáknak, kik
Béka módra kuruttyolnak.

Te vagy az én elemem, tűz!...
Sokat fáztam életemben,
Szegény testem sokat fázott,
De meleg volt mindig lelkem. -

Jer, szeretlek szép leányka,
Jer, szeretlek szenvedéllyel;
De tüzes légy! máskülönben
Elmehetsz isten hirével.

Hej, kocsmáros, bort! ihatnám.
Tiszta bort! mert ha vizes lesz:
Megköszönhetd, ha kancsód a
Falhoz vágom, nem fejedhez. -

Csak igy élet ez az élet,
Tüzes lyánnyal, tüzes borral...
És - amit majd elfeledtem -
Nem maradhat még el a dal.

Mondjatok dalt, de tüzes dalt,
Mert szakadjon ki a nyelve,
Ki ugy dalol, hogy dalától
Nincsen a szív feltüzelve.

Nem akarok elrohadni,
Mint a fűzfa a mocsárban;
El akarok égni, mint a
Tölgy a fellegek lángjában!','Nem akarok elrohadni,
Mint a fűzfa a mocsárban;
El akarok égni, mint a
Tölgy a fellegek lángjában.','Pest, 1847. május',1847,'1847',array['Szerelem']::text[],'{}'::text[],false,591,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184703-45','petofi','Legszebb versem','Sok verset írtam én már össze,
S nem mindenik haszontalan;
De amely hírem megszerezze,
A legszebb vers még hátra van.

Legszebb lesz az, ha majdan Béccsel
Hazám bosszúja szembeszáll,
S én villogó kardom hegyével
Száz szívbe ezt írom: halál!','Sok verset írtam én már össze,
S nem mindenik haszontalan;
De amely hírem megszerezze,
A legszebb vers még hátra van.','Érmihályfalva, 1847. május',1847,'1847',array['Haza']::text[],'{}'::text[],false,592,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184703-46','petofi','Erdőd, május 17. 1847','Nevezetes a tennapi napom,
Furcsa dolgokat kellett hallanom.
Szerencséje, hogy az bánt ugy velem,
Akinek a leányát szeretem.

Mondott volna csak felényit is más,
Majd megtudná, mi a bosszúállás,
Majd kiálltunk volna a mezőre,
Zöld mezőre folyna piros vére.

De még hagyján, hogy énnekem esnek,
Hej van, ami jobban fáj szivemnek,
Az még sokkal jobban fáj énnekem,
Hogy téged is bántanak, kedvesem.

Sokat szenvedsz, édes lelkem, szenvedsz,
És csak azért, mert engemet szeretsz.
Tűrj, galambom, tűrj még egy keveset,
Maj'' megszakasztom szenvedésedet.

Légy csak egyszer az én feleségem,
Nem lesz párod a földkerekségen,
Nem lesz párod boldogság dolgába'',
Még csak nem is vágysz a másvilágra!','Nevezetes a tennapi napom,
Furcsa dolgokat kellett hallanom.
Szerencséje, hogy az bánt ugy velem,
Akinek a leányát szeretem.','Erdőd, 1847. május 18.',1847,'1847',array['Szerelem','Természet']::text[],array['tavasz']::text[],false,593,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184703-47','petofi','Hol a leány, ki lelkem röpülését...','Hol a leány, ki lelkem röpülését
Követni bírná te kivűled?
És hol a férfi, aki én kivűlem
Szived mélyére lemerűlhet?
Egymáshoz illünk; a teremtés napján
Egymásnak voltunk már rendelve mi...
Isten kötötte össze lelkeinket,
Ember nem képes elválasztani.

Mint törnek ők s hadd törjenek reánk az
Önérdek rozsdás fegyverével;
Elhárítjuk mi könnyen a csapást a
Szerelem varázsvesszejével.
A szerelem a legnagyobb hős, ennek
Valának legtöbb diadalmai...
Isten kötötte össze lelkeinket,
Ember nem képes elválasztani.

Szeretjük egymást égő szerelemmel,
Te tiszta, szent vagy, oh leányka,
S az én szivemnek hogyha volt is foltja,
Leégeté szerelmem lángja.
Mért oltanátok el keblünk tüzét? mely
Oltár fölött is méltó állani...
Isten kötötte össze lelkeinket,
Ember nem képes elválasztani.

Tiéd vagyok, szép angyalom, tiéd, és
Te az enyém vagy mindörökre!
Együtt lépünk az élet határáig
Rózsákra, tövisekre,
S ha átörültük, átbusúltuk éltünk,
Együtt fogunk a sírban porlani...
Isten kötötte össze lelkeinket,
Ember nem képes elválasztani.','Hol a leány, ki lelkem röpülését
Követni bírná te kivűled?
És hol a férfi, aki én kivűlem
Szived mélyére lemerűlhet?','Erdőd, 1847. május 18.',1847,'1847',array['Szerelem']::text[],'{}'::text[],false,594,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184703-48','petofi','Röpül az úti por...','Röpül az úti por, dobog a föld, nyargal
A bőszült paripa egy szegény lovaggal.
Kihányta nyergéből a ló a lovagot,
De haj a kengyelbe akadt egyik lába...
Talppal az ég felé, iszonyú állapot,
Fejével pedig ott lenn a föld porába'',
A fakó port söpri fekete fürtével,
S köveket pirosít homloka vérével.

Csak úgy vagyok, mint e szerencsétlen lovag,
Kit szilaj paripa hurcol maga után,
Hurcol engemet az eszeveszett harag,
Még agyvelőmet is széjjelloccsantja tán.
Bárcsak szétszakadna boldogtalan fejem,
Ugyis kopár föld az, nem süt a nap rája,
Csak sötét gondolat, ami benne terem,
Sötét gondolatok tövise, dudvája.

Szeretem rózsámat, mint az isten maga,
Ki őt teremtette leányok gyöngyének,
Az ő nekem, ami a csillag az éjnek,
Szeretőm a hűség tündöklő csillaga.
Köd ereszkedett rád, csillagom világa,
Köd ereszkedett rád, be halovány lettél!
Kértelek apádtól, kértelek hiába,
Nem kaptam egyebet hideg feleletnél.

Elűztek tőled, szép paradicsomkertem,
De nem angyal, aki ott őrt áll előtted;
Ne félj, nem örökre váltunk el! te érted
Még többet is merek, ha már annyit mertem.
Elvittelek volna, mint nap a harmatot,
Mint az esti szellő a rózsalevelet,
De most, mint a nyílvesszővel, a zaklatott
Megsebzett oroszlán, ugy megyek el veled!','Röpül az úti por, dobog a föld, nyargal
A bőszült paripa egy szegény lovaggal.
Kihányta nyergéből a ló a lovagot,
De haj a kengyelbe akadt egyik lába...','Erdőd, 1847. május 18-20.',1847,'1847',array['Természet','Szerelem']::text[],'{}'::text[],false,595,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184703-49','petofi','Bányában','Ezer ölre vagyok idelenn a
Föld ölében,
Hol az ősi örök éj tanyázik
Vadsötéten.
A kis lámpa reszkető sugára
Félve néz a zordon éj arcára,
Mint a sasra a galamb.

Ezer ölre a virágoktól s a
Napvilágtól,
Ezer ölre! tán már a pokol sincs
Innen távol;
Vagy már benn is vagyok a pokolban?
Benne, mert a sátán háza ott van,
Ahol az arany terem.

Bányaszellem, sátán, kincs királya,
Mit adsz értem?
Mennyit adsz, ha szívemet tenéked
Eligérem?
Alkudjunk meg, jöszte, bányaszellem,
Most ez egyszer volt lejőni kedvem,
Vagy látsz többé vagy soha. -

Vártam, vártam, és hiába, mert a
Kincs királya
Bennmaradt a sziklák tömegében,
Ki nem álla.
S mért nem állt ki? miért nem jelent meg?
Csak azért, mert tudta, hogy enyelgek,
Hogy szívem nem eladó.

Nem, szivem nem eladó, e szívnek
Nincsen ára,
Nem megy az be a hatalmasoknak
Kincstárába...
Széjjelosztom én a szegénységnek,
Kik kunyhóban és útfélen élnek,
Köztök ingyen osztom szét.','Ezer ölre vagyok idelenn a
Föld ölében,
Hol az ősi örök éj tanyázik
Vadsötéten.','Nagybánya, 1847. május 25.',1847,'1847',array['Szerelem']::text[],'{}'::text[],false,596,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184703-50','petofi','Bírom végre Juliskámat...','Bírom végre Juliskámat,
Mindörökre bírom őt,
Az enyémnek vallhatom már
Isten és világ előtt.

Megjött már jókedvem, és még
Nem hagyott el bánatom;
Sírjak-e vagy mosolyogjak
Örömömben? nem tudom.

Én vagyok hát az az ember,
Aki annyit szenvedék?
Akinek szivén ahány nap,
Annyi átok feküvék.

Én vagyok hát az az ember,
Ki most a legboldogabb?
Ki, mig a világ világ lesz,
Boldogságban párt nem kap.

Bárcsak már lehullanának
A virágok s levelek!
Most az ősz lesz tavaszom, mert
Akkor vőlegény leszek...

De nem nézek a jövőbe,
Belenéznem nem lehet,
Mert az olyan fényes nap, hogy
Megvakítná szememet.

Rád tekintek, holdvilágom,
Rád tekintek, mult idő,
Szinte oly szép, de szelídebb
Sugaraddal jőj elő.

Drága nap, mit nála tölték,
Kedvesemnél, drága nap!
Üdvösségben egy öröklét
S futtában egy pillanat.

Odavontam őt magamhoz,
Halkan vontam őt felém;
Mint égett, midőn legelső
Csókomat rálehelém!

Mint égett arcátul ajkam!
Most is érzem melegét,
Mintha bennem egy elolvadt
Nap tűz-árja folyna szét.

Sőt a sírtól sem félek már,
Hogy meghűt majd engemet,
Mert e láng még ott is fogja
Melegítni szívemet.','Bírom végre Juliskámat,
Mindörökre bírom őt,
Az enyémnek vallhatom már
Isten és világ előtt.','Szatmár, 1847, május 28.',1847,'1847',array['Természet','Szerelem']::text[],'{}'::text[],false,597,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184703-51','petofi','A majtényi síkon','Mióta elváltam édes szeretőmtül,
Velem volt emléke, szűntelenűl velem;
Valamint a három napkeleti királyt
A csillag, ugy kísért engem a szerelem.

Hagyj el most, szerelem, hagyj el, szép csillagom,
Nem neked való hely ez, ahova értem;
Vagy ha el nem maradsz, fátyolt vetek reád,
Hogy szembekötve jőj át a csatatéren.

Csatatér ez a sík, szent csatának tére,
Mert a szabadságért harcolának rajta,
Oh árva szabadság, haldokló kezedből
Undok árulás a fegyvert kicsavarta.

És a hősök, kik itt a hazáért vívtak,
Hazátlan bujdosók, földönfutók lettek,
És a latrok, kik a hazát elárulták,
Urak lőnek... oh, szív, szívem, ne repedj meg! -

Tavaszi délután, verőfényes idő,
Az égen kis fejér felhők uszdogálnak;
Hattyusereg tán e felhőcsoport? vagy a
Hősök szellemei, kik itt elhalának?

Csend van körülöttem, tünődöm, tünődöm...
De mit állok még itt? mért odább nem megyek?
Végzém, amit kelle: elmondtam legszörnyűbb
Átkomat, s elsírtam legszentebb könnyemet.','Mióta elváltam édes szeretőmtül,
Velem volt emléke, szűntelenűl velem;
Valamint a három napkeleti királyt
A csillag, ugy kísért engem a szerelem.','Majtény, 1847. május 30.',1847,'1847',array['Haza','Természet','Szerelem']::text[],'{}'::text[],false,598,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184703-52','petofi','Te az enyim, én a tied...','Te az enyim, én a tied,
Nekünk áll a világ!
Magas a nap fejünk fölött,
Messze földet belát,
De ameddig szeme elhat,
Nem lát nálunk boldogabbat.

Kicsiny leány az én rózsám,
Elfér az ölembe''.
Kicsiny leány az én rózsám,
De nagy ám a lelke,
Rózsám lelke egész ország,
Mégpedig a Tündérország.

Ha Juliskám eszembe jut,
Sötétben is látok,
Fényes szeme, fényes lelke
Hint reám világot;
Ha előttem e két fáklya,
Belátok a mennyországba. -

Tudod-e még, édesanyám,
Mikor gyerek voltam?
Kinn az utcán házunk előtt
Játszottam a porban,
Már ott az járt a fejembe:
Ha belőlem király lenne!

Kinevettél akkor, anyám,
Jóizűt nevettél,
Hogy fiad fejében ilyen
Balga gondolat kél.
De az isten meghallgatott,
Megsegített, király vagyok.

Király vagyok én, mióta
Bírom Juliskámat.
Nem fejemen, de szívemen
Hordom koronámat.
Eszemadta Juliskája
Szívem arany koronája!','Te az enyim, én a tied,
Nekünk áll a világ!
Magas a nap fejünk fölött,
Messze földet belát,','Nagyvárad, 1847. június 1.',1847,'1847',array['Szerelem']::text[],'{}'::text[],false,599,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184703-53','petofi','Arany lacinak','Laci te,
Hallod-e?
Jer ide,
Jer, ha mondom,
Rontom-bontom,
Ülj meg itten az ölemben,
De ne moccanj, mert különben
Meg talállak csípni,
Igy ni!
Ugye fáj?
Hát ne kiabálj.
Szájadat betedd,
S nyisd ki füledet,
Nyisd ki ezt a kis kaput;
Majd meglátod, hogy mi fut
Rajta át fejedbe...
Egy kis tarka lepke.
Tarka lepke, kis mese,
Szállj be Laci fejibe.

Volt egy ember, nagybajúszos.
Mit csinált? Elment a kúthoz.
De nem volt viz a vederbe'',
Kapta magát, telemerte.
És vajon minek
Merítette meg
Azt a vedret?
Tán a kertet
Kéne meglocsolnia?
Vagy ihatnék?... nem biz a.
Telt vederrel a kezében
A mezőre ballag szépen,
Ott megállt és körülnézett;
Ejnye vajon mit szemlélhet?
Tán a fényes délibábot?
Hisz olyat már sokat látott...
Vagy a szomszéd falu tornyát?
Hisz azon meg nem sokat lát...
Vagy tán azt az embert,
Ki amott a kendert
Áztatóba hordja?
Arra sincsen gondja.
Mire van hát?
Ebugattát!
Már csak megmondom, mi végett
Nézi át a mezőséget,
A vizet mért hozta ki?
Ürgét akar önteni.
Ninini:
Ott az ürge.
Hű, mi fürge,
Mint szalad!
Pillanat,
S odabenn van,
Benn a lyukban.
A mi emberünk se'' rest,
Odanyargal egyenest
A lyuk mellé,
S beleönté
A veder vizet;
Torkig tele lett.
A szegény kis ürge
Egy darabig türte,
Hanem aztán csak kimászott,
Még az inge is átázott.
A lyuk száján nyakon csipték,
Nyakon csipték, hazavitték,
S mostan...
Itt van...
Karjaimban,
Mert e fürge
Pajkos ürge
Te vagy, Laci, te bizony!','Laci te,
Hallod-e?
Jer ide,
Jer, ha mondom,','Szalonta, 1847. június 1-10.',1847,'1847',array['Természet']::text[],'{}'::text[],false,600,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184703-54','petofi','Mily szép a világ!','Én hittem-e egykor
Átoknak az éltet?
Én bolygtam a földön,
Mint éji kisértet?
Elégeti arcom
A szégyeni láng! -
Mily édes az élet,
Mily szép a világ!

Vad ifjukoromnak
Szélvésze kitombolt,
Kék, tiszta szemével
Mosolyg le a mennybolt,
Mint gyermekeikre
Az édesanyák -
Mily édes az élet,
Mily szép a világ!

Minden napom egy bút
Gyomlál ki szivembül,
Kert újolag e szív,
Mely széltire zöldül,
És benne virít a
Sok tarka virág...
Mily édes az élet,
Mily szép a világ!

A bizodalom, kit
Oly rútul elűzék,
Két karral ujonnan
Lelkemre füződék,
Mint távoli utról
Jött régi barát...
Mily édes az élet,
Mily szép a világ!

Jertek közelembe,
Jó régi barátok,
Nem néz a gyanúnak.
Kancsal szeme rátok,
Elvertem az ördög
Ez atyjafiát...
Mily édes az élet,
Mily szép a világ!

Hát még ha eszembe
Jut ifju virágom,
A barna leány, e
Szép hajnali álom,
Kit én ugy imádok,
S ki engem imád -
Mily édes az élet,
Mily szép a világ!','Én hittem-e egykor
Átoknak az éltet?
Én bolygtam a földön,
Mint éji kisértet?','Szalonta, 1847. június 1-10.',1847,'1847',array['Természet','Szerelem']::text[],'{}'::text[],false,601,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184703-55','petofi','Sári néni','A küszöbön guggol Sári néni,
Guggol s nem áll; nem akar már nőni,
Van nyergelve pápaszemmel orra,
Varrogat... tán szemfedőjét varrja.
Sári néni, hej, mikor kendet még
Sárikámnak, húgomnak nevezték!

Ami eddig ott lenn volt ruháján,
Odafönn van most a ránc orcáján;
Csak úgy líg-lóg derekán ruhája,
Mintha rá villával volna hányva.
Sári néni, hej, mikor kendet még
Sárikámnak, húgomnak nevezték!

Haja tél, - ha látom, szinte fázom -
Fejér, mint a fejérített vászon,
S borzasan űl feje tetejében,
Mint a gólyafészek a kéményen.
Sári néni, hej, mikor kendet még
Sárikámnak, húgomnak nevezték!

Befelé vette az utját szeme,
Ráúnt régi születőhelyire,
Ott benn pislog szomorún, nem vígan,
Mint lámpa a beroskadt sírban.
Sári néni, hej, mikor kendet még
Sárikámnak, húgomnak nevezték!

Keble róna, puszta s csendes róna,
Mintha már alatta szív se'' vóna;
Ott van még a szív, de mozdulatlan,
Csak nagy néha, csak elvétve dobban.
Sári néni, hej, mikor kendet még
Sárikámnak, húgomnak nevezték!

Vad, tékozló fiú az ifjúság,
Két marokkal szórja gazdaságát,
De jön apja, a zsugori vénség,
S visszaszedi elpazarlott kincsét.
Sári néni, hej, mikor kendet még
Sárikámnak, húgomnak nevezték!','A küszöbön guggol Sári néni,
Guggol s nem áll; nem akar már nőni,
Van nyergelve pápaszemmel orra,
Varrogat... tán szemfedőjét varrja.','Szalonta, 1847. június 1-10',1847,'1847',array['Természet']::text[],'{}'::text[],false,602,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184703-56','petofi','Csonka torony','Vén torony áll a rónaság felett...
Letűnt századba visz a képzelet.

Kevélyen néztek hajdan e falak,
Mert ormukon szent jelt tartottanak.

A szabadság zászlója volt e szent jel;
Csak játszott a viaskodó szelekkel.

Piros szárnyát hivólag lengeté,
S kiben vér volt, elszántan jött elé.

Gyűlt a toronyba a sok ifju bajnok,
Harc-öltözetnek csillogása rajtok,

De fegyveröknél sokkal fényesebben
Sugárzott a hősbátorság szemökben.

"Markunkban a kard, s benne lesz, amig
Szemfényünk vagy rabláncunk megtörik!"

Ezt harsogák s mely ekkor kinn zugott,
A mennydörgés e zaj viszhangja volt. -

A sírba dőlt egy századév ezóta,
Nincs a toronynak többé lobogója,

A szabadsági zászló lebukott,
Ti is alusztok, dicső bajnokok,

Kik szabadon inkább elestetek,
Semhogy rabszolgaságban éljetek.

A torony áll még egyes-egyedűl,
Ez is maholnap már halomra dűl.

Idétlen rom, mogorva, puszta váz,
Falai között senki sem tanyáz.

Csak a holt század fekszik odabent,
Szemfödele a hosszu, méla csend.','Vén torony áll a rónaság felett...
Letűnt századba visz a képzelet.
Kevélyen néztek hajdan e falak,
Mert ormukon szent jelt tartottanak.','Szalonta, 1847. június 1-10.',1847,'1847',array['Haza']::text[],'{}'::text[],false,603,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184703-57','petofi','Lennék én folyóviz...','Lennék én folyóvíz,
Hegyi folyam árja,
Ki darabos utját
Sziklák között járja...
De csak úgy, ha szeretőm
Kis halacska volna,
Habjaimban úszna föl s le
Vígan lubickolva.

Lennék vad erdő a
Folyó két oldalán,
Fergetegekkel a
Harcot kiállanám...
De csak úgy, ha szeretőm
Kis madárka volna,
Bennem ütne fészket és ott
Ágamon dalolna.

Lennék váromladék
A hegy legtetején,
Bús pusztulásomat
Venném csak könnyedén...
De csak úgy, ha szeretőm
Ott a repkény volna,
Elnyuló zöld karjaival
Homlokomra folyna.

Lennék kicsiny kunyhó
A rejtett völgybe'' lenn,
Eső-vágta sebbel
Szalmafödelemen...
De csak úgy, ha szeretőm
Bennem a tűz volna,
Tűzhelyemen lassacskán, de
Nyájasan lobogna.

Lennék felhődarab,
Összetépett zászló,
A vadontáj fölött
Fáradtan megálló...
De csak úgy, ha szeretőm
Az alkonyat volna,
Búshalovány arcom körül
Pirosan ragyogna.','Lennék én folyóvíz,
Hegyi folyam árja,
Ki darabos utját
Sziklák között járja...','Szalonta, 1847. június 1-10.',1847,'1847',array['Természet','Szerelem']::text[],'{}'::text[],false,604,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184703-58','petofi','A gólya','Sokféle a madár, s egyik ezt, másik azt
Leginkább kedveli,
Ezt ékes szólása, amazt pedig tarka
Tolla kedvelteti.
Kit én választottam, a dal-mesterséghez
Nem ért az a madár.
S egyszerű, mint magam... félig feketében,
Félig fejérben jár.

Nekem valamennyi között legkedvesebb
Madaram a gólya,
Édes szülőföldem, a drága szép alföld
Hűséges lakója.
Tán ezért szeretem annyira, mert vele
Együtt növekedtem;
Még mikor bölcsőmben sírtam, ő már akkor
Kerepölt fölöttem.

Vele töltöttem a gyermekesztendőket.
Komoly fiú valék.
Míg társim a hazatérő tehéncsordát
Estenként kergeték:
Én udvarunkon a nádkúp oldalánál
Húztam meg magamat,
S némán szemléltem a szárnyokat-próbáló
Kis gólyafiakat.

És elgondolkodtam. Jól tudom, az gyakran
Fordult meg fejembe'':
Miért hogy az ember nincs úgy, mint a madár,
Szárnyakkal teremtve?
Csak a messzeséget járhatni meg lábbal
S nem a magasságot;
Mit ér nekem, mit a messzeség? mikor én
A magasba vágyok.

Fölfelé vágytam én. Ah, ugy irigyeltem
Sorsáért a napot,
A föld fejére ő tesz világosságból
Szőtt arany kalapot.
De fájt, hogy estenként megszúrják... mert hiszen
Foly keblébül a vér;
Gondolám: hát így van? hát aki világít,
Ilyen jutalmat nyér? - -

Kívánt időszak az ősz a gyermekeknek,
Mint anya jön elé,
Aki fiainak számára kosarát
Gyümölccsel terhelé.
Én ellenségeműl néztem az őszt, s szólék,
Ha gyümölcsöt hozott:
Tartsd meg ajándékod, ha kedves madaram,
A gólyát elcsalod.

Szomorodott szívvel láttam gyülekezni,
Midőn távozának;
Miként most eltűnő ifjuságom után,
Ugy néztem utánok,
S milyen bús látvány volt a házak tetején
A sok üres fészek,
Szellő lehelt reám, sejtés halk szellője,
Hogy jövőmbe nézek.

Mikor tél multával fehér hó-subáját
A föld levetette,
S virággal zsinórzott sötétzöld dolmányát
Ölté föl helyette:
Akkor az én lelkem is felöltözék új,
Ünnepi ruhába,
S gólya-várni néha elballagtam egész
A szomszéd határba. -

Később, hogy a szikra lángra lobbant, ahogy
Ifju lett a gyermek:
Talpam alatt égett a föld, nekiesem,
És paripán termek,
S megeresztett kantárszárral vágtaték ki
A puszták terére...
Még a szél is ugyan nekigyürközött, hogy
Lovamat elérje.

Szeretem a pusztát! ott érzem magamat
Igazán szabadnak,
Szemeim ott járnak, ahol nekik tetszik,
Nem korlátoztatnak,
Nem állnak körűlem mogorva sziklák, mint
Fenyegető rémek,
A csörgő patakot hányva-vetve, mintha
Láncot csörgetnének.

És ne mondja senki, hogy a puszta nem szép!
Vannak szépségei,
De azokat, mint a szemérmes lyány arcát,
Sürű fátyol fedi;
Jó ismerősei, barátai előtt
Leteszi fátyolát,
S rajta vesz merően a megbűvölt szem, mert
Tündérkisasszonyt lát.

Szeretem a pusztát! be-bekalandoztam
Tüzes paripámon,
S midőn már ott jártam, ahol fizetésért
Sincs emberi lábnyom:
Lovamról leszálltam, gyepre heveredtem.
Egy futó pillanat
A tóra mellettem, s benne kit látok meg?
Gólya barátomat.

Oda is elkísért. Együtt ábrándoztunk
A puszta legmélyén,
Ő a víz fenekét, én a délibábot
Hosszasan szemlélvén.
Igy töltöttem vele gyermekségemet és
Ifjuságom javát,
Azért kedvelem, bár se'' tolla nem ragyog,
Se'' szép hangot nem ád.

Mostan is kedvelem és úgy tekintem én
A gólyamadarat,
Mint egyetlen valót, mely egy átálmodott
Szebb korból fönnmaradt.
Megérkezésedet még mostan is minden
Esztendőben várom,
S kivánok szerencsés útat, ha távozol,
Legrégibb barátom!','Sokféle a madár, s egyik ezt, másik azt
Leginkább kedveli,
Ezt ékes szólása, amazt pedig tarka
Tolla kedvelteti.','Szalonta, 1847. június 1-10.',1847,'1847',array['Természet','Szerelem','Gyermekkor']::text[],'{}'::text[],false,605,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184703-59','petofi','Puszta föld ez, ahol most járok...','Puszta föld ez, ahol most járok,
Istenért sem látni virágot,
Rajta bokor sincsen, ahol a
Fülemile-madár szólana,
Az este is felhős, fekete,
Nincs a csillagoknak híre se''...
Hogy jutottál mégis eszembe,
Barna kislyány, szívem szerelme?
Eszembe jutottál, édesem,
És most már úgy tetszik énnekem,
Mintha itten a szomszédomba''
Fülemile-madár szólana,
S mintha virágok közt ballagnék,
S csupamerő csillag voln'' az ég!','Puszta föld ez, ahol most járok,
Istenért sem látni virágot,
Rajta bokor sincsen, ahol a
Fülemile-madár szólana,','Körösladány, 1847. június 10.',1847,'1847',array['Természet']::text[],'{}'::text[],false,606,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184703-60','petofi','Utazás az Alföldön','Pompás kis útazás, valóban!
Alig van egy arasznyira
Fölöttem a felhő, oly terhes,
Szakad nyakamba zápora.
Bundám dohányzacskómra adtam,
Hogy az maradjon szárazon.
Csuron víz vagyok. Még megérem,
Hogy végre hallá változom.

Minő az út!... de vajjon út ez?
Vagy fekete kovász talán?
Mely ha kisűl, leszen belőle
Kenyér az ördög asztalán.
Ne dögönyözze kend csikóit,
Ne dögönyözze kend, kocsis,
Fölérünk Pestre, ott leszünk tán
Már az itéletnapon is. -

Hej, alföld, alföld, nem reméltem,
Hogy így fizess szerelmemért!
Vagy tán e zápor és ez a sár
Épen szerelmemért a bér?
Csakugyan az lesz... a záporban
Bucsúkönyűid ömlenek,
S karod a sár, amely helyettem
A kereket öleli meg.

Szép tőled, kedves alföldem, szép,
Hogy engem ennyire szeretsz,
Hogy távozásom így megindít,
Hogy ilyen bánatot szerez;
Örűlök rajta, hogy irántam
Ily érzékeny szived vagyon,
De, szó ami szó, jobb szeretném,
Ha nem szeretnél ily nagyon.','Pompás kis útazás, valóban!
Alig van egy arasznyira
Fölöttem a felhő, oly terhes,
Szakad nyakamba zápora.','Mezőtúr, 1847. június 11.',1847,'1847',array['Természet','Szerelem']::text[],'{}'::text[],false,607,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184703-61','petofi','Kérdezd: szeretlek-e','Kérdezd: szeretlek-e? s megmondom én, hogy
Szeretlek, mert ezt mondhatom;
De oh ne kérdezd: mennyire szeretlek?
Mert én azt magam sem tudom!
Azt tudni csak, hogy mély a tengerszem,
De milyen mély? nem tudja senki sem.

Mondhatnék esküt, hosszu és nagy esküt,
Az ég felé tartván kezem,
Hogy szívem minden dobbanása érted
És egyedűl érted leszen,
Hogy öröklámpa benne a hüség,
Mely még ott lenn a föld alatt is ég.

S mondhatnék átkot, hosszu és nagy átkot,
Mely, mint a villám, érjen el,
S égesse, tépje lelkemet legmélyebb
Pokolba mártott körmivel,
Ha elfeledlek téged, kedvesem,
Sőt ha rólad csak megfeledkezem.

Nem mondok esküt és átkot. Jaj annak,
Jaj, akit ez tart vissza csak.
Én eskü s átok nélkül is örökre
Lelkem lelkében tartalak,
Ott fogsz te állni magas-fényesen,
Mint a tejút a legmagasb egen.

S örök hűségem, oh ez a hüség is
Még a te érdemed csupán;
Hogy szerethetne mást többé, akit te
Megszeretél, dicső leány?
Ki egyszer már a mennybe szállt vala,
Nem látja azt a föld többé soha!','Kérdezd: szeretlek-e? s megmondom én, hogy
Szeretlek, mert ezt mondhatom;
De oh ne kérdezd: mennyire szeretlek?
Mert én azt magam sem tudom!','Pest, 1847. június 14-30.',1847,'1847',array['Szerelem','Természet']::text[],'{}'::text[],false,608,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184703-62','petofi','Bucsúpohár','Hadd támadjon föl mégegyszer a mult,
Hol szivünk és poharunk kicsordult,
Kedv s bor bennök meg nem férve már.
Koszorúnk egy levelét veszíti,
A szél épen engemet röpít ki...
Cimborák, ez a bucsúpohár!

Amiért a sorshoz úgy esengtem,
Bár sokára, de megadta: engem
Házasélet boldogsága vár.
Hányt-vetett a vad hullámos élet,
S végre, végre meglelém a révet...
Cimborák, ez a bucsúpohár!

Nem veszem már a bort gyógyszeremnek,
Ha a kígyók lelkemen teremnek,
Melyeket a bú szivembe zár;
Barna kislyány ajka mézet árul,
Mézzel élek édes ajakárul...
Cimborák, ez a bucsúpohár!

Még ez este vagyok a tiétek,
Töltsétek meg poharam, töltsétek,
Koccantgassunk, míg e nap lejár;
Holnap messze járok, más vidéken,
Üresen fog itten állni székem...
Cimborák, ez a bucsúpohár!

S mert szeretlek bennetek, kivánom:
Nyiljon ily út nektek is utánam.
Feleség föld s ég közt a határ.
Adja isten azt az áldást rátok,
Hogy egyenként ezt kiálthassátok:
Cimborák, ez a bucsúpohár!','Hadd támadjon föl mégegyszer a mult,
Hol szivünk és poharunk kicsordult,
Kedv s bor bennök meg nem férve már.
Koszorúnk egy levelét veszíti,','Pest, 1847. június 14-30.',1847,'1847',array['Természet']::text[],'{}'::text[],false,609,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184703-63','petofi','Híres szépség','Róla és csak róla szól
Az új világ krónikája;
Tótágast áll az esze,
Ki csak egyszer néz is rája.

Odahagyja aranyát
A fukar s boltját a kalmár
S a poéta rímjeit,
Hogy kövessék őt, ahol jár.

Ha látná őt a király,
Elfeledné trónját érte;
Árnya lenne a nap, és
Nem kivánkoznék az égre.

A halálos beteget
Meggyógyítja szemsugára,
És az éhes jóllakik
Egy futó pillantatára. -

Így írják le őt nekem,
Így beszéle róla minden.
Mit csináljak? gondolám,
Már, mondok, csak megtekintem.

S megtekintém. Eh, bolond
A világ s az lesz örökre;
Mi a szép? ugy tudja csak,
Mint apám bármelyik ökre.

Szó sincs, szó sincs róla, hogy
Szép e lyány. Uram kegyelmezz,
Hogy lehetne szép? hiszen
Nem hasonlít kedvesemhez.','Róla és csak róla szól
Az új világ krónikája;
Tótágast áll az esze,
Ki csak egyszer néz is rája.','Pest, 1847. június 14-30.',1847,'1847',array['Szerelem']::text[],'{}'::text[],false,610,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184704-64','petofi','Mi lárma ez megént?','Mi lárma ez megént fülem körűl?
Ki háborítja nyugtomat megént?
Hallgasson el, ki jó sorsán örűl!
Majd megtanítok egy pár kóc legényt.

Ismét fölkelt a kritikus-csapat,
Ismét veszettül zúgnak ellenem.
Hagyjátok el kiabálástokat,
Mig engem el nem hágy a türelem.

Vagy feledétek már a múlt időt?
Nem ég, nem viszket többé hátatok?...
Nem árt meggondolni, hogy ezelőtt
Mi történt? s húzzátok meg magatok.

Tudjátok: durván bánom veletek. -
Hiába, ez már az én modorom:
Ha férfi bánt, majd karddal felelek,
De a kutyákat csak korbácsolom.','Mi lárma ez megént fülem körűl?
Ki háborítja nyugtomat megént?
Hallgasson el, ki jó sorsán örűl!
Majd megtanítok egy pár kóc legényt.','Pest, 1847. június 14-30.',1847,'1847',array['Természet']::text[],'{}'::text[],false,611,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184704-65','petofi','Hozzám jösz-e?','Csillagnak születél
Magasban, fényesen,
Belőled itt alant
Kis mécsvilág leszen,
Mely csak szűk házamat
Világosítja meg;
Leány, hozzám jösz-e?
- "Ifjú, hozzád megyek!"

Hallod, miket beszél
Felőlem a világ?
Hallod, mikép reám
Kigyót-békát kiált?
Ha igaz a hir: én
Nagyon rosz lehetek;
Leány, hozzám jösz-e?
- "Ifjú, hozzád megyek!"

Apád egyetlenegy
Örömsugára vagy,
Eljöttöd kebliben
Rideg, vad éjet hagy,
S haragja, búja mint
Két rém, velünk lebeg;
Leány, hozzám jösz-e?
- "Ifjú, hozzád megyek!"','Csillagnak születél
Magasban, fényesen,
Belőled itt alant
Kis mécsvilág leszen,','Pest, 1847. június 14-30.',1847,'1847',array['Szerelem']::text[],'{}'::text[],false,612,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184704-66','petofi','Fölszedtem sátorfám...','Fölszedtem sátorfám és világnak mentem. -
Homályos sejtések munkálódtak bennem,
Hogy, ha elindulok, találok valamit,
Találok, hanem a sejtés nem mondta: mit?
Még azt sem mondta, hogy mely táj felé menjek?
Csak azt mondta: menjek, menjek, ne pihenjek.
Én e benső szónak engedelmeskedtem,
S az apai ház úgy elmaradt mögöttem,
Mint az álom a fölébredt ember mögött,
Apámhoz, anyámhoz még csak hírem se'' jött.
Apám s anyám pedig búbánatba esék,
De a jó szomszédok őket fölkeresék,
S vigasztalásukra voltak ilyen formán:
"Sose búsuljanak Sándor fiok sorsán!
Ilyen istentől elrugaszkodott gyerek
Az aggódást ingyen sem érdemli meg.
Viszi, mig viheti, végre pedétiglen
Fölakasztják, amit adjon is az isten,
Mert nem vagyok mai legény a világban,
De kicsiny mását sem láttam gonoszságban."
Öreg szülőimet ekkép vigasztalák,
Szegény jó anyámmal fölfordult a világ,
Ráborúlt fejjel az ágy szélére, s ottan
Elveszett fiáért sírt szíveszakadtan.
Édesapám csak egy-két könnyet hullatott,
De azután annál többet káromkodott,
Kicifrázta, mint a szűcs a remek-bundát,
S kegyetlen haraggal im e szókat mondá:
"Hogy tiszta nevemnek ilyen foltja vagyon!
Ha föl nem akasztják, én lövöm őt agyon!"
Híre ment e szónak, hozzám is elére,
Nem is tettem lábam apám küszöbére,
Mert nagyon jól voltam én annak tudója,
Hogy igéreteit ő híven lerója.
Kedvem kerekedett beszólni sok ízben
Öregeimhez, de biz én be se'' néztem,
Csak akkor, hogy már megleltem a valamit,
Megleltem, megleltem, két ország tudja: mit.
Tudnivaló dolog, hogy nem lőtt meg apám,
Mikor azután az ajtót rájok nyitám;
Olyat örűlt, hogy a szíve is fájt bele,
Sohasem volt szívvel így teli kebele,
S bezeg, nem mondja most, mint egykoron tevé,
Bezeg nem mondja, hogy beszennyeztem nevét.
Hát a jó szomszédok? ők most ezt beszélik:
"Mondtam, szomszéd uram, mondtam én mindétig,
Ne bántsa a fiát, a szerencse fordul,
Derék ember válik abbul a Sándorbul!"','Fölszedtem sátorfám és világnak mentem. -
Homályos sejtések munkálódtak bennem,
Hogy, ha elindulok, találok valamit,
Találok, hanem a sejtés nem mondta: mit?','Pest, 1847. június 14-30.',1847,'1847',array['Család']::text[],'{}'::text[],false,613,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184704-67','petofi','Múzsám és menyasszonyom','Kopogtatának. Kérdém: ki van ott?
"Leány" felelt kinn, aki kopogott.
''Leány? ah, úgy bocsánatot,
Ajtómat meg nem nyithatom:
Mit szólna majd menyasszonyom,
Ha megtudná idővel,
Hogy hölgyet fogadék el,
Mint vőlegény is... mert házasodom.''
"Épen azért jövék," felelt megint
Szomoru hangon a lyány odakint,
"Épen azért jövék;
Nyiss ajtót, áldjon meg az ég,
Számomra csak kinyithatod,
Én régi szeretőd vagyok."
''Mit? régi szeretőm? ugy annál
Kevésbbé jösz be, bármiként akarnál.
Aztán nekem nincs régi szeretőm;
Rútul hazudtam, amidőn
Leánynak azt mondám, hogy szeretem...
Az csak költői szalmaláng vala,
Mely született s ellobbana.
Ez bennem a legelső szerelem,
Büntessen isten engemet, ha nem!''
"Senkit sem szeretél? az nem lehet,
Egyet szerettél, egyet, engemet;
Eressz be, én múzsád vagyok,
Vagy még most is hiába kopogok,
Midőn megmondám nevemet?"
''Te vagy, galambom, kedves múzsám?
Miért nem szóltál? jer be hozzám,
Jer, nyitva ajtóm és karom,
Ölelj meg, édes angyalom!
Igen, te voltál az egyetlen,
Akit szerettem eddig életemben,
S szeretni foglak síromig,
Te drága szép leány, akit
Mellém a jó sors rendele,
Hogy légyen egy lény, melynek kebele
Hiven ver értem akkor is még,
Midőn a mondhatatlan inség
Korában elhagy az egész világ.
S ugy lett. Az árva ifjut elhagyák
Baráti, ismerősei.
Te nem tudád csak őt felejteni,
Te voltál hű vigasztalója, társa,
Mig tartott hosszú, kínos bujdosása.
És mostan téged én feledjelek,
Kihez csatolnak oly szent kötelek?
Nem, nem, örökre itt maradsz szivemben,
Ez a szív nagy, megfértek benne ketten,
S hiszem, tudom,
Hogy egymás mellett békeségben éltek,
Mert hisz te és menyasszonyom
Testvérek vagytok ti, édestestvérek:
Együtt születtetek az égben,
A csillagok legszebbikében,
S onnan le együtt szálltatok
Szivárványból szőtt szárnyakon
Egy szép tavaszi hajnalon,
Hogy engem boldogítsatok!''','Kopogtatának. Kérdém: ki van ott?
"Leány" felelt kinn, aki kopogott.
''Leány? ah, úgy bocsánatot,
Ajtómat meg nem nyithatom:','Pest, 1847. június 14-30.',1847,'1847',array['Szerelem','Természet']::text[],'{}'::text[],false,614,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184704-68','petofi','Az időhöz','Nem a terhes szekér
Alföld fertőiben,
Nem a vitorlátlan
Hajó a tengeren,
Nem e jő lassan, nem e jő;
Te jössz lassan, te vén idő.

Ah, hogy megvénülél!
Alig birod magad.
El is töréd azon-
Fölül még lábadat.
Mint béna koldús, csúszsz elé,
Ki mankóját elveszité.

Öledben ásitó
Fiaid, a napok;
Ásítni általuk
Én is kedvet kapok,
Ásítok olyan nagyokat,
Hogy majd elnyelem magamat.

Förtelmes vén idő,
Roszlelkü hatalom,
Mint fogsz te futni majd,
Ha én nem akarom.
Mint fogsz te futni majd, midőn
Velem lesz édes szeretőm.

Akkor megifjodol,
Vén bőröd leveted,
S öltesz sas-szárnyakat
Köszvényes láb helyett,
És messze, gyorsan szállasz el
Az élet örömeivel.

Mostan röpűlj, idő,
Míg távol kedvesem;
Midőn együtt leszünk,
Midőn őt ölelem:
Nem bánom én, ha mindenik
Órád eltart egy századig!','Nem a terhes szekér
Alföld fertőiben,
Nem a vitorlátlan
Hajó a tengeren,','Pest, 1847. június 14-30.',1847,'1847',array['Szerelem']::text[],'{}'::text[],false,615,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184704-69','petofi','Az erdőnek madara van...','Az erdőnek madara van,
És a kertnek virága van,
És az égnek csillaga van,
S a legénynek kedvese van.

Virítsz, virág, dalolsz, madár,
És te ragyogsz, csillagsugár,
S a lyány virít, dalol, ragyog...
Erdő, kert, ég, legény, boldog.

Hej elhervad a virágszál,
Csillag lehull, madár elszáll,
De a leány, az megmarad,
A legény a legboldogabb.','Az erdőnek madara van,
És a kertnek virága van,
És az égnek csillaga van,
S a legénynek kedvese van.','Pest, 1847. június 14-30.',1847,'1847',array['Természet','Szerelem']::text[],'{}'::text[],false,616,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184704-70','petofi','Tompa mihálynál','Itt vagyok, itt vagyok testestül-lelkestül.
Mit bámulsz ugy? ne szúrj szemeddel keresztül.
Húnyd be a szemedet, ha neki nem hiszesz,
Ha nem hiszed, hogy itt csakugyan én vagyok;
S kérdezd meg szívedet, hiszen majd felel ez...
Hallod? én is hallom, oly hangosan dobog.

Mit gondoltál, mikor ráztam a kilincset:
Vajjon ki az ördög háborítja csended?
Akárkit gondoltál, tudom, csak nem engem,
De azt is tudom, hogy jött volna akárki,
Nem fogadnál senkit nálam szívesebben,
S nem fognád forróbban karjaidba zárni.

Édes barátom!... de szólj már te is egyet,
Bennem a gondolat gondolatot kerget,
Ugy vagyok, mint mikor az éhes megrakott
Asztalhoz vetődik, - ugy vagyok valóban -
S nem tudja mely tálhoz kapjon. Nem szólhatok,
Hej pedig olyan sok mondanivalóm van.

Uj hivatalodban hogy éled világod?
Hogyan vagy, mióta az istent szolgálod?
Szépecskén benőtt az udvarod; semmi a,
Még jó: nem vesz éhen múzsád szárnyas lova.
Megfér-e együtt a lant és a biblia?
Nem vesz össze rajtad Apolló s Jehova?

S te, ki annyinak vagy megnyugtatására,
Száll-e megnyugovás lelked hullámára?
Vesd ki jóbarátom, vesd ki azt a férget,
Mely titkon, de folyvást emészt téged belül:
Hidd el, szép a világ, hidd el, szép az élet!
Ha vehetünk, mért ne vennénk örömibül?

S vehetünk. Rajtunk áll, hogy boldogok legyünk.
Csak akaratos ne legyen természetünk.
Gyermek-dolog, inkább szomjazni, mintsem más
Pohárból inni, mint amelyre kedve jött.
A bölcs - mert nem jogunk a sok válogatás -
Ahonnan jut, onnan issza az örömöt.

Mondjak-e rá példát? példa vagyok magam...
De im harangoznak: tiszteletes uram,
Vegye hóna alá imádságos könyvét,
S végezze illendőn a szent szolgálatot;
Én majd addig itt a kis kertben nézek szét,
S isteníge gyanánt szívom az illatot.

Mert az én templomom a nyílt, nagy természet...
Hanem akkor szóljunk, ha dolgodat végzed,
Akkor mondom el csak, hogy s mikép találtam
Homér-Arany Jánost, hazánk uj csillagát,
S az én csillagomtól, rózsámtól hogy váltam,
S oltár előtt áldást reánk melyik pap ád.

Te fogsz megesketni, jó Mihály barátom...
De ideje végre, a szót kettévágnom,
Eredj, mert a harang immár elhallgatott,
Menj, ne várakoztasd jámbor híveidet,
S vigyázz: örömedben egyik bordalomat
Ne mondd el valahogy a miatyánk helyett.','Itt vagyok, itt vagyok testestül-lelkestül.
Mit bámulsz ugy? ne szúrj szemeddel keresztül.
Húnyd be a szemedet, ha neki nem hiszesz,
Ha nem hiszed, hogy itt csakugyan én vagyok;','Beje, 1847. július 3-8.',1847,'1847',array['Természet']::text[],'{}'::text[],false,617,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184704-71','petofi','Alkony','Olyan a nap, mint a hervadt rózsa,
Lankadtan bocsátja le fejét;
Levelei, a halvány sugárok,
Bús mosollyal hullnak róla szét.

Néma, csendes a világ körűlem,
Távol szól csak egy kis estharang,
Távol s szépen, mintha égbül jönne
Vagy egy édes álomból e hang.

Hallgatom mély figyelemmel. Oh ez
Ábrándos hang jólesik nekem.
Tudj'' isten, mit érzek, mit nem érzek,
Tudja isten, hol jár az eszem.','Olyan a nap, mint a hervadt rózsa,
Lankadtan bocsátja le fejét;
Levelei, a halvány sugárok,
Bús mosollyal hullnak róla szét.','Diósgyőr, 1847. július 8.',1847,'1847',array['Természet']::text[],'{}'::text[],false,618,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184704-72','petofi','Panyó Panni','Panyó Panni hires nevem,
Pirulva kén említenem,
De lekopott rólam régen
Piros kendőm, a szemérem.

Ilyen magam fajtájának
Se'' országa, se'' hazája,
Vagyok a csárdák lakosa,
Keblem betyárok vánkosa.

Tolvajnéppel cimborálok,
Én vagyok az orgazdájok,
Lopott jószág csengő ára
Hever a ládám fiába''.

Tolvajoknak én danolok,
Tolvajokkal én táncolok.
Mulassatok, jó betyárok,
Van muzsika: varju károg.

Hej, sok derék ifju legény,
Ki nyakamon függött szegény,
Ott függ most az akasztófán,
Ördög négyágú villáján.

Hát magam mi véget érek?
Valahol megesz a féreg;
Ha már senkinek sem kellek,
A sövény alatt halok meg.

A sövény alatt dűlök el,
A cigányok temetnek el,
Valami vén cigány lök be
Dögkutyával egy gödörbe.

Jaj nekem, de neked, anyám,
Teneked még inkább jaj ám!
Téged számoltat meg isten,
Mert miattad lettem ilyen.

Szép, jó legény kért meg engem,
Ki szeretett, kit szerettem.
Az anyám lebeszélt róla,
Ez volt a siralmas óra!','Panyó Panni hires nevem,
Pirulva kén említenem,
De lekopott rólam régen
Piros kendőm, a szemérem.','Szerencs, 1847. július 9.',1847,'1847',array['Szerelem']::text[],'{}'::text[],false,619,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184704-73','petofi','Széphalmon','Te, a nemzet-hálátalanság
Égbekiáltó némasága,
A nemzet-szégyen Káin-bélyege,
Oh Széphalom!
Azért kellett-e csak
Hozzád zarándokolnom,
Hogy egy hajtásra oly hosszút igyam
A keserűség poharából,
Amilyet eddig még talán nem ittam?...
Ez volt tehát
A múzsák egykori tanyája,
Hol most haszonbérlő zsidó lakik?
Azon szobában,
Melyben Kazinczy Ferenc
Élt s kilehelte tiszta lelkét,
Most piszkos nyávogó porontyok
Hentergenek,
S a szentek szentéből, nejének
Szobájából ím kamra lett,
Mely ronda lommal van tele.
Ki innen e falak közül!
Félek, hogy a ház rám szakad,
Mert nagy teher nehezkedik rá:
Az isten átka. - -
Nagy ég, a pompás kert mivé lett!
Még mostan is mosolyg, mosolyg,
De szívetszaggatólag,
Mint a megőrült szép leány.
Elvadulának a gyümölcsfák,
S alattok fű terem buján,
Sürűn és magasan;
Tán el akarja rejteni
A pusztulásnak szellemét,
Mely itt két kézzel dolgozik,
Vagy az utat akarja
Elfödni, mely a sír mellé vezet,
Hogy a halottnak nyúgodalmát
Ne háborítsa senki,
Mert nyúgalomra nagy szüksége van,
Kit hetven évig üldözött az élet.
Itt nyugszik ő
Vad fák és vad füvek körében,
Fölötte hófehér szobor...
Miért fehér? miért nem fekete?
Vegyétek el s tűzzétek föl helyébe
Sötét sorsának zászlaját!
Oly bántó e fehér hazugság. -
És ezt is özvegye
Állíttatá, ez oszlopot;
De könnyen telt ki tőle,
Mert nem maradt több,
Csupán hét árva gyermeke.
S miért tett volna oszlopot
Sírjához a haza?
Hiszen mit tett ő a hazáért?
Miatta hét esztendeig szivá csak
A börtönök dögvészes levegőjét,
És csak fél századig
Tartá vállán, mint Atlasz az eget,
A nemzetiségnek ügyét.
Magyar nemzet, most nem volnál magyar,
Ő akkor volt az, midőn senki sem volt,
Midőn magyarnak lenni
Szégyen vala.
És te, hazám, te így fizetted őt!
Mig élt: fázott és éhezett,
S most sírja olyan elhagyott,
Mint számüzötté,
Ki idegen földön vesz el. -
Hálás haza,
A szent halott nevében
Vedd forró köszönetemet!
Ha gyermekem lesz,
Ki arra készül,
Hogy néked éljen:
Ide fogom majd őt vezetni
E sírhalomhoz... buzditásul.','Te, a nemzet-hálátalanság
Égbekiáltó némasága,
A nemzet-szégyen Káin-bélyege,
Oh Széphalom!','Széphalom, 1847. július 11.',1847,'1847',array['Haza','Elmúlás']::text[],'{}'::text[],false,620,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184704-74','petofi','A munkácsi várban','Itt tüzé föl piros zászlaját a
Szabadságnak Zrínyi Ilona?
A szabadság hősinek tanyája
Íme, íme most rabok hona.
Semmi más, mint dönthetetlen kőfal,
Semmi más, mint lánccsörömpölések -
Bátran tudnék a vérpadra lépni,
Oh de ez a börtön... ettül félek.

Föl s alá jár magas büszke fővel
Ott a sáncon egy ifjú fogoly;
Messzeszállott lángtekintetével
Vajjon hol jár gondolatja, hol?
Lépte gyors még; uj vendég bizonnyal,
Erejét az éj s lánc nem töré meg -
Bátran tudnék a vérpadra lépni,
Oh de ez a börtön... ettül félek.

Ott a másik sáncon egy öreg rab,
Nem tekint sem ide, sem oda,
Lassan hordja könnyü, száradt testét...
Nehezebb már lánca, mint maga.
Tört szeméből holt sugár buvik ki,
Mint a sírból a kisértő lélek -
Bátran tudnék a vérpadra lépni,
Oh de ez a börtön... ettül félek.

Ifju rab, nézd, mint virít az erdő,
Akkor is, ha kijösz, zöld lesz az,
Ah de téged, téged akkorára
A nyomor s bú régen behavaz.
És te vén rab, tőled már talán csak
Itt vesz búcsut a lánc és az élet -
Bátran tudnék a vérpadra lépni.
Oh de ez a börtön... ettül félek.

Föld alól föl halk nyögés jön; mint a
Köszörült kés, metszi szívemet.
El, el innen! fönn vagyok, és mégis
Környekez már-már az őrület,
Hát ha még lenn volnék, hogyha ott lenn
Híznék rajtam testi-lelki féreg!
Bátran tudnék a vérpadra lépni,
Oh de ez a börtön... ettől félek.','Itt tüzé föl piros zászlaját a
Szabadságnak Zrínyi Ilona?
A szabadság hősinek tanyája
Íme, íme most rabok hona.','Munkács, 1847. július 12.',1847,'1847',array['Haza']::text[],'{}'::text[],false,621,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184704-75','petofi','Meleg dél van...','Meleg dél van itt kinn a mezőben,
Rakja a nap a tüzet erősen,
Meleg dél van, meglippen a madár,
A fáradt eb kiöltött nyelvvel jár.

Két lyány gyüjti ott a széna rendét,
Két siheder hordja a petrencét,
Hej de nem telik nagy kedvök benne,
Mert ilyenkor súlyos a petrence.

Legjobb dolga van most a királynak,
Vagy ott annak a gulyásbojtárnak;
Király pihen aranyos karszéken,
Gulyásbojtár kedvese ölében.','Meleg dél van itt kinn a mezőben,
Rakja a nap a tüzet erősen,
Meleg dél van, meglippen a madár,
A fáradt eb kiöltött nyelvvel jár.','Beregszász, 1847. július 12.',1847,'1847',array['Természet']::text[],'{}'::text[],false,622,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184704-76','petofi','Amott az a hegy...','Amott az a hegy tőlem
Mi messze, messze még!
Kék színe csak kevéssel
Sötétebb, mint az ég.

Egészen e hegyig kell
Még zarándoklanom,
Vándorsarúimat le
Csak ottan oldhatom.

Ott vár reám, ott vár a
Végcél, a jutalom,
Az én szerelmes édes
Kedves kis angyalom.

Tudom, tudom nagyon jól,
Hogy örömet hozok,
Hogy az örömtül szíve,
Lelke repesni fog;

Csak azt szeretném tudni,
Vajon most sejti-e,
Hogy holnap ilyentájban
Oly nagy lesz öröme.','Amott az a hegy tőlem
Mi messze, messze még!
Kék színe csak kevéssel
Sötétebb, mint az ég.','Nagypeleske, 1847. július 13.',1847,'1847',array['Természet','Szerelem']::text[],'{}'::text[],false,623,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184704-77','petofi','Látom kelet leggazdagabb virányit...','Látom kelet leggazdagabb virányit,
A természetnek virág-háremét,
S a napnak rózsaszínű szempilláit:
Hasadt felhő mosolygó peremét;
Látok homályos pálmaligetet,
Hol a szellő rejtélyesen susog,
És énekel fényes madársereg...
Madarak? vagy tán zengő csillagok? -
- Látok nagy hegyről egy kék szigetet
A tenger és a messzeség ölében;
Körűlem ősz van, amott kikelet.
Vándorló darvak úsznak át az égen
Az őszbül a tavaszba, és utánok
Elküldi a szív minden vágyait,
S e vágy talán még jobban boldogít,
Mint ha ott volnék, ahol lenni vágyok. -
- Látok mesés, holdfényes éjszakát,
Az élet alszik, a halál viraszt:
A légen szellemek suhannak át,
Ruháiktól megrezzen a haraszt;
Nem alvilági rémes szellemek:
Boldog halottak, kik lejöttenek
A holdsugárok arany fonalán
Csillagjaidból, mennyei magasság,
Hogy kedveseiket meglátogassák,
S hogy ajkaikra csókolják talán
Az édes álmat, melyben lelkeik
Az ég üdvét előre érezik.
Látok mindent, mi sohasem a szemnek,
Csak a sejtésnek látható az éjben...
S mindezt két szemben látom: kedvesemnek
Sötét világú, ábrándos szemében.','Látom kelet leggazdagabb virányit,
A természetnek virág-háremét,
S a napnak rózsaszínű szempilláit:
Hasadt felhő mosolygó peremét;','Szatmár, 1847. július 14-27.',1847,'1847',array['Természet','Szerelem']::text[],'{}'::text[],false,624,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184704-78','petofi','Kard és lánc','Földre szállt a legszebb angyal
Isten engedelmivel, hogy
Fölkeresse, megtekintse
A legszebbik szép leányt.
Megtalálta. Megszerette.
És ezentúl rája nézve
Szebb volt a föld, mint a menny,
És azért is minden éjjel
Le-lejárt a szép leányhoz.
Csillagról csillagra lépett,
És midőn elérte már
A legalsó csillagot,
Ottan egy hattyúra ült,
Egy fehér hattyúra, és ez
Hozta őt a lyányka mellé,
Aki őt kertébe várta,
S szűz mosollyal fogadá,
Melytől a bimbók kinyíltak
És az elhervadt virágok
Újolag föléledének.
Ottan űltek és beszéltek,
Míg a hajnal nem hasadt,
És beszédök mindenről folyt,
Ami szép és ami szent.
A leányka szemlesütve
Hallgatá a fényes angyalt,
S ahogy egyszer föltekintett,
Annyi bűbáj volt szemében,
Hogy az angyal térdre omlott,
És egy csókot kére tőle,
És a lyány meg nem tagadta.
Milyen csók volt ez!... midőn
Összeért az angyal ajka
És a lyányé, az egész föld
Megrezzent a kéj miatt,
Mintha az csak egy szív volna;
S odafönn az égen minden
Csillag egy-egy csengetyű lett,
Mely varázshangon csilingelt,
S e még nem hallott zenére
A virágok, mint megannyi
Tündérek, táncolni kezdtek,
És a hold - mivel talán az
Elpirult lyány belenézett -
Elpirúla szinte, s tőle
Rózsaszínű lett az éj.
És az angyal csókja szépen
Megfogamzott: a leányka
Anya lett: oly gyermeket szűlt,
Oly dicsőet, aminő csak
Akkoron születhetik, ha
Föld és ég ölelkezék.
Kardot szűlt a lyányka, kardot,
És ez a kard... a szabadság.

*

Feljött a legrútabb ördög
Sátán engedelmivel,
Fel a földre, hogy meglelje
A legocsmányabb boszorkányt.
Megtalálta. Megszerette.
És ezentúl jobban tetszett
Néki a föld a pokolnál,
És azért is minden éjjel
Föl-följárt a boszorkányhoz.
Tűzokádó hegy torkában
Jöttek össze éjfelenként.
Békafejű, kígyófarkú,
Lángsörényű, sárkánylábú,
Vad fekete paripa
Hozta föl az ördögöt,
S a boszorkány, denevérek
És baglyok kíséretében,
Hórihorgas seprőnyélen
Lovagolva jött elé a
Tűzokádó hegy torkába.
Ottan űltek és beszéltek,
Míg megszólalt a kakas,
És beszédök mindenről folyt,
Ami rút s szentségtelen.
S szólt az ördög: "Fázni kezdek,
Jöszte beljebb, jöszte beljebb,
Le a hegy legfenekére,
A tüzeknek őshonába...
Hah, még itt is fázom, fázom,
Szinte csattog a fogam...
Jer, ölelj meg, jer, csókolj meg!"
S ölelkeztek, csókolóztak.
Milyen csók volt ez!... midőn
Összeértek ajkaik,
A boszorkány s ördög ajka:
Összeborzadott a föld,
S dörgött, morgott, mintha vészes
Felhőket nyelt volna el,
S elkezdett okádni a hegy,
És okádta ég felé a
Tűzesőt, tűzköveket,
És egy láng lett a világ,
Csak a csillagok s a hold
Vontak fátyolt arcaikra,
Sűrű fátyolt, feketét,
Hogy semmit ne lássanak.
S megfogant az ördög csókja,
Anya lett s szűlt a boszorkány,
Szűlt oly förtelmet, minő csak
Akkoron születhetik, ha
Föld s pokol ölelkezék.
Láncnak híják a boszorkány
Undok kölykét, láncnak híják,
És e lánc... a szolgaság.

*

És a mennynek s a pokolnak
Két szülötte, a szabadság
S szolgaság, a kard s a lánc,
Harcot űz élet-halálra,
Hosszu harcot, hosszu harcot,
Elfáradva, nem pihenve.
Tompa, csorba már a kard,
De a lánc is szakadoz.
Várjunk, várjunk egy kicsit,
Megtudjuk már nemsokára:
Melyik lészen úr a földön?
Melyiké lesz a világ?','Földre szállt a legszebb angyal
Isten engedelmivel, hogy
Fölkeresse, megtekintse
A legszebbik szép leányt.','Szatmár, 1847. július 14-27.',1847,'1847',array['Szerelem','Természet','Haza']::text[],'{}'::text[],false,625,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184704-79','petofi','Válasz kedvesem levelére','Megjött, megjött az óhajtott levél!
Elolvasám, az isten tudja hányszor,
S még számtalanszor olvasandom el,
Mindaddig, amíg mindenik betűje,
Minden vonási válhatatlanúl
Szivemhez nőnek csillagok gyanánt;
Legyen számatlan ragyogó világot
Magában tartó mindenség szivem!...
Most is kezemben e levél, s remegve
Érinti ajkam, félvén, hogy talán
Szentségtelenség megcsókolnom azt.
Előttem olyan szentek e sorok!...
Oh lyány, ki vagy te? nem tudod magad sem;
Hadd mondjam én meg, hogy ki és mi vagy.
Midőn feljöttem gyermekéveim
Szűk völgyéből az ifjuság hegyére,
S láttam körűlem a roppant világot,
Mely szépségekben olyan gazdag, és
Gazdagságában olyan szép, hogy a szem
Egy élten át elgyönyörködhetik
Csak egy parányi részén is... midőn
Ezt a világot láttam, fölkiálték:
"Dicső, dicső a munka! hol keressem
A nagy mestert, ki mindezt alkotá?
Oh hol vagy, isten? hadd keresselek föl,
Hadd térdeljek le, hadd imádjalak!"
S utánküldém elmémet; bejárta
Minden vidékét a bölcselkedésnek,
Röpűlt, gyorsabban, mint az üstökös,
Röpűlt, amerre más elméje járt
S amerre nem járt, megfutá nagy útját,
S esztendők mulva búsan tért haza,
Búsan, fáradtan. Hasztalan bolyongott.
Ekkor veled volt szép találkozásom,
Veled, szép lyányka, s megszerettelek.
Te megnyitád előttem kebledet,
Mely eddig még nem nyílt meg senkinek,
S ott láttam én, hogy akit úgy kerestem,
A jó s nagy isten kebledben lakik,
Igen, te vagy az isten lakhelye!
Hol volt előtted és hol lesz utánad?
Azt nem tudom, de most benned lakik,
Hogy érdemeltem én, meglátni őt? e
Boldogság épen engemet hogy ért?
Vagy oh igen, megérdemeltem én,
Hogy színről-színre lássam, mert hiszen
Ugy, mint én, látni senki nem kivánta.
De netalán, ha méltatlan valék:
Méltatlan, oh lyány, nem leszek reá,
Hogy nékem ád az isten tégedet, hogy
Benned nekem megmutatá magát.
Tiéd szerelmem, osztatlan tiéd,
S e szerelem nagy! egykor a világot
Borítá el gyülölség képiben;
Most téged illet, téged egyedűl
E szerelemmé vált nagy gyűlölet,
E felhőktől-megvált mennyboltozat.
Tiéd jövendőm, parancsolj vele.
Lemondok érted minden vágyaimról,
Reményeimről... ez még mind kevés,
De ami több, de ami sok, mi minden:
Ha úgy kivánod, elveimrül is
Lemondok érted; hordom fejemen,
Mig élek, s ha meghaltam, síromon
A megvetés s gyalázat bélyegét! -...
De ezt kivánni tőlem nem fogod,
Tudom, hogy nem; mert akit te szeretsz,
Annak nevén szégyenfolt nem lehet.
Sőt ösztönözni fogsz, hogy úgy haladjak,
Amint megkezdém pályázásomat.
S én úgy halok meg, amint születém,
Meg nem fordulva, hajthatatlanul.
E névnek, melyet én magam teremték,
Elpusztitója nem leszek magam.
A név, amelyet örököl utódom,
Ha nem nagy is, de szép és tiszta név lesz...
Lehetne tán, lehetne tán nagy is,
Ha hozzáadnád lelked fénysugárit,
Ha vélem együtt síkra szállanál,
Oh mert bölcsődbe téged is, szerelmem,
A múzsa tett, a múzsa ringatott.
De te erőd nem ismered, s ki bízzék
A harcosban, ha maga sem bizik?
Jobb, jobb, maradj el a csaták teréről,
Hol úgyis a sors többnyire azért
Ád csak babért, hogy meggyilkoltatott
Boldogságunknak szemfedője légyen.
Maradj, maradj el a csaták teréről;
Nem lész kevésbé kedves én előttem
Árnyas magányodnak homályiban,
Mint lennél kinn, bár bámultatva, a
Nyilvánosság napfényes ormain;
Sőt kedvesebbé tészen a tudat,
Hogy aki mély és nagy tenger lehetnél,
Csak mint kicsiny kis harmatcsepp ragyogsz
A szerénységnek rózsalevelén.','Megjött, megjött az óhajtott levél!
Elolvasám, az isten tudja hányszor,
S még számtalanszor olvasandom el,
Mindaddig, amíg mindenik betűje,','Szatmár, 1847. július 14-27.',1847,'1847',array['Szerelem','Természet','Haza']::text[],'{}'::text[],false,626,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184704-80','petofi','Jó ideje lement a nap...','Jó ideje lement a nap,
Le is szállott már a harmat,
Már a hold is magasan van,
Éjfél is lesz innen-onnan.

Mit csinál mostan Juliskám?
Összetette kis kezit tán,
S imát mond: ha imádkozik:
Tudom, értem imádkozik.

Mit csinál mostan Juliskám?
Már régen el is aludt tán;
Ha elaludt és álmodik:
Tudom, felőlem álmodik.

S ha Juliskám se'' nem alszik,
Se'' pedig nem imádkozik,
Hanem csak úgy gondolkodik:
Tudom, rólam gondolkodik.

Gondolkozzál, gondolkozzál,
Gyönyörűséges virágszál!
Gondolataid olyanok,
Mint azok a szép csillagok.

És vajon a csillagokat,
Juliskám, nem te gondoltad?
Te gondoltad ki ezeket,
Mikor szerelmed született.','Jó ideje lement a nap,
Le is szállott már a harmat,
Már a hold is magasan van,
Éjfél is lesz innen-onnan.','Szatmár, 1847. július 14-27.',1847,'1847',array['Szerelem','Természet']::text[],'{}'::text[],false,627,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184705-81','petofi','A betegséggel szomszéd a halál...','A betegséggel szomszéd a halál...
Gyógyulj meg édes, szép menyasszonyom!
Mivé leszek, ha ajkaid helyett
Fejfádat csókolok?

Itt hagynál engem? engem! és miért?
Hogy minél elébb föl az égbe menj?
Szebb lesz neked, szebb lesz velem a föld,
Mint nélkülem a menny. -

Ne vedd el tőlem, oh sors, hívemet...
Megénekeltem már egy holt leányt...
Ne kivánd, hogy két koporsó közé
Szoruljak, ne kivánd!

Hagyd meg nekem, sors, hagyd meg őt nekem!
Hisz ő a díj egy olyan életért,
Amely beillik kárhozatnak is,
Ha nem nyer semmi bért.

Ő mennyországom, földi örömem,
Földi virágom, égi csillagom,
Ő a mindenség reám nézve... én
Oda nem adhatom.

Vagy vidd el őt, kegyetlen hatalom,
Vidd el, ha róla így határozál...
Egy tőr megnyitja szívem ajtaját,
S lelkem utánaszáll.','A betegséggel szomszéd a halál...
Gyógyulj meg édes, szép menyasszonyom!
Mivé leszek, ha ajkaid helyett
Fejfádat csókolok?','Szatmár, 1847. július 14-27.',1847,'1847',array['Elmúlás','Szerelem']::text[],'{}'::text[],false,628,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184705-82','petofi','Az elhagyott zászló','Megtépve, megcsufolva,
Sivatag közepén,
Magában áll a zászló,
Melyet szolgálok én.
Nagy és hosszú vihar volt,
Mely rajta ennyit tépe,
De bármint meg van rontva,
Még most is látszik csonka
Szárnyán az isten képe.

És e szent jelnek egyre
Gyérülnek hívei.
Bálvány elébe mennek
Térdet, főt hajtani.
Hadd menjenek! nem méltók
Egy sorban állni vélünk.
Ha a fecskék ledérek
S éghajlatot cserélnek,
Mi sasok nem cserélünk.

Mily varázshatalmú e
Diszetlen csonka jel!
A legdicsőbbek érte
S alatta haltak el.
Mutatja ez, mutatja,
Hogy az igazság itt van,
S ez isten oltáránál,
Bár a világ odább áll,
Megállok a siriglan!','Megtépve, megcsufolva,
Sivatag közepén,
Magában áll a zászló,
Melyet szolgálok én.','Szatmár, 1847. július',1847,'1847','{}'::text[],'{}'::text[],false,629,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184705-83','petofi','Már, galambom, engedj meg...','Már, galambom, engedj meg, de
Ki kell mondanom:
Legyen vége a tréfának,
Mert nagyon unom.

Eddigi szeszélyedet csak
Megbocsátom még;
Más ennyit sem tűrne, régen
Mondta voln'': elég.

Vinné el az ördög ezt az
Én jó szívemet!
Boldogságom ennek mindig
Áldozatja lett.

Kifog rajtam minden gyermek
És minden leány...
De fogadom, hogy máskép lesz,
Máskép ezután.

Azért vége a tréfának,
Szedd össze magad,
És hallgasd meg ünnepélyes
Komoly szavamat:

Amit eddig még nem tettél,
Bármint kértelek,
Tedd ezennel, tedd, ha mondom,
Rögtön csókolj meg!','Már, galambom, engedj meg, de
Ki kell mondanom:
Legyen vége a tréfának,
Mert nagyon unom.','Szatmár, 1847. július',1847,'1847',array['Szerelem']::text[],'{}'::text[],false,630,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184705-84','petofi','Koronázás','Heine után németből

Föl, föl, dalaim, jó dalaim!
Föl, fegyverkezzetek!
Hangoztassátok a harsonákat,
S emeljétek paizsra
Ez ifju leányt,
Ki mátul egész szivemet
Birandja mint királyné.
Üdvezlégy, ifju királyné!
Ott fönn lerántom a napról
A piros sugáru aranyat,
S belőle fölszentelt fejedre
Koronát fonok.
Az égboriték lobogó kék selymiből,
Amelyen az égi gyémántok ragyognak,
Egy drága darabot lemetszek,
S koronázási köpenyként
Királyi vállaidra akasztom.
Kiséretűl adok neked
Fölcifrázott szonetteket, kevély
Tercínákat s udvarias stancákat;
Elmésségem leszen kengyelfutód,
Bohócod képzeletem,
Heroldod húmorom,
Nevető könyűkkel a címeren.
Magam pedig, királyné,
Letérdelek előtte,
S hódolva, pirosbársony párnán
Átnyujtom a kis darab észt,
Amelyet elődöd
Még irgalomból meghagyott.','Heine után németből
Föl, föl, dalaim, jó dalaim!
Föl, fegyverkezzetek!
Hangoztassátok a harsonákat,','Szatmár, 1847. július',1847,'1847',array['Szerelem']::text[],'{}'::text[],false,631,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184705-85','petofi','Augusztus 5-dikén','Itt a gyűrü, itt a gyűrü,
Itt van végre ujjamon!
Itt van ajka, itt van ajka,
Itt van végre ajkamon!

Oh, mi édes, oh, mi édes,
A csók piros ajakán!
A kerek világnak minden
Édessége itt van tán.

Csókolj, csókolj!... senki sem lát...
Szíjad, szíjad ajkamat!
S ha látnak is? jegyeseknek
Csókolózni már szabad.

Addsza ajkad, addsza orcád,
Homlokod, szemeidet,
Elborítom csókjaimmal,
Mint a hajnal az eget.

Szédülök... fogj meg karoddal,
Lágy karoddal, szép leány!
Csók-e ez vagy bor? biz én már
Nem is tudom igazán,

Bor lesz ez, bor! ilyet ittak
Az olympi istenek,
S én, az ember, nem birom meg,
Fölforgatja eszemet.

Mámor szállt nehéz fejemre,
Oh de milyen mámor ez!
Égbe vitt... a föld alattam
Végtelen mélységbe vesz.

Túljutottam már a felhők
Tarka vándor-táborán;
Csillagok között röpűlök,
Mindenik egy csalogány.

Mint dalolnak, mint dalolnak!
Ilyet nem hallott fülem.
S milyen fény! százezer villám
Nyargalózik körülem.

Hát a szívem, hát a szívem?
Ott van, ott van még a baj...
Fiu, ugy vigyázz magadra:
Örömedben meg ne halj!','Itt a gyűrü, itt a gyűrü,
Itt van végre ujjamon!
Itt van ajka, itt van ajka,
Itt van végre ajkamon!','Erdőd, 1847. augusztus 5.',1847,'1847',array['Szerelem']::text[],array['nyar']::text[],false,632,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184705-86','petofi','Levél Arany jánoshoz','Meghaltál-e? vagy a kezedet görcs bántja, imádott
Jankóm, vagy feledéd végkép, hogy létezem én is?
Vagy mi az ördög lelt?... híred sem hallja az ember.
Hogyha magába fogadt az öröklét bölcseje, a sír:
Akkor béke veled, legyenek szép álmaid ott lenn,
Feddő kérdésem nem fogja zavarni nyugalmad,
Hogy mi okért hallgatsz? mért késel szólni levélben?
Hogyha pedig görcs bánt, menj a patikába, s iparkodj
Meggyógyulni, fiam, s aztán írj rögtön, azonnal.
S ha feledél engem? ha barátod volna feledve?
Dejsz ugy, öcsém, vessz meg, kívánom tiszta szivembül.
Te mikoron nevedet keblem mélyébe leírtad,
Mit tettél, tudod azt? gránitsziklába acéllal
Vágtál életen át múlás nélkűli betűket;
Hát én? én nevemet karcoltam volna homokba,
Melyet, névvel együtt, egy hó szellője is elfúj?
Megköszönöm, ha netán így van... no de elhiszem inkább,
Hogy rosz verseim is vannak, mint hogy te feledtél.
Lomha vagy, itt a bibéd; restelsz, mit jó magam, írni.
Kérlek, hagyd nekem a restséget, légy te serényebb,
Lásd, nekem úgy illik, (s oly jólesik!) úgye lemondasz
Róla, ha én kérlek! - Hah, máris látlak ugorni,
Mint ragadod nyakon a tollat, mint vágod az orrát
A tintába, miként huzod a sok hosszu barázdát
A papiron, ringy-rongy eszméket vetve beléjök...
Mert ne is írj inkább, hogysem bölcs gondolatokkal
Terheld meg leveled s gyomrom, mert semmi bolondabb
Nincsen, mint az okos levelek, s én iszonyuképen
Irtózom tőlök; tán mert én nem tudok olyat
Kompónálni, azért. Ez meglehet. Ámde hogy úgy van,
Esküszöm erre neked túróstésztára, dohányra
És mindenfélére, mi csak szent s kedves előttem. -
Drága komámasszony, kegyedet kérem meg alássan,
Üsse agyon férjét és szidja meg istenesen, ha
Még ezután sem fog nekem írni az illyen-amollyan.
Írjon mindenről hosszan, de kivált, ha kegyedről
Ír röviden, haragunni fogok majd hosszu haraggal.
El ne feledje a barna Lacit s a szőke Julist, e
Kedves gyermekeket. Hát a kert hogy van, amelynek
Rózsáin szemeim sokszor függének, amíg a
Messzeröpűlt lélek hívemhez vitte szerelmét?
És a csonka torony, mely a harcoknak utána
Most szomorún hallgat gyér fű-koszorúzta fejével,
S várja jövendőjét, mely lábát ráteszi, s akkor
Összeomol, mint a koldús, ha kikapja kezéből
A mankót a halál... áll még a gólya fölötte,
Méla merengéssel nézvén a messze vidékbe?
Mindenről akarok, mi nekem kedves vala, tudni.
Jártam azóta dicső szép tájakon, ámde tiétek
Mindig eszemben volt, bár nincs mit rajta csodálni;
A veletek töltött kor tette szivembe örökké.
S jártam azóta magas fényes paloták körül, ahol
Minden, minden nagy; gazdáik lelke kicsiny csak...
Akkor eszembe jutott alacsony hajlékotok, ebben
Mind kicsinyecske, de a gazdának lelke nagy és szép! -
Ejnye, mi a fene lelt engem, hogy szembe dicsérek?
Most veszem észre, hohó! mind, amit mondtam, hazugság,
Csúnya hazugság volt. Le akartam csak kenyerezni
A nótáros urat, hogy... hogy... majd beszerezzen
Bakternek vagy kondásnak falujába, ha e szép
Hívatalok valamelyike meg fog ürűlni idővel.
Hja, nekem is hozzá kell látnom végre, barátom.
Házasodom, tudod azt, s tudod azt is, hogy jövedelmet
Dús uradalmam nem hullat zsebeimbe, mióta
Századik édesapám eladá vagy meg se'' szerezte.
S így az eléléshez nincsen mód, nincs! hivatal kell.
Meghajtom fejemet, szépen mosolyogni tanúlok,
Nyájas szófogadás, kígyó-csúszásu hizelgés
Lesz kenyerem (s zsíros kenyerem)... hah, lesz a kutyának,
Nem pedig énnékem! pusztán a gondolat is már
Lángfelhőket idéz véres szemeimnek elébe,
És szívem tombol, mint a harmadfü csikó, ha
A pányvás kötelet legelőször dobja nyakába
A pásztor, hogy a ménesből kocsirúdho'' vezesse.
Nem a tehertől fél, amelyet húznia kell majd,
Nem! hanem a hámtól, mely korlátozza futását.
És amit így elveszt, azt nem pótolja sem abrak,
Sem pedig a ragyogó szerszám. Mit néki az étel
S a hiu fény! megelégszik ő a pusztai gyeppel,
Bármi sovány, s a záporesők szabad égnek alatta
Verhetik oldalait s a bozót hadd tépje sörényét,
Csak szabadon járjon, csak kergethesse tüzében
A sivatag viharát s a villám sárga kigyóit - -
Isten hozzátok! lelkem múlatni szeretne
Még veletek, kedves hiveim, de az elragadó szél
Képzeletem százrétü vitorlájába beléfújt,
Szétszakad a horgony, fut gályám, elmarad a part,
S ringat habkarján a látkör nélküli tenger,
És mig az orkán zúg, s a felhők dörgenek, én a
Lant idegébe kapok, s vad tűzzel zengi el ajkam
Harsány himnuszodat, százszorszent égi szabadság!','Meghaltál-e? vagy a kezedet görcs bántja, imádott
Jankóm, vagy feledéd végkép, hogy létezem én is?
Vagy mi az ördög lelt?... híred sem hallja az ember.
Hogyha magába fogadt az öröklét bölcseje, a sír:','Szatmár, 1847. augusztus 6.',1847,'1847',array['Természet','Szerelem','Család']::text[],'{}'::text[],false,633,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184705-87','petofi','T. M. kisasszonyhoz','Hogyan vagy, kedves jó leányka?
Alig hogy hallom híredet,
Pedig nagyon szeretném tudni,
Vidám-e vagy bús életed?

Ha jól van dolgod, hadd örülnék,
Mert a boldogság úgy egész,
Sőt kétszerezve lesz azáltal,
Ha más is nyer belőle részt.

S ha bánatod van, hadd busúlnék
Veled, hadd venném át felét,
Másik felével a harcot csak
Könnyebben végigküzdenéd.

Elmondanád, mi bántja lelked,
Mi mérte rája a csapást?
S ha gyógyszert nem tudnék is adni,
Adhatnék tán vigasztalást.

Mint szeretném én, mint szeretném,
Ha el lehetne mondani:
Mily boldog vagyok, meddig mennek
Boldogságom határai...

Sőt nincs is annak, nincs határa,
Ugy nyúlik által lelkemen,
Miként a föld felett az ég, mely
Jelen van, mindenütt jelen.

S e nagy kéjtengert, melynek minden
Cseppjében egy gyöngy, egy öröm
- Nem csak magam: másodmagammal -
Nemes szivednek köszönöm.

Tudd ezt, leányka, és ha sorsod
Nehéz: enyhíti e tudat;
Mert a boldogságnak testvére:
Boldoggá tenni másokat.','Hogyan vagy, kedves jó leányka?
Alig hogy hallom híredet,
Pedig nagyon szeretném tudni,
Vidám-e vagy bús életed?','Szatmár, 1847. augusztus',1847,'1847',array['Szerelem']::text[],'{}'::text[],false,634,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184705-88','petofi','A költészet','Oh szent költészet, mint le vagy alázva,
Miként tiporják méltóságodat
Az ostobák, s ép akkor, amidőn
Törekszenek, hogy fölemeljenek.
Azt hirdetik föl nem kent papjaid,
Azt hirdetik fennszóval, hogy terem vagy,
Nagyúri, díszes, tündöklő terem,
Hová csupán csak fénymázas cipőkben
Lehet bejárni illedelmesen.
Hallgassatok, ti ál, hamis proféták,
Hallgassatok, egy szótok sem igaz.
A költészet nem társalgó-terem,
Hová fecsegni jár a cifra nép,
A társaság szemenszedett paréja;
Több a költészet! olyan épület,
Mely nyitva van boldog-boldogtalannak,
Mindenkinek, ki imádkozni vágy,
Szóval: szentegyház, ahová belépni
Bocskorban sőt mezítláb is szabad.','Oh szent költészet, mint le vagy alázva,
Miként tiporják méltóságodat
Az ostobák, s ép akkor, amidőn
Törekszenek, hogy fölemeljenek.','Szatmár, 1847. augusztu',1847,'1847',array['Szerelem']::text[],'{}'::text[],false,635,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184705-89','petofi','Az én Pegazusom','Nem angol ló az én Pegazusom,
Vékony nyakkal, hórihorgas lábbal,
Nem is német teherhordó állat,
Széles háttal, medve-topogással.

Magyar csikó az én Pegazusom,
Eredeti derék magyar fajta,
Világospej síma selyem szőrrel,
A napsugár hanyatt esik rajta.

Nem nevelték benn az istállóban,
Nem is igen járt az iskolába;
Kinn született, ott kinn fogtam el a
Kis-kunsági szép nagy pusztaságba''.

Nem bosszantom a hátát nyereggel,
Egy kis csótár van csak ráterítve,
Úgy ülök rajt, és sebesvágtatva
Ragad, mert ő a villám testvére.

A pusztákra visz legörömestebb,
Mert a puszta születési helye,
Hej, ha arra fordítom a kantárt,
Ugy megugrik, alig bírok vele.

A falukban megállok egy szóra,
Hol a lyányság, mint a méhe-raj, áll;
A legszebbtől egy virágot kérek,
Akkor aztán, akkor ujra hajrá!

Visz csikóm, s csak szavamba kerűlne,
Hogy kivigyen ebből a világból;
Ha szakad a tajték róla: ez a
Sok tűztől van, nem a fáradságtól.

Pegazusom sohasem fáradt el,
Hamarjában még el sem is fárad,
Biz ezt ne is tegye, mert még messze
Vagyon útam, vágyaim határa.

Vágtass, lovam, vágtass, édes lovam,
Ha követ vagy árkot lelsz, ugord át,
S lábad alá ha ellenség botlik,
Rúgd agyon az ilyen-olyan adtát!','Nem angol ló az én Pegazusom,
Vékony nyakkal, hórihorgas lábbal,
Nem is német teherhordó állat,
Széles háttal, medve-topogással.','Szatmár, 1847. augusztus',1847,'1847',array['Természet']::text[],'{}'::text[],false,636,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184705-90','petofi','Ismét könny!','Azt hittem, hogy szemembül a sors
Örökre számüze,
S ismét pillámon vagy, sötét
Fájdalmak fényes követe!

Alig vidultam a boldogság
Nyájas napsúgarán,
Ismét felhő takarta el,
Mely önti záporát reám.

De nem, nem zápor ez; csak egy könny,
Egy könnycseppecske csak,
És mégis kínosabb talán,
Mint volna egy egész patak.

Oh sírtam én már, sokat sírtam
Miattad, szerelem,
És siratálak tégedet,
Szegény pusztúló nemzetem.

De ennél keserűbb könyűt még
Nem ejtettem soha,
Sem érted, égő szerelem,
Sem érted, hamvadó haza.

E könny, mint a tüzes vas, mint a
Pokolnak lángja, süt...
Irtóztatón, irtóztatón
Orromba ment a pípafüst!','Azt hittem, hogy szemembül a sors
Örökre számüze,
S ismét pillámon vagy, sötét
Fájdalmak fényes követe!','Szatmár, 1847. augusztus',1847,'1847',array['Szerelem']::text[],'{}'::text[],false,637,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184705-91','petofi','Falu végén kurta kocsma...','Falu végén kurta kocsma,
Oda rúg ki a Szamosra,
Meg is látná magát benne,
Ha az éj nem közelegne.

Az éjszaka közeledik,
A világ lecsendesedik,
Pihen a komp, kikötötték,
Benne hallgat a sötétség.

De a kocsma bezzeg hangos!
Munkálódik a cimbalmos,
A legények kurjongatnak,
Szinte reng belé az ablak.

"Kocsmárosné, aranyvirág,
Ide a legjobbik borát,
Vén legyen, mint a nagyapám,
És tüzes, mint ifju babám!

Húzd rá cigány, húzzad jobban,
Táncolni való kedvem van,
Eltáncolom a pénzemet,
Kitáncolom a lelkemet!"

Bekopognak az ablakon:
"Ne zugjatok olyan nagyon,
Azt üzeni az uraság,
Mert lefeküdt, alunni vágy."

"Ördög bújjék az uradba,
Te pedig menj a pokolba!...
Húzd rá, cigány, csak azért is,
Ha mindjárt az ingemért is!"

Megint jőnek, kopogtatnak:
"Csendesebben vigadjanak,
Isten áldja meg kendteket,
Szegény édesanyám beteg."

Feleletet egyik sem ad,
Kihörpentik boraikat,
Végét vetik a zenének
S hazamennek a legények.','Falu végén kurta kocsma,
Oda rúg ki a Szamosra,
Meg is látná magát benne,
Ha az éj nem közelegne.','Szatmár, 1847. augusztus',1847,'1847',array['Család']::text[],'{}'::text[],false,638,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184705-92','petofi','Vándorlegény','Hogyha üres az embernek
Zsebje: üres a has is.
Zsebem üres, ennélfogva
Üres az én hasam is.

Tennap ettem utójára,
Az igaz, hogy keveset,
No de semmi! van elég, ki
Én helyettem is evett.

S holnap ujra nap lesz, akkor
Ehetem majd... ha lesz mit.
Addig reménység-anyámnak
Szívom édes emleit.

Hasam üres, de helyette
Teli vannak szemeim,
Megtöltötték a hidegtől
Kiszorított könnyeim.

És ez jó, hogy ily hideg van,
Legalább sietnem kell,
S így a csárdát, mely még messze,
Szaporábban érem el.

Gyi, te fakó, gyi, te szürke,
Gyi, két lábam, fussatok!...
Milyen áldott két csikó ez,
Egyik sem kér abrakot.

Egyik fakó, másik szürke,
Mert nadrágom két darab,
Egyik szárát úgy toldottam
A másikhoz a minap.

Volt nekem jó új ruhám is,
Volt nekem szép uj ruhám;
De kimélni kell az újat...
Hogy ne kopjék, eladám.

S hogy kijátsszam a haramját,
Ki megállit, meglehet:
A legelső kocsmárosnak
Általadtam pénzemet.

Most amely''k zsivány nálam csak
Egy fillérre is akad,
Díjul annak én azonnal
Fizetek száz aranyat.

Nincs zsivány, de a helyett a
Szél kutatja zsebemet.
Szél barátom, ne kutyálkodj,
Megütöm a kezedet.

Tréfa, ami tréfa, de ez
Kriminális egy idő,
Összeesküdt ellenem ma
Szél, hidegség, hó, eső.

Az az egyetlen szerencsém,
Hogy mezítláb útazom,
Telemenne vízzel, sárral
A csizmám e rosz uton.

Gúnykacaj gyanánt süvöltöz
Fölöttem a fergeteg.
Hadd gunyoljon! rajta egykor
Én is jókat nevetek.

Ád az isten egy kis műhelyt,
Ád az isten majd nekem,
Benne lesz meleg kandallóm,
Feleségem, gyermekem...

Ott ha a szél, e cudar szél
Ablakomnál megjelen:
Olyat kacagok szemébe,
Hogy megpukkad mérgiben!','Hogyha üres az embernek
Zsebje: üres a has is.
Zsebem üres, ennélfogva
Üres az én hasam is.','Szatmár, 1847. augusztus',1847,'1847',array['Természet']::text[],'{}'::text[],false,639,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184705-93','petofi','Ne bántson az meg...','Ne bántson az meg, fényes napvilágom,
Ha arcom néha elsötétedik;
Nem lehetek én, bármiként kivánom,
Még előtted sem folyton-folyva vig.

Nyugtasson meg, hogy ilyenkor szivembe
A bánatot nem te hozád vala...
Hogyan szereznél bánatot nekem te,
A földnek égnek legjobb angyala?

Egészen más az, amért engem néha
Kisértetes halványság színe fed;
Én egy szellemnek vagyok martaléka,
Mely meg-meglátogatni nem feled.

Hiába kérem, hasztalan esengek,
Hogy hagyjon el, hagyjon magamra már;
Kérlelhetetlen, siket ő! nem enged,
Talán örökké vissza-visszajár.

Sokszor, midőn a kéj legédesb nedve
Érinti már-már szomjas ajkamat,
Megjelenik... kezem megáll ijedve
És földre ejti a telt poharat.

E szellem a mult! mult időm emléke,
A legvadabb, legborzasztóbb alak,
Mit egy pokoli bor hevétül égve
A sors viszályi kigondoltanak.

Ezen szellemnek vagyok odavetve;
Fel-feltör hozzám sírja mélyibül,
S míg súgja rémes ígéit fülembe,
Lelkem lelketlen sziklává kövül.

Ne szólíts ekkor, úgysem értenélek,
Édes hangod sem hatna szívemig;
Várd el békében, míg a jelenésnek
Irtóztató órája eltelik.

Körűlem ilyen álom fon hideg kart,
S miatta mégis mennyi a kinom!
Álom csupán... de mit használ? amig tart,
Eszembe nem jut, hogy csak álmodom.','Ne bántson az meg, fényes napvilágom,
Ha arcom néha elsötétedik;
Nem lehetek én, bármiként kivánom,
Még előtted sem folyton-folyva vig.','Szatmár, 1847. augusztus',1847,'1847','{}'::text[],'{}'::text[],false,640,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184705-94','petofi','Homér és Oszián','Hol vannak a hellenek és hol a celták?
Eltűntenek ők, valamint
Két város, amelyet
A tengerek árja benyel,
Csak tornyaik orma maradt ki a vízből...
E két torony orma: Homér s Oszián.

Koldús vala az,
Királyfi emez. Mi különbség!
De egybe'' hasonlatosak:
Mindketteje vak volt.
Szemfényeiket tán
Lelkök lobogó tüze, önnön
Dicsőségök ragyogása vevé el?

Nagy szellemek ők! ha varázskezeik
Érintik a lant idegét,
Mint isten igéje, világot
Alkotnak az ember elé,
Mely bámulatos szép
És bámulatos nagy. -

Halljátok Homért?
Dalában a mennyei bolt
Egy csendes örömnek örök mosolya,
Ahonnan a hajnali bíbor
S a déli sugár aranya
Oly nyájasan ömlik alá
A tengeri szőke habokra
És bennök a zöld szigetekre,
Hol istenek űzik az emberi nemmel
Boldog vegyülésben
Játékidat, oh gyönyörű szerelem.

S látjátok amott Osziánt?
Az éjszaki tenger örök-ködü földén
Vad szikla fölött viharokkal együtt
Harsogja dalát az alaktalan éjben,
És feljön a hold,
Mint a lemenő nap,
Oly vérvörösen,
S zord fénybe borítja a rengeteget, hol
Bolygnak seregestül
A harc mezején elesett daliák
Bús szellemei.

Minden mi világos,
Minden mi virágzó
Dalodban, oh koldusok őse, Homér!
Minden mi sötét,
Minden mi sivár
Dalodba'', királyi utód, Oszián! -

Csak rajta, daloljatok egyre,
Verjétek a lantot, az isteni lantot,
Homér s Oszián!
Eljőnek az évek
Századjai s ezredei; letipornak
Mindent könyörtelenül, oh, de
Ti szentek vagytok előttök;
Mindenre a sárga halált lehelik,
Csak ősz fejetek koszorúja marad zöld!','Hol vannak a hellenek és hol a celták?
Eltűntenek ők, valamint
Két város, amelyet
A tengerek árja benyel,','Szatmár, 1847. augusztus',1847,'1847',array['Természet']::text[],'{}'::text[],false,641,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184705-95','petofi','Tarka élet','Szolgáltam én Mars uramnál
És Thalia kisasszonynál,
Mégpedig nagy tiszteletben...
Ott elcsaptak, itt elszöktem.

Gyalogoltam kutyamódon,
S jártam négylovas hintókon.
Tisztitottam más csizmáját,
S tisztitá az enyimet más.

Kujtorogtam szomjan-éhen,
Egy helyen száraz kenyéren
Rágicsáltam, más helyen meg
Tejbe-vajba fürösztöttek.

Volt már ágyam a mezetlen
Föld, kietlen rengetegben;
Háltam ismét cifra ágyon,
Finom patyolat-párnákon.

Megemeltem a sipkámat
Szolgabíró hajdujának,
S én előttem hajtogatták
Magokat a szolgabírák.

Szobalyány is szégyelt volna
Velem jőni karonfogva,
Máskor ismét úri hölgyek
Pillantásomért epedtek.

Drága, ékes uj ruhám volt,
S volt ruhámon folt hátán folt,
Zöldre raktam sárgát, kéket...
Szent atyám, be tarka élet!','Szolgáltam én Mars uramnál
És Thalia kisasszonynál,
Mégpedig nagy tiszteletben...
Ott elcsaptak, itt elszöktem.','Szatmár, 1847. augusztus',1847,'1847',array['Szerelem']::text[],'{}'::text[],false,642,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184705-96','petofi','O. B. kisasszonyhoz','Szép mulatság téged néznem,
Szőke kislyány,
Te kis bimbó az ifjuság
Rózsafáján!
Elnézném én szemed s ajkad
Untalan;
Ajkadon szived s szemedben
Lelked van.

Szíved, lelked, mind meglátom,
Ha rád nézek;
Csendes még az, mint a téli
Madárfészek.
Várj csak, várj, ha majd eljő a
Kikelet,
Mily zajos néppel telik meg
Kebeled.

És az szép, legszebb idője
Életünknek,
Amidőn a szív először
Népesül meg,
Amidőn kiséretével
Benn terem
A hatalmas nagy király, a
Szerelem.

Kísérői: öröm, bánat,
Könny, mosolygás,
Kétség, remény, és ki tudja:
Mi minden más?
E sok vendég ugy megtölti
A szivet,
Hogy ez, szegény, szinte-szinte
Megreped.

És ez a nép egyre lót-fut,
Föl s le nyargal,
Nem nyugosznak, dörömböznek
Éjjel-nappal.
És nekünk e zaj, mely soha
Nem szünik,
Oly nagyon fáj és oly nagyon
Jólesik!...

Mit mosolygasz, mit mosolygasz,
Csintalan lyány?
Amit itten magyaráztam,
Már tudod tán?
Oh nem, ezt még nem teszem föl
Felűled!
De ha így van?... annál jobban
Becsűllek.','Szép mulatság téged néznem,
Szőke kislyány,
Te kis bimbó az ifjuság
Rózsafáján!','Szatmár, 1847. augusztus',1847,'1847',array['Szerelem']::text[],'{}'::text[],false,643,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184705-97','petofi','Szép levél','Szép levél, amelyet írtál,
Életemnek élete!
Benne elméd minden fénye
S szíved minden melege.

Oly forróan fested és oly
Édesen szerelmedet,
És, ki hinné? nékem mégis
Fáj, nagyon fáj leveled.

Egy redő űlt homlokomra,
Amidőn elolvasám,
S e redő fáj, mintha késsel
Hasították volna rám.

Leveled virágbokor, de
Kígyó lappang a tövén.
Keresém és nem lelém meg,
De csipését érzem én.

Készakarva vagy nem tudva
Bántod ekkép lelkemet?
Mely téged oly véghetetlen
És csak tégedet szeret.

Ezt kellett tehát megérnem,
Hogy az üssön új sebet,
Akinek megorvosolni
Kén'' a régiebbeket.

Fuldokoltam a habokban,
S kezemet fölemelém...
S te, hogy mélyebben taszíts be,
Csak azért jöttél felém?

Jer, leány, és csendesíts le,
Jer, s nyugtass meg engemet,
Mert az első sziklakőnél
Szétloccsantom fejemet!','Szép levél, amelyet írtál,
Életemnek élete!
Benne elméd minden fénye
S szíved minden melege.','Szatmár, 1847. augusztus 20. táján',1847,'1847',array['Szerelem']::text[],'{}'::text[],false,644,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184705-98','petofi','Megbántott a rózsám...','Megbántott a rózsám nagyon,
Haragudtam érte nagyon,
Haragudtam, buslakodtam,
Mint az effélékért szoktam.
Azt gondoltam, hogy sebemet
A sirásó gyógyítja meg,
Hogy akkor zárul be sebem,
Ha megnyílik a sír nekem.

S meddig tartott ez a bajom?
Míg megcsókolt az angyalom,
Mihelyt megcsókolt angyalom,
Mindjárt nem lett semmi bajom.
Éles, hegyes tőr a szava,
S édes balzsam az ajaka.
Ilyen az a leányféle!
Mit tegyen az ember véle?','Megbántott a rózsám nagyon,
Haragudtam érte nagyon,
Haragudtam, buslakodtam,
Mint az effélékért szoktam.','Szatmár, 1847. augusztus',1847,'1847',array['Szerelem']::text[],'{}'::text[],false,645,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184705-99','petofi','Jó költőnek tartanak...','Jó költőnek tartanak, s hogy
Az vagyok, én is hiszem,
De azért te ne magasztald
Verseimet, kedvesem.

Te előtted elpirúlok,
Hogyha dícsérsz engemet,
Oh mert érzem, hozzád képest
Érzem kicsinységemet.

A legkisebb gondolatban,
Mely fejedben tündököl,
A legkisebb érzeményben,
Mely kebled dagasztja föl,

Szemed egy pillantásában,
Mely titkon felém röpül,
Egy hangodban, mely futólag
Csengi lelkemet körül,

Egy mosolygásodban is több
Költészet van, kedvesem,
Mint az ötszázötven versben,
Melyet írtam összesen.','Jó költőnek tartanak, s hogy
Az vagyok, én is hiszem,
De azért te ne magasztald
Verseimet, kedvesem.','Szatmár, 1847. augusztus',1847,'1847',array['Szerelem']::text[],'{}'::text[],false,646,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184706-100','petofi','A csillagos ég','Fekszem hanyatt a föld sötétzöld szőnyegén,
És merengve nézem a sötétkék eget;
Száll reám aranyos, ezüstös csillagfény
És koszorú gyanánt övezi fejemet.
Megfürösztém lelkem e sugárözönben,
Lemosott magáról minden földi szennyet,
S most ujjászületve a magasba röppen,
S keresi a mennyet;

Alszik az egész föld; mély és csendes álma,
Egyetlen halk dongás érinti fülemet,
Tán mellém valami kis bogárka szálla,
Vagy távoli folyam harsogása lehet,
Vagy még távoliabb felhők mennydörgése,
Mely, míg hozzám ér, ily parányivá törpül,
Vagy talán lelkemnek himnusz-éneklése
Le a csillagkörbül.

Szállj, lelkem, oh szállj az égitestek között,
És pillants keresztül rejtelmök fátyolán,
Melyet az istenség titkos ujja szövött...
Bölcsességből-e vagy csak szeszélyből talán?
Nézd meg, lelkem, mi van ott a csillagokon,
És nézd meg, mi vagyon a csillagok felett,
Azután röpűlj le hozzám gyors szárnyadon,
Hadd beszéljek veled;

Hadd kérdjem: mit láttál? van-e ott is élet?
S ha van, ily gyötrelmes, ily bús, mint a földi?
Áll-e az a kemény, szigorú itélet,
Amely jutalmat oszt és boszúját tölti?...
De mi közöm ehhez! egyet szeretnék én,
Csak egyet megtudni, arról hozz hírt nekem:
Vannak-e ott szívek és a szívek mélyén
Lángol-e szerelem?

Ha ott is szeretnek, ah ugy vágyok oda,
S hogy feljussak, forrón imádkozni fogok,
De ha a szerelem föl nem kísér oda,
Ugy isten hozzátok, ragyogó csillagok!
Ugy szebb a föld minden búbánata mellett,
S enyésszem el, ha a sírba fognak tenni!...
A szerelem mindent pótol, s a szerelmet
Nem pótolja semmi.','Fekszem hanyatt a föld sötétzöld szőnyegén,
És merengve nézem a sötétkék eget;
Száll reám aranyos, ezüstös csillagfény
És koszorú gyanánt övezi fejemet.','Szatmár, 1847. augusztus',1847,'1847',array['Természet','Szerelem']::text[],'{}'::text[],false,647,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184706-101','petofi','Csak ugy omlanak most hozzám...','Csak ugy omlanak most hozzám
A szebbnél szebb levelek!
Minap eggyel kedvesem majd
Szívem repesztette meg,
Most meg arra figyelmeztet
Egy nem ismert jóbarátom,
Hogy "vigyázzak s fussak innen,
Mert közel van a halálom.

Fussak innen! orgyilkos kéz
Fenyegeti éltemet."
Tréfa-e ez vagy valóság?
Egyik s másik is lehet.
Jóbarátom, hogyha tréfálsz,
Fordulnál más emberekhez.
Mert az ily kis tréfácskával
Engemet meg nem ijesztesz.

S ha nem tréfa? ha valóban
Tör valaki ellenem?
Úgyis jól van, majd bevárom
És megnézem emberem.
Tán valami rosz poéta,
Kinek Pegazusom lába
Ráhágott a tyukszemére,
Helikonra-ballagtába''?

Vagy valami táblabíró,
Kinek úri fejirül
Leütöttem a parókát
S a feje is leröpült?
Vagy valami vetélytársam,
Ki miattam kosarat hord,
Kit lehánytam a nyeregből
És szemébe rúgtam a port?

Hah, vagy talán mind a három
Összeesküdt ellenem?
No ha ezek megtámadnak,
Mit csináljak, istenem!
A poéta állkapcáját
Leszakítom fegyveremnek,
S ellenségimet, mint Sámson,
E szamárcsonttal verem meg!','Csak ugy omlanak most hozzám
A szebbnél szebb levelek!
Minap eggyel kedvesem majd
Szívem repesztette meg,','Szatmár, 1847. augusztus',1847,'1847',array['Elmúlás']::text[],'{}'::text[],false,648,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184706-102','petofi','Szívem','Isten, alkotál-e
Több ily szívet is már
Mint az én szivem?
Volt-e másban is már
Ily sokféle és ily
Forró érzelem?

Hű tanya ez a szív,
Nemesebb barátság
Hű tanyája ez.
Elhagyott, elaggott
Szüleim egyetlen
Lágy párnája ez.

Kert e szív, ahol leg-
Illatosb virágid
Nyílnak, szerelem!
Bánya ez, amely a
Szabadság számára
Kardvasat terem.

És mi szép, mi jó van
A kerek világon,
Melyet nem ölel,
Melyhez imádása
Nem hajolna le vagy
Nem röpülne fel?...

S egykor ez a szív is
Megszünik dobogni,
Mint a többiek;
Egykor ez a szív is
Megszünik dobogni...
Néma lesz s hideg.

Lenn a föld porában
Össze fog vegyűlni
Majd a többivel,
S tán olyannal épen,
Kit magasb indúlat
Sosem gyujta fel.

Oh nem! szívemet ne
Bírja másokéval
Ugyanaz a hely...
Vegyétek ki, hogyha
Meghalok, barátim,
S égessétek el.','Isten, alkotál-e
Több ily szívet is már
Mint az én szivem?
Volt-e másban is már','Szatmár, 1847. augusztus',1847,'1847',array['Szerelem']::text[],'{}'::text[],false,649,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184706-103','petofi','A szájhősök','Meddig tart ez őrült hangzavar még?
Meddig bőgtök még a hon nevében?
Kinek a hon mindig ajkain van,
Nincsen annak, soha sincs szivében!
Mit használtok kofanyelvetekkel?
Évrül-évre folyvást tart a zaj,
És nem ott-e, ahol volt, a nemzet?
Nincs-e még meg minden régi baj?

Tenni, tenni! a helyett, hogy szóval
Az időt így elharácsoljátok;
Várva néz rég s oly hiába néz az
Isten napja s a világ reátok.
Nyujtsátok ki tettre a kezet már
S áldozatra zsebeiteket,
Tápláljátok végre a hazát, ki
Oly sokáig táplált titeket.

Áldozat s tett, ez a két tükör, mely
A valódi honfiút mutatja,
De ti gyáva s önző szívek vagytok,
Tettre gyávák s önzők áldozatra.
Hiszem én, hogy mint a fák tavasszal,
Megifjodnak a vén nemzetek,
De ti hernyók új lombot nem adtok,
Sőt a régit is leeszitek.

S oh mi vakság! fölemelte még a
Népszerűség őket paizsára,
Az elámult sokaság, miképen
Megváltóit, karjaiba zárja.
Megváltók? ők a hon eladói,
Elveszünk ez ordítók miatt...
Rólok tudja ellenünk, hogy félünk,
Mert a félénk eb mindég ugat.

Én ugyan nem állok a sereghez,
Mely kiséri őket ujjongatva,
És ha egykor közibök vetődöm,
Nem egyébért lépek e csapatba,
Csak azért, hogy fölfordítsam majd ez
Ál nagyok győzelmi szekerét,
S haragomnak ostorával vágjam
Arcaikra a bitó jelét!','Meddig tart ez őrült hangzavar még?
Meddig bőgtök még a hon nevében?
Kinek a hon mindig ajkain van,
Nincsen annak, soha sincs szivében!','Szatmár, 1847. augusztus',1847,'1847',array['Haza','Természet']::text[],'{}'::text[],false,650,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1847-184706-104','petofi','Valahogy','Várom, várom lakodalmam
Nehezen,
No de hiszen maholnap már
Itt leszen,
Nem a világ ez az egy hét,
Lemorzsolom apródonként
Valahogy.

Szegény ember fia vagyok,
Az apám
Egy kunyhót sem, egy garast sem
Hagy reám;
Baj, baj! de nem olyan nagy baj,
Azért mi csak elélünk maj''
Valahogy.

Menyasszonyom akaratos
Kisleány,
Én sem hajtok fejet minden
Szó után,
Tüzes patak a mi vérünk,
Hanem azért csak megférünk
Valahogy.

Ma ő enged, holnap meg én
Engedek,
Igy elejét álljuk szépen
A pörnek,
És ha nappal összeveszünk,
Este majd csak kibékülünk
Valahogy.','Várom, várom lakodalmam
Nehezen,
No de hiszen maholnap már
Itt leszen,','Szatmár, 1847. augusztus',1847,'1847',array['Szerelem']::text[],'{}'::text[],false,651,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006')
